quests[27905] = { id = 27905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heckschütze!", description = "Okay, ich habe diesen Kerl weichgeklopft, wie wäre es, wenn Ihr mir helft, ihn zu erledigen?\n\nIch habe einen Fluchtplan für uns, aber dafür braucht man viel Mut und ein bisschen Glück.\n\nSeid Ihr dabei, {name}?\n\nDann folgt mir...", sourceObjective = "Benutzt das Heckgeschütz, um den Bomber von Schnottz zu verteidigen.", completion = "Das war gute Arbeit da hinten, {name}.\n\nAnscheinend sind wir sie losgeworden - wenigstens für den Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[27906] = { id = 27906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeka Blutnarbe", description = "Es gibt noch viel zu tun, um uns von dem Angriff zu erholen und auf den nächsten vorzubereiten. All unsere Späher werden sich koordinieren müssen.\n\nNeeka Blutnarbe ist unsere beste Späherin und im harschen Ödland ausgebildet worden. Sie wurde nach Westen zur Splitterspeerkreuzung geschickt, um Allianzaktivitäten zu überwachen.\n\nBegebt Euch zu Neeka, {name}. Berichtet Ihr, was in Steinard vorgefallen ist. Unterstützt sie bei allem, worum sie Euch bittet.", sourceObjective = "Sprecht mit Neeka Blutnarbe an der Splitterspeerkreuzung.", completion = "Ich hoffe, dass Euch meine Trauer amüsiert, {name}. In dieser Gegend wird das die einzige Unterhaltung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27907] = { id = 27907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebetsblume", description = "Ich bin ruiniert, {class}. Ich habe meine Stärke in Helgrum investiert, und jetzt blutet sie aus seinen klaffenden Wunden. Wunden, die zu tief sind, um zu heilen, Fleisch, das sich nicht mehr schließen will.\n\nEr murmelt vor sich hin, vor Angst, Schmerz und Fieber. Ich kann jetzt nicht von seiner Seite weichen. Nicht jetzt. Bitte, ich muss Euch voller Scham bitten, mir ein paar Kräuter zu besorgen.\n\nDie Gebetsblume, die in den Sümpfen wächst, ist eine alte Heilpflanze. Damit sollten seine Schmerzen gestillt werden können.", sourceObjective = "Sammelt 10 Zweige der Gebetsblume im Wabersumpf.", progress = "Habt Ihr die Gebetsblume dabei?", completion = "Ich werde sie zermahlen und versuchen, sie ihm einzuflößen. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[27908] = { id = 27908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse des Sumpfes", description = "Helgrums Wunden entzünden sich in dem Sumpfklima. Sie schwellen an und eitern, und erfüllen seine letzten Minuten mit Höllenqualen. Ich brauche etwas, um sie abzudecken.\n\nDie Geister gehen in diesem Sumpf um. Sie erfüllen selbst den Schlamm, formen ihn zu Brocken glatter Erde und hauchen ihm Leben ein.\n\nDie Geister des kühlen, reinen Schlicks werden ihm etwas Linderung verschaffen. Bitte sammelt ihn für mich, da ich ihn nicht allein lassen möchte.", sourceObjective = "Sammelt 10 Exemplare kräftigen Schlicks von Wabersumpfklumpen.", progress = "Helgrum atmet noch. Habt Ihr den Schlick dabei?", completion = "Wenigstens kann ich seine Schmerzen mit meinen Händen lindern, während er noch atmet. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27909] = { id = 27909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reinquell", description = "Helgrums Atemzüge werden langsamer. Seine Zeit ist gekommen.\n\nIch brauche Wasser. In den Teichen der Reinquellhöhle streifen Elementare umher. Das Wasser, das aus ihnen strömt, ist das reinste hier im Sumpf.\n\nSelbst wenn ich es wagte, von Helgrums Seite zu weichen, würde meine Axt in meiner Hand zittern. Ich flehe Euch nochmals an, Mitleid mit mir zu haben, um seinetwillen. Bringt mir die Partikel der Elementare, auf dass sein letzter Trank rein und erquicklich sein möge.", sourceObjective = "Sammelt 8 Reinquellpartikel von Reinquellelementaren.", progress = "Ihr seid zurückgekehrt.", completion = "Er kann nicht so viel trinken. Den Rest können wir vielleicht benutzen, um seinen Körper zu waschen, nachdem...\n\n<Neeka starrt frustriert, erschauert und dreht dann ihren Kopf zur Seite.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27910] = { id = 27910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späte Reue", description = "Wenn ich mich schon erniedrigen und kriechen muss, dann kann ich auch nach allem fragen, was ich kriegen kann. Es gibt einen letzten Gefallen, um den ich Euch bitten würde - nur noch eine Aufgabe, um die ein beschämter Orc Euch bittet.\n\nHelgrum hatte eine Beute, die er über alles schätzte. Dämmerfang, der Ogerfresser, der große Panther des Nebligen Tals. Er hat sich niemals die Muße genommen, ihn zu verfolgen. Obwohl er ihn unbedingt jagen wollte, so waren doch unsere Späherpflichten zu wichtig.\n\nWenn er Dämmerfang nicht in dieser Welt jagen kann, so soll er ihn in der nächsten jagen können. Nehmt die Jagd für ihn auf und bringt mir Dämmerfangs Balg.", sourceObjective = "Besorgt Dämmerfangs Balg.", progress = "Hat Dämmerfang sich gezeigt?", completion = "Jetzt, da Dämmerfang seinen Körper umhüllt, wird er den Geist des Tieres mit ins Jenseits nehmen.\n\nHört auf mich. Einen abergläubischen, alten Narren. Es tut mir so leid, Helgrum...", sourceObjectiveStatus = "unverified-source-field" }
quests[27911] = { id = 27911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Atemzug", description = "Er regt sich...\n\nBitte bleibt bei mir, {name}. Lasst uns gemeinsam Helgrum ehren. Ihr habt so viel für ihn getan.", sourceObjective = "Begleitet Helgrums letzte Momente auf Erden.", completion = "Er ist von uns gegangen.\n\nEr hat Recht. Ich muss stark für ihn sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[27912] = { id = 27912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Titanen", description = "Als der zweite Verteidiger zu Boden fällt, erscheint im hinteren Teil der Kammer eine Kiste. Könnte es das sein, was sie beschützt haben?", sourceObjective = "Untersucht den Schatz der Behüter.", completion = "Ihr werft einen Blick in die Kiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[27913] = { id = 27913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Titanen", description = "Als der zweite Verteidiger zu Boden fällt, erscheint im hinteren Teil der Kammer eine Kiste. Könnte es das sein, was sie beschützt haben?", sourceObjective = "Untersucht den Schatz der Behüter.", completion = "Ihr werft einen Blick in die Kiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[27914] = { id = 27914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Grünen Drachenschwarms", description = "Ihr habt gute Arbeit geleistet, {name}. Jammal'an ist uns zwar entkommen, aber sein Rückzug erlaubt es mir, den Tempel nach Belieben zu betreten.\n\nBleibt, wo Ihr seid und bewegt Euch nicht. Ich werde Eure Rückkehr beschleunigen, indem ich Euren Geist durch den Smaragdgrünen Traum zu mir bringe.\n\nDabei wird Euch vielleicht etwas schwindelig.", sourceObjective = "Sprecht mit Lord Itharius an der Spitze des Tempels von Atal'Hakkar.", completion = "Ihr habt mir und meinem Volk einen großen Dienst erwiesen, {name}. Nehmt dies als Symbol meines Dankes und Eures Mutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27915] = { id = 27915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Tempels", description = "Ich muss gestehen, dass ich persönlich in diese Angelegenheit verwickelt bin. Einer der ersten grünen Drachen, die hier verderbt wurden, war mein Bruder Eranikus.\n\nIch dachte, dass Eranikus tot sei, für immer von den düstersten Rissen des Alptraums verschluckt. Doch nun habe ich gehört, dass sein Schemen im Tempel aufgetaucht ist. Ich weiß nicht, ob er es wirklich ist oder nur ein leeres, schwermütiges Echo seiner selbst.\n\nWenn Ihr mir weiter helfen wollt, kehrt zur Halle der Masken zurück und reist durch den Bogengang in das wahre Sanktum des Tempels. Ich werde dort auf Euch warten.", sourceObjective = "Sprecht im Inneren des Tempels von Atal'Hakkar erneut mit Lord Itharius.", completion = "Ich freue mich, Euch wiederzusehen, {name}. Es ist sehr ehrenhaft von Euch, dass Ihr mich weiterhin unterstützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27916] = { id = 27916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruags Bericht", description = "Hier ist Ruags Bericht, {name}. Sagt ihm, dass sein Kundschafter immer noch hier ist.\n\nErwähnt Helgrum nicht. Niemand sonst soll durch diese tragische Nachricht abgelenkt werden.\n\nIch selbst muss stark sein. Wir alle müssen stark sein.", sourceObjective = "Überbringt Zentralenkommandant Ruag in Steinard den Splitterspeerbericht.", progress = "Ja?", completion = "<Ruag überfliegt den Bericht.>\n\nIch verstehe. Danke für diese Informationen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27917] = { id = 27917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschnüffelt sie", description = "Ich konnte Godfrey und seine Kameraden schon kilometerweit riechen. Sie haben ihre Spuren auf der Flucht nicht gerade gut verwischt. Ein Fehler, der sie in ihr Grab bringen wird.\n\nEiner von ihnen ist sehr nah und obwohl sich ihr Geruch im Untod verändert hat, bin ich sicher, dass es Ashbury ist. Geht hinein und reißt ihn in Stücke! Wir stellen sicher, dass die Verlassenen uns bei unserer Aufgabe nicht in die Quere kommen.", sourceObjective = "Tötet Baron Ashbury.", progress = "Tötet Ashbury bevor mir noch der Kragen platzt. Ihr würdet mich nicht mögen, wenn ich wütend bin...", completion = "Der Duft von frisch vergossenem Verräterblut füllt meine Nase und er ist überaus belebend. Mein Kampfrausch wird aber erst verebben, wenn Godfrey als lebloser Haufen im Staub liegt.\n\nEr glaubt, eine Armee lebloser Kadaver kann den Zorn der Blutfangworgen aufhalten? Wir werden ihre Knochen noch jahrelang abnagen, nachdem unser Werk hier vollbracht ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[27918] = { id = 27918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sichere Hafen", description = "Anachoret Avuun ist einer unserer nicht verderbten Brüder, die anderen Völkern als Draenei bekannt sind. Er kam in den Sicheren Hafen, um uns zu heilen und zu versuchen, ein Gegenmittel zu finden. Er war es, der mich hierhergeschickt hat, um diese Kristalle zu sammeln.\n\nEr kümmert sich gerade um einen sehr kranken Freund, und obwohl er sogar an die Exodar selbst Nachricht entsandt hat, findet er niemanden, der ihn unterstützt. Könntet Ihr ihm diese Kristalle bringen, {name}? Ihr seid vielleicht <der Einzige, der/die Einzige> die; ihm helfen kann.", sourceObjective = "Bringt die Draenethystkristalle zu Anachoret Avuun.\n\nBereitgestellter Gegenstand:", completion = "Vielen Dank, {class}. Ich fürchte, dass es zu spät sein könnte... aber ich weigere mich aufzugeben, selbst wenn die Exodar mein Flehen nicht erhört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27919] = { id = 27919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter in die Verwüsteten Lande", description = "Wir wissen Eure Hilfe hier in diesem Sumpf zu schätzen, {name}. Ich muss Euch mitteilen, dass ich ein Schreiben aus Burg Nethergarde erhalten habe.\n\nEnohar Donnerbräu bittet um Hilfe bei der Untersuchung der Schiffswracks in den Roten Weiten, doch niemand will diese Reise unternehmen. Ich selbst kann den Sicheren Hafen leider nicht verlassen.\n\nBurg Nethergarde liegt in den Verwüsteten Landen, südlich der Sümpfe des Elends. Kommt Steinard auf Eurer Reise nicht zu nah.", sourceObjective = "Reist in die Verwüsteten Lande und sprecht mit Enohar Donnerbräu in Burg Nethergarde.", completion = "Ah, schickt Euch Avuun? Gut, gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[27920] = { id = 27920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis an die Zähne bewaffnet", description = "Bei unserem Angriff auf die Burg sind wir auf unvorhergesehene Hindernisse getroffen, {name}. Es scheint, als würden die Diener, die Baron Silberlein und Kommandant Grüntal im Leben umsorgten, dies auch noch im Tode tun, und Godfrey hat sie direkt zwischen sich und uns platziert.\n\nKeine Sorge, wir werden nicht zulassen, dass sie mehr als eine kleine Unannehmlichkeit darstellen. Vernichtet sowohl Silberlein als auch Grüntal. Es wird die Wächter nicht nur ihrer Meister berauben, die ihnen Anweisungen geben, es wird uns auch unserem finalen Ziel sehr viel näher bringen.", sourceObjective = "Tötet Baron Silberlein und Kommandant Grüntal.", progress = "Es ist zum Verrücktwerden, dass wir diese Geistersoldaten töten müssen, obwohl sie rein gar nichts mit dem eigentlichen Missionsziel zu tun haben. Godfrey ist in der Tat ein gerissener Gegner.", completion = "Wir haben es fast geschafft, {name}. Die Zeit ist gekommen, den letzten Vorstoß zu machen und Walden das Handwerk zu legen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27921] = { id = 27921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Klauen und Zähnen", description = "Es scheint, als hätte Lord Walden unsere Anwesenheit endlich bemerkt und seine Verteidigung verstärkt. Verschwendete Liebesmüh... nichts wird unser Rudel aufhalten.\n\nDer Weg zu ihm ist voller Diener der Geißel, doch ich vertraue darauf, dass Ihr ihn freimachen könnt, damit der Rest von uns folgen kann. Sobald wir Walden getötet haben, sollten wir direkt zu seinem feigen Anführer vordringen können.", sourceObjective = "Tötet Lord Walden.", progress = "Wir stehen voll hinter Euch, {name}.", completion = "<Rudelführer Ivar Blutfang grinst Euch an, wobei er seine rasiermesserscharfen Zähne entblößt.>\n\nDank Eurer wackeren Hilfe dauert es jetzt nicht mehr lang, bis die Burg uns gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27922] = { id = 27922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter!", description = "Bitte, <Fremder/Fremde>. Ihr müsst mir helfen.\n\nIch bin hierhergekommen, um die Ankunft eines mächtigen Verbündeten der Neferset zu untersuchen. Dabei wurde ich von meinen engsten Verbündeten verraten und dem Feind überlassen.\n\nGeht zu der Terrasse über uns im Osten und sucht die Information, die ich nicht finden konnte. Ihr müsst Euch vor den Neferset verbergen. Vielleicht könnt Ihr Euch hinter einer der großen Pflanzen auf der Plattform verstecken, um Eure Anwesenheit geheim zu halten.\n\nErledigt das für mich und ich werde Euren Freunden dabei helfen, in Sicherheit zu gelangen.", sourceObjective = "Versteckt Euch hinter einem Wedel der Neferset und enthüllt das Geheimnis der Neferset.", completion = "Einen Dschinn! Wir müssen hier so schnell wie möglich weg.\n\nDiese unheilige Allianz der Neferset mit den Helfern von Todesschwinge bedeutet nichts Gutes für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[27923] = { id = 27923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauch in ihren Augen", description = "Ich weiß zwar nicht, was für einen behämmerten Plan Euer Freund da ausbrütet, aber wir werden eine Ablenkung brauchen, wenn wir eine Chance haben wollen, zu entkommen.\n\nNehmt die Fackel von der Kohlenpfanne und legt ein paar Feuer.\n\nVielleicht gelingt es uns dadurch, den Neferset-Abschaum für ein paar Minuten abzulenken und das gibt uns die Gelegenheit, die wir brauchen.", sourceObjective = "Verbrennt Heuhaufen in der Verlorenen Stadt der Tol'vir in Uldum.", completion = "Ja. Ich höre, wie die Neferset sich gegenseitig nach Osten rufen. Das könnte noch klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27924] = { id = 27924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Budds Plan", description = "Ich hab' 'ne Idee! Vertraut mir, diesmal ist es eine gute!\n\nBesorgt einige dieser glänzenden Rüstungsteile, die die Katzenmenschen tragen.\n\nDieser Plan kann nicht schiefgehen. Vertraut mir.", sourceObjective = "Besorgt 6 Rüstungen der Neferset.", progress = "Habt Ihr die Teile, {name}?", completion = "Ausgezeichnet. Ihr werdet schon sehen, das kann unmöglich schiefgehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27925] = { id = 27925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effiziente Ausgrabungen", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nEs wird deutlich, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist. \n\nVielleicht wäre es angebracht, sich einmal vorzustellen.", sourceObjective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[27926] = { id = 27926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gastfreundschaft des Ostens", description = "Der Kommandant ist gerade sehr beschäftigt, fürchte ich.\n\nDie Anforderungen solch einer Operation nehmen dieser Tage fast seine ganze Aufmerksamkeit in Anspruch.\n\nWas haltet Ihr davon, Euch ein wenig unter unsere Gäste zu mischen, während Ihr darauf wartet, mit ihm zu sprechen?\n\nWir haben eine Auswahl der berühmtesten Einwohner Azeroths eingeladen, um der Enthüllung der Geheimnisse dieser Region beizuwohnen.\n\nIch bin davon überzeugt, dass Ihr sie ausgesprochen faszinierend finden werdet.", sourceObjective = "Bellok Leuchtklinge möchte, dass Ihr Euch unter die Gäste in Schnottz' Landeplatz mischt.", completion = "Ich gehe davon aus, dass Ihr keine Schwierigkeiten hattet, mit unseren Gästen auszukommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27927] = { id = 27927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinunter zur Narbe", description = "Das Ödland beherbergt einige ungewöhnliche Leute, viele davon halten sich hier schon seit geraumer Zeit auf. \n\nDa waren zum Beispiel drei Herren, die hier in der Stadt lebten. Ich vergesse immer ihre Namen... Der Zwerg hieß glaube ich Theldurin. Jedenfalls sind sie vor einigen Tagen mit einem Rucksack voller Bier nach Süden aufgebrochen und seitdem habe ich nichts mehr von ihnen gehört. Ich glaube, sie wollten zu der großen Narbe.\n\nWürde es Euch etwas ausmachen, nach ihnen zu sehen? Ich wüsste gerne, dass es ihnen gut geht.", sourceObjective = "Findet Theldurin den Verirrten nahe der Narbe des Weltenbrechers im Ödland.", completion = "Man hat Euch geschickt, um nach uns zu sehen? Pfft... Ich lebe schon länger in dieser Wüste als die meisten dieser Trottel. Wir lassen nur die Landschaft auf uns wirken und erzählen uns Geschichten über alte Zeiten.\n\nErzählt Ihr gerne Geschichten?", sourceObjectiveStatus = "unverified-source-field" }
quests[27928] = { id = 27928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feines für den Fellhändler", description = "Der Kommandant kann zu denen, die ihm Loyalität erweisen, sehr großzügig sein. Ich wüsste da etwas, das Ihr tun könnt, um Euch bei ihm beliebt zu machen.\n\nBevor er seine... äh... Belegschaft aufgebaut hat, handelte er mit Tierfellen.\n\nEr ist in der Kunst der Lederverarbeitung sehr bewandert. Der Fellhändler kann sogar bei den zerlumptesten Fellen noch Wunder bewirken.\n\nDie ausgetrocknete Oase im Osten beheimatet angeblich eine seltene Koyotenrasse.\n\nIhre Felle wären ein wunderbares Geschenk.", sourceObjective = "Erbeutet 5 Felle eines Wüstenkoyoten.", progress = "Hattet Ihr Erfolg auf der Jagd?", completion = "Oh, die sind vorzüglich!\n\nDer Kommandant wird daraus eine Winteruniform herstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27929] = { id = 27929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt sie 'runter", description = "Ein einziger Drache des Drachenmalklans wiegt ein Dutzend Wildhammergreifenreiter auf. Holt sie von ihren verlausten Vögeln und sie sind nichts mehr wert.\n\nSogar Ihr könnt sie dann mit Leichtigkeit töten, Horden-{class}.\n\nJagt Greifenreiter, die über den Fluss nördlich von Blutschlucht fliegen. Nehmt diesen Haken und werft ihn auf sie, während sie vorüberfliegen. Durch ihren Schwung werden sie von ihrem Reittier genau vor Eure Füße geschleudert. Tötet sie! Tötet einige Donnermar-Greifenreiter und ich werde glauben, dass Eure Horde so mächtig ist, wie Ihr behauptet.", sourceObjective = "Benutzt den gestachelten Fleischerhaken, um 4 Donnermar-Greifenreiter von ihren Reittieren zu holen und tötet sie dann.", completion = "Ihr seht leicht angeschlagen aus. Diese Zwerge haben Euch keine Schwierigkeiten bereitet, oder doch?\n\nEs war dennoch eine beeindruckende Vorstellung.", sourceObjectiveStatus = "unverified-source-field" }
quests[27930] = { id = 27930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüstung", description = "Die Luft ist rein. Wenn Rheastrasza oder das Ei durch ein Wunder Todesschwinges Flammen überlebt haben, werden sie so bald wie möglich Eure Hilfe benötigen.", sourceObjective = "Sucht nach Rheastrasza.", completion = "Helden:\n\nWenn Ihr das hier lest, war mein Verdacht berechtigt. Todesschwinge hat uns gefunden. Das Ei ist zerstört - ebenso wie ich.\n\nDas war allerdings von Anfang an der Plan. Ihr müsst wissen... Das Ei, das Todesschwinge zerstörte, war nicht das Ei, das er suchte.\n\nEs war meins.", sourceObjectiveStatus = "unverified-source-field" }
quests[27931] = { id = 27931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bebenden Felder", description = "Bevor Ihr uns hier helfen könnt, müssen wir uns erst um die Streitkräfte Therazanes, der Steinmutter, im Süden kümmern. Die Elementare und Riesen der Bebenden Felder werden momentan zusammengestellt.\n\nAuch sie sind auf der Suche nach dem mittleren Fragment der Weltensäule. Sie werden uns mitten in unserem Krieg mit den Steintroggs angreifen und wir werden sie nicht abwehren können.\n\nIch habe den Erzgeomanten bereits vorgeschickt. Geht zu Schiefer Treibsand und tut, was er sagt.", sourceObjective = "Sprecht mit Schiefer Treibsand im Zerschmetterten Feld in Tiefenheim.", completion = "Gut, dass Ihr hier seid, {race}.\n\nWir müssen schnell handeln, um die Streitmächte Therazanes vom Angriff abzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27932] = { id = 27932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Axt der irdischen Trennung", description = "Die Smaragdkolosse sind die größten Kreaturen der Steinmutter. Sie müssen als erstes von dem Feld entfernt werden.\n\nIch habe Steinvater Erzmantels Axt für diesen Zweck mitgebracht. Benutzt sie, um die Riesen zu spalten.\n\nDadurch bekommen sie eine leichter zu handhabende Größe. Dann könnt Ihr sie töten.", sourceObjective = "Tötet 5 gespaltene Smaragdkolosse.", completion = "Danke, {name}. Ohne all ihre Riesen werden Therazanes Streitkräfte es schwerer haben, Steinruh einzunehmen.\n\nWenn Ihr jetzt bitte meine Axt zurückgeben würdet. Ich werde darauf aufpassen, bis Ihr den Steinvater retten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27933] = { id = 27933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarerz", description = "Ihr werdet Euch hier mit dem Anführer von Therazanes Streitkräften auseinandersetzen müssen. Um aber schnell und sicher zu ihm zu gelangen, muss ich ein Ritual durchführen.\n\nGeht hinaus aufs Feld und sammelt Elementarerz von den Jadewütern. Wenn wir genug davon haben, sollte ich in der Lage sein, Euch eins mit der Erde werden zu lassen, damit Ihr dorthin gelangt, wo Ihr hin müsst.", sourceObjective = "Sammelt 6 Elementarerze.", progress = "Habt Ihr alles Notwendige?", completion = "Das sollte reichen. Ich benötige nur einen Moment für die Vorbereitung des Rituals.", sourceObjectiveStatus = "unverified-source-field" }
quests[27934] = { id = 27934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eins mit der Erde", description = "Der hiesige Anführer der Streitkräfte der Steinmutter ist ein großer Erdelementarlord namens Lavinius. Zum Glück für uns haben die Kultisten des Schattenhammers beschlossen, in seine Höhle einzumarschieren. Ihr Ziel ist es, seine Elementare ihrem Willen zu unterwerfen.\n\nAus diesem Durcheinander werden wir einen Vorteil schlagen. Das Erdritual, das ich beschwöre, wird Euch eins mit der Erde werden lassen. Es wird Euch in die Nähe von Lavinius versetzen, ohne dass er Eure Gegenwart bemerkt.\n\nDann ist es an Euch, ihn zu beseitigen.", sourceObjective = "Beendet das 'Eins mit der Erde'-Ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27935] = { id = 27935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lawine ins Rollen bringen", description = "Lavinius steht vor Euch. Tötet ihn, um Therazanes Streitkräfte von einem Angriff auf Steinruh abzuhalten.", sourceObjective = "Tötet Lavinius.", completion = "Ihr habt etwas getan, zu dem nur wenige fähig gewesen wären. Lavinius besiegt zu haben ist eine große Leistung.\n\nIch bin beeindruckt, {name}. Werdet Ihr uns bei unserem Krieg gegen die Steintroggs helfen, damit wir den Steinvater retten können?", sourceObjectiveStatus = "unverified-source-field" }
quests[27936] = { id = 27936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lawine ins Rollen bringen", description = "Ihr müsst zurückgehen und Lavinius töten, um Therazanes Streitkräfte von einem Angriff auf Steinruh abzuhalten!", sourceObjective = "Tötet Lavinius.", sourceObjectiveStatus = "unverified-source-field" }
quests[27937] = { id = 27937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held kehrt zurück", description = "Der Steinvater wartet auf Euch in Steinruh im Süden.\n\nPutzt Euch ein wenig heraus. Ihr habt Euch den Empfang eines Helden verdient!", sourceObjective = "Stellt Euch bei Steinvater Erzmantel in Steinruh in Tiefenheim vor.", completion = "Unser Held kehrt zurück!\n\nIhr habt mein Volk gerettet, {name}. Ihr habt Euch das, was Ihr sucht, redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[27938] = { id = 27938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das mittlere Fragment", description = "Ich überreiche Euch hiermit den Schlüssel von Steinruh. Mit ihm dürft Ihr die Schatzkammer in meiner Heimstatt aufschließen und das mittlere Fragment der Weltensäule herausnehmen.\n\nAchtet gut auf das Fragment, {name}. Stellt sicher, dass Ihr es so schnell wie möglich zum Tempel der Erde in Tiefenheim zurückbringt!\n\nIhr sollt wissen, dass Ihr hier immer willkommen sein werdet.", sourceObjective = "Bringt das mittlere Fragment der Weltensäule in Euren Besitz.", progress = "Ihr seid zurückgekehrt. Habt Ihr das mittlere Fragment geborgen?", completion = "Das mittlere Fragment der Weltensäule!\n\nIch danke Euch, {name}. Ich kann mir nur schwer vorstellen, was Ihr durchmachen musstet, um das hier zu uns zurückzubringen. Ich werde dafür sorgen, dass es in der Mitte der Kammer aufgestellt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27939] = { id = 27939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wüstenfuchs", description = "In dieser Region muss einiges getan werden, {race}.\n\nWir haben beide eine brennende Leidenschaft für uralte Technologien, nicht wahr? Vielleicht können wir ja irgendwie zusammenarbeiten?\n\nLassen wir die Missverständnisse der Vergangenheit einfach ruhen, hmm?\n\nNun, da ist ein sehr scheues Tier Richtung Osten, das ich zu jagen versucht habe. Bringt mir diese Kreatur als Zeichen Eurer Aufrichtigkeit, hmm?\n\nDann weihe ich Euch vielleicht in meine Operation ein...", sourceObjective = "Schnottz will, dass Ihr ihm den Wüstenfuchs bringt.", progress = "Habt Ihr den Wüstenfuchs gefangen, {class}?", completion = "Ihr habt es geschafft!\n\nVielleicht kann ich Euch mit wichtigeren Aufgaben betrauen, hmm?", sourceObjectiveStatus = "unverified-source-field" }
quests[27940] = { id = 27940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Vögel", description = "Der Himmel über der Verdorrten Oase ist voll mit diesen hässlichen Geiern.\n\nSie sind wie mit Krankheiten befallene Ratten mit Flügeln. Sie dienen keinem bedeutsamen Zweck und bringen unsägliches Leid.\n\nSäubert den Himmel von dieser Plage und hinterlasst die Region besser, als Ihr sie vorgefunden habt.", sourceObjective = "Ihr sollt 8 kranke Geier töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27941] = { id = 27941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modeismus", description = "Wir haben einen unerschütterlichen Grundsatz in unseren Rängen, den wir sehr ernst nehmen.\n\nUnsere Truppen müssen zu jeder Zeit in offizielle Uniformen gekleidet sein. Das hilft bei der Organisation - Beschuss durch die eigenen Streitkräfte kommt nicht so oft vor und die Truppen sehen immer großartig aus!\n\nWir nennen das Modeismus.\n\nIn letzter Zeit gehen uns aber die Uniformen aus. Ich muss Euch darum bitten, sie von den Soldaten, die während ihrer Pflichterfüllung gefallen sind, zu bergen.\n\nIhr solltet reichlich arme Kerle östlich von hier bei den Ruinen von Ammon finden.", sourceObjective = "Bellok Leuchtklinge möchte, dass Ihr 10 Gardistenuniformen aufsammelt.", progress = "Konntet Ihr die Uniformen, die wir benötigen, beschaffen?", completion = "Das ist sehr gute Arbeit, {class}.\n\nIhr solltet schnell bei uns im Rang aufsteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27942] = { id = 27942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzendienst", description = "Ich habe etwas, um das Ihr Euch kümmern müsst, {race}.\n\nMein engster Vertrauter ist von einem uralten Fluch befallen. Es handelt sich um einen Fluch, der ihn ausgerechnet in einen Truthahn verwandelt hat!\n\nIch habe tagelang nach einem Heilmittel gesucht und bin nun endlich so weit, das Ritual durchzuführen.\n\nIch werde einige Götzen aus den nahegelegenen Ruinen benötigen. Ihr werdet sie mir umgehend beschaffen!\n\nWeggetreten!", sourceObjective = "Kommandant Schnottz möchte, dass Ihr 8 gut erhaltene Götzen einsammelt.", progress = "Habt Ihr die Götzen für mich, {race}?", completion = "Diese Stücke scheinen mir von ausreichender Qualität zu sein.\n\nDamit kommen wir dem Reinigungsritual einen Schritt näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[27943] = { id = 27943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verärgerte Geister", description = "Doktor Wenkmann war einer meiner besten Forscher, bis ich von seinem Elend erlöst werden musste.\n\nEr hat mir aber eine seiner größten Errungenschaften hinterlassen. Gegen einen richtig abgestimmten, übernatürlichen Gegner wird diese Waffe die Essenz des Ziels abzapfen.\n\nDas ist von entscheidender Bedeutung bei dem Ritual, das ich durchführen werde.\n\nWo Ihr ins Spiel kommt, fragt Ihr? Ganz einfach. Ihr habt das Privileg, das Material zu sammeln.\n\nDie Waffe ist darauf kalibriert, bei den wütenden Schreckgespenstern im Tempel im Osten zu funktionieren.", sourceObjective = "Kommandant Schnottz möchte, dass Ihr die L.P.B.K. benutzt und 5 wütende spektrale Essenzen einsammelt.", progress = "Also, junger Mann? Wart Ihr erfolgreich?", completion = "Sehr gut!\n\nIhr habt Euch die Teilnahme an dem Ritual redlich verdient.\n\nIhr werdet einer der Ersten sein, die Gubbel wieder in seiner... ursprünglichen Form willkommen heißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27944] = { id = 27944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnen der Brut", description = "Seit Wochen versuchen wir schon, im Finsterwald Fuß zu fassen, aber dort wimmelt es nur so von Spinnen. Tut mir einen Gefallen und schaut, ob Ihr ihre Zahl so weit eindämmen könnt, dass wir einen Angriff starten können.\n\nDoch seid vorsichtig da draußen. Mir wurde berichtet, dass Anfang der Woche Hordetruppen dort gesichtet wurden.", sourceObjective = "Tötet 12 Dunkelwaldlauerer im Finsterwald. Der Finsterwald liegt direkt westlich von hier, jenseits der Brücke auf der mittleren Insel.", completion = "Den Spinnen habt Ihr es gezeigt, {name}. Wenn wir so weitermachen, ist der Wald im Handumdrehen unser.", sourceObjectiveStatus = "unverified-source-field" }
quests[27945] = { id = 27945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzmalerei", description = "Die Erde blutet, {class}. Sie reißen sie auf, wie man Fleisch aufreißen würde.\n\nDiese Kultisten finden großen Gefallen an ihrer Geheimniskrämerei, aber eben die Elementare, die sie für ihre Untaten benutzen, könnten sie verraten. Sucht die Obsidiansteinsklaven im Nordosten von hier in der zerstörten Erde, die wir den Schwarzen Riss nennen.\n\nZerschmettert ihre Körper und sucht für mich ein perfektes Herz aus schwarzem Diamant. Ich werde in sein Herz blicken. Und ich werde seine Seele entblößen.", sourceObjective = "Besorgt ein schwarzes Diamantherz.", progress = "Das Herz. Ein Steinherz in tiefstem Schwarz. Habt Ihr eins gefunden?", completion = "<Mallia nimmt ihre Augenklappe ab und hält den Diamanten vor ihre leere Augenhöhle.>\n\nWas haben wir, was haben wir - Bresche, Bresche Nummer Drei. Zwei Köpfe, einer ganz seinem Meister gegeben. Ich sehe die Zukunft. Ein vereinigter Hammer. Ein zerschmetterter Berg. Oh - OH!\n\n<Mallia lässt den Diamanten zu Boden fallen und bedeckt ihr Gesicht mit den Händen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27947] = { id = 27947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vision des Zwielichts", description = "Cho'gall behält seine Handlanger durch mächtige magische Kugeln im Blick: \"Die Augen des Zwielichts\"\n\nIn Hyjal haben die Wächter von Hyjal es geschafft, eine zu finden und für ihre Zwecke zu verändern. Das müssen wir auch tun. Ich will eine dieser Kugeln und ich will sie benutzen, um hineinzuschauen und mitten in Cho'galls Versteck zu blicken.\n\nDurchsucht den Schwarzen Riss jenseits des Flusses im Nordosten und findet ein Auge des Zwielichts. Tut alles Notwendige, um es zu mir zurückzubringen!", sourceObjective = "Spürt ein Auge des Zwielichts in dem Schwarzen Riss auf.", completion = "<Das Auge liegt vor Euch und summt unheilvoll vor dunkler Energie.>\n\n<Ohne Warnung dreht sich die Kugel, als sehe sie Euch an. Ihr spürt die Anwesenheit des Bösen, als sei die Kugel lebendig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27948] = { id = 27948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine klebrige Angelegenheit", description = "Auf dieser Insel Vorräte zu sammeln, hat sich, gelinde gesagt, als schwierig erwiesen.\n\nGlücklicherweise haben wir ein gutes Angebot an Seide im Finsterwald, direkt westlich von hier, ausmachen können. Der unschöne Teil an der Sache ist, dass die Seide aus den Drüsen von Brutmutterspinnen gewonnen werden muss. Ich möchte, dass Ihr mir vier davon besorgt.\n\nDas sollte genügen, um die letzte Ladung Hemden fertigzustellen.", sourceObjective = "Sammelt 4 klebrige Seidendrüsen von Finsterwaldbrutmutterspinnen im Finsterwald. Der Finsterwald liegt westlich von hier, über die Brücke hinweg, auf der zentralen Insel.", progress = "Konntet Ihr die klebrigen Seidendrüsen bekommen?", completion = "Diese Drüsen sind genau richtig. Wir sind für Eure Hilfe dankbar, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27949] = { id = 27949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergessenen", description = "Viele Soldaten sind auf dieser Insel gestorben, {name}. Es ist nur rechtens, dass wir ihnen auf jede mögliche Art und Weise unseren Respekt erweisen.\n\nIch möchte, dass Ihr zum Vergessenen Hügel reist, der westlich von hier liegt, und die Seelen unserer geknechteten Waffenbrüder von hier fort geleitet. Seid bitte vorsichtig da draußen, uns haben Berichte über Machenschaften der Untoten in dem Bereich erreicht.", sourceObjective = "Schenkt den Geistern von 6 gequälten Seelen die Freiheit am Vergessenen Hügel. Die Seelen können kanalisiert werden, indem Ihr mit den Händen die Grabsteine berührt. Der Vergessene Hügel liegt direkt westlich von hier, vorbei am Finsterwald und der Rastlosen Front.", completion = "Mögen ihre Seelen in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27950] = { id = 27950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gubbel!", description = "Endlich! Die Zeit ist gekommen, meinen Gubbel von diesem furchtbaren Fluch zu befreien!\n\nPasst gut auf, {race}, und seid auf der Hut. Es darf keine Unterbrechungen während des Rituals geben.\n\nSagt mir Bescheid, wenn die Umgebung sicher ist!\n\nBewegung!", sourceObjective = "Schnottz möchte, dass Ihr ihn ansprecht, wenn Ihr bereit seid, dem Ritual beizuwohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27951] = { id = 27951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen alle Opfer bringen", description = "<Das Auge spricht mit Euch; seine 'Stimme' scheint aus allen Richtungen zugleich zu erschallen.>\n\nIhr wünscht einen Blick durch mich zu werfen, {race}? Meine Macht ist nur für einen bestimmten Preis zu haben. Diese Jünger des Zwielichts haben mich mit dem Blut der Wildhammerzwerge beehrt, aber ich verspüre immer noch Durst. Vielleicht könntet Ihr es besser machen.\n\nTötet meine alten Herren und meine Visionen gehören Euch. Ehrt mich, indem Ihr Schamanen der Schwärze tötet. Schließlich ist ein Blut so gut wie das andere.", sourceObjective = "Tötet 10 Schamanen der Schwärze.", completion = "<Das Auge schimmert dunkel, Farben wirbeln über seine düstere Oberfläche.>\n\nAh, die wohlschmeckende Spannung ausgelöschten Lebens. Könnt Ihr das fühlen, {class}? Gefällt es Euch so gut wie mir?\n\nNein, wie ich sehe, nicht. Ihr kämpft, um das Leben anderer zu beschützen. Schade.", sourceObjectiveStatus = "unverified-source-field" }
quests[27952] = { id = 27952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Forscher", description = "Eine Gruppe der Forscherliga befindet sich in der Kammer im Nordwesten im Tempel.\n\nNun machen sie immer lauteres Geschrei über etwas, das der Schattenhammer anstellt.\n\n{name}, würdet Ihr ein Schatz sein und nachsehen, was sie brauchen?", sourceObjective = "Sprecht mit Entdeckerin Mowi im Tempel der Erde in Tiefenheim.", completion = "Donnerwetter! Es ist endlich jemand hier, um uns zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27953] = { id = 27953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Archäologische Akademie", description = "Eine Gruppe der Archäologischen Akademie befindet sich in der Kammer im Nordosten im Tempel.\n\nNun machen sie immer lauteres Geschrei über etwas, das der Schattenhammer anstellt.\n\n{name}, würdet Ihr ein Schatz sein und nachsehen, was sie brauchen?", sourceObjective = "Sprecht mit Prüfer Rowe im Tempel der Erde in Tiefenheim.", completion = "Ah, es wurde auch langsam Zeit, dass jemand herkommt, um mit uns über Angelegenheiten größter Dringlichkeit zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27954] = { id = 27954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Auge des Betrachters", description = "Also gut, {race}. Ihr habt Euch meine Dienste mit Blut erkauft. Bringt mich zu Garona der Halborcin zurück.\n\nOh ja, ich weiß bereits, wo Ihr mich hinbringt. Garonas unablässige Suche nach Rache ist kein Geheimnis. Es wird ein Genuss sein, dabei zuzusehen, wie sie sich entfaltet.", sourceObjective = "Bringt das Auge des Zwielichts zu Garona der Halborcin in der Blutschlucht im Schattenhochland.", progress = "Hattet Ihr Glück im Schwarzen Riss?", completion = "Ihr habt eins gefunden? Ich habe überall gesucht. Gebt es her!\n\nEinige dieser Augen kann man mit Rätseln oder Versen für sich gewinnen. Bei anderen benötigt man Magie. Was hat dieses hier verlangt? Ah, das spielt keine Rolle. Es zählt nur, dass es uns gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27955] = { id = 27955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe was, was Ihr nicht seht...", description = "Dieses furchtbare Ding lässt mir die Haare zu Berge stehen. Cho'gall benutzt diese Dinger, um seine Gehilfen zu überwachen - jetzt ist es an der Zeit, dieses gegen ihn zu verwenden.\n\nSchauen wir mal... hmm, es ist ganz milchig. Ich sehe nur Euch. Warum zeigt es mir Euch?\n\n<Garona stellt das Auge vor sich hin.>\n\nSchaut in das Auge und sagt mir, was Ihr seht. Werft einen Blick in Cho'galls Versteck! Was macht er? Ist er schwer bewacht? Sagt es mir!", sourceObjective = "Blickt für Garona in das Auge des Zwielichts.", completion = "Ihr seid ganz blass geworden, {class}. Was hat das Auge Euch gezeigt?\n\nIhr habt Cho'gall gesehen? Moment - Cho'gall hat Euch gesehen? Er beobachtet uns? Er beobachtet uns jetzt gerade!?\n\nVerflucht sei diese blöde, dunkle Magie! Ich werde mich selbst in Cho'galls Festung einschmuggeln müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27956] = { id = 27956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunks Aufgabe", description = "Lunk kam aus dem Ödland. Andere Oger Lunk gezwungen zu kämpfen.\n\nLunk hasst kämpfen. Lunk will lernen.\n\nLunk sieht Maschinen im Süden. Maschinen sind aus Zahnrädern.\n\nVielleicht, wenn Ihr nett fragt, Maschinen geben Euch ein paar Zahnräder? Dann kann Lunk vielleicht ein Zahnrad haben und über Maschinen lernen.", sourceObjective = "Beschafft 15 gehärtete Schwungräder von ausgehärteten Kriegsgolems.", progress = "Habt Ihr die Zahnräder? Wie habt Ihr sie bekommen?", completion = "Ihr habt... ...nicht die Maschinen GETÖTET, stimmt's?\n\n<Lunk sieht verstört aus.>\n\nStimmt's?", sourceObjectiveStatus = "unverified-source-field" }
quests[27957] = { id = 27957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk nicht töten", sourceObjective = "Nein! Ihr seid wie Zwerg von Thoriumbruderschaft.\n\n\"Zwerg töten. Spinne töten. Maschine töten. Töten, töten, töten.\"\n\nLunk ist in Schlucht gekommen für Abenteuer, nicht für Mörderserie.\n\nLebt wohl, {race}. Ihr tötet zu viel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27958] = { id = 27958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anständiges Gegengift", description = "Eigentlich schade, dass Lunk weg ist. Ich hatte gerade angefangen, Vergnügen an seiner Gesellschaft zu finden.\n\nAber na ja, zurück an die Arbeit!\n\nIch bin das Beste, was diese Expedition in Sachen Medizinversorgung hat, und meine Gegengiftvorräte gehen langsam zur Neige.\n\nDer Schlüssel zu vernünftigem Gegengift ist es, IMMER mit dem Gift selbst zu beginnen. Die Glasnetzspinnen in der Umgebung sollten einen guten Ausgangspunkt bieten. Wenn Ihr sie tötet, könnt Ihr wahrscheinlich etwas Gift aus den Säcken in ihren Kiefern gewinnen.", sourceObjective = "Beschafft Euch 14 Proben Glasnetzgift.", progress = "Sieh mal einer an, ihr arbeitet wirklich schnell! Ihr habt doch das Gift, oder?", completion = "Das... das ist weit mehr, als ich erwartet hatte. Das wird uns monatelang reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27959] = { id = 27959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunks Abenteuer: Spinnenreiter", description = "Lunk merkt, Ihr tötet gerne. Lasst Lunk Euch etwas anderes zeigen.\n\nLunk wollte schon immer auf Spinnenrücken reiten. Sieht spaßig aus. Spinnen bewegen sich aber zu schnell. Hauen immer ab.\n\nWir arbeiten zusammen. Ihr kämpft gegen Spinne, bis Spinne schwach und müde ist. Dann springt Lunk auf Spinnenrücken und reitet.\n\nVielleicht sammelt Lunk etwas Gift für Euch! Nicht müssen töten!", sourceObjective = "Schwächt 7 Glasnetzspinnen, damit Lunk sie reiten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27960] = { id = 27960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je weniger, desto besser", description = "Ich bin kein besonderer Kämpfer... Ich bin eher der Bergbauzwerg. Das Gleiche gilt für Jack und Pris. Was Lunk betrifft... na ja, man könnte glauben, er wäre ein großer Kämpfer, aber eigentlich ist er der größte Feigling von uns allen.\n\nWas ich damit sagen will: Es ist gut, dass Ihr hierhergekommen seid.\n\nEs scheint wahrscheinlich, dass wir von der Thoriumbruderschaft schon bald gegen die anderen Dunkeleisenzwerge kämpfen müssen. Ich denke, dass wir zunächst einige ihrer Besten ausschalten sollten, bevor der Krieg so richtig losgeht. Fangt mit den Geologen und den Wächtern im Süden an.", sourceObjective = "Tötet 10 Geologen der Dunkeleisenzwerge oder Wachmänner der Dunkeleisenzwerge.", completion = "Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[27961] = { id = 27961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehl am Platz", description = "Die Schlucht ist ein unerbittlicher Ort. Hier laufen nicht besonders viele flauschige Wildtiere herum.\n\nWir haben versucht, etwas Jagdwild anzusiedeln, aber sie haben sich nicht besonders gut gehalten. Es gibt einfach nichts für sie zu fressen. Die Spinnen in der Nähe allerdings - die an sich schon gefährlich genug sind - schlagen sich den Bauch mit Hühnchenfleisch voll.\n\nWir werden die Spinnen niemals los, aber wir können die paar Hühner, die es noch gibt, retten. Damit werdet Ihr nicht nur die Bruderschaft versorgen, sondern ihnen auch einen qualvollen Tod durch den Biss einer Spinne ersparen.", sourceObjective = "Beschafft Euch 8 Aschehühnchen.", progress = "Diese armen Tiere.", completion = "Ihr müsst wirklich sehr geschickt sein, wenn Ihr so viele in so kurzer Zeit sammeln konntet.\n\nAusgezeichnete Arbeit, {name}. Ich werde dafür sorgen, dass sie nicht zu Schaden kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27962] = { id = 27962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor der Schlucht", description = "Margol die Wütende ist eine alte Donnerechse, die hier in der Gegend ab und zu auftaucht. Der Legende nach lebte sie schon in dieser Schlucht, bevor es diese Schlucht gab. Einer anderen Legende nach hat sie meinen Bruder Barnabas gefressen.\n\nEs interessiert mich nicht, wie alt sie ist oder welche Magie sie aus ihrer Nase verschießt. Ich will ihren Tod. Um Barnabas' Willen.\n\nIhr findet sie in den Klippen südlich von hier.", sourceObjective = "Erbeutet Margols gigantisches Horn.", progress = "Bringt mir das Horn, {name}.", completion = "Ja, das war wirklich Margols Horn. Kann man nich' dran rütteln.\n\nBarnabas war wie ich ein Gräber. Im Kampf gegen diese Bestie war er chancenlos. Ich bin froh, dass Ihr für Gerechtigkeit gesorgt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27963] = { id = 27963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Meister... nur wer?", description = "Ihr seid gerade zur rechten Zeit gekommen.\n\nDarum geht's: Die Dunkeleisenzwerge in der Schlucht verhalten sich merkwürdig und die Thoriumbruderschaft hat vor, herauszufinden, warum. Aufseher Schlickfaust hat nicht viel für Überraschungen übrig.\n\nWir vermuten, dass sie den Befehlen von irgendeinem neuen Anführer folgen. Ich habe Grund zu der Annahme, dass Gravius Rußschlack, direkt südlich von hier, weiß, um wen es sich dabei handelt.\n\nSelbst hier in der Sengenden Schlucht, hat sich die Kunde Eurer Heldentaten herumgesprochen, {name}. Rußschlack sollte Euch keine Probleme bereiten.", sourceObjective = "Beschafft Euch die Dunkeleisennotiz von Gravius Rußschlack bei Rußschlacks Arbeitsstätte.", progress = "Gibt es Neuigkeiten?", completion = "Mal sehen... Aufseher Maltorius... ihn und seine Arbeit kennen wir schon.\n\nWas ist das denn? Der \"Erzherzog\"? Das klingt ja vielversprechend.", sourceObjectiveStatus = "unverified-source-field" }
quests[27964] = { id = 27964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabungsboss Krawallschnäuzer", description = "Rußschlack war in der Hierarchie nicht so weit oben, wie ich dachte. Wir müssen seinen Vorgesetzten aus dem Weg schaffen und herausfinden, was er weiß.\n\nSein Name ist Ausgrabungsboss Krawallschnäuzer und er leitet die Ausgrabungen der Dunkeleisenzwerge im Kessel etwas nordwestlich von hier. Seine Ausgräber und Fußsoldaten patrouillieren auf der östlichen Seite des Kessels und graben sich Tag und Nacht weiter nach unten.\n\nEr zeigt sich nicht sehr oft in der Öffentlichkeit, aber wenn Ihr genug seiner Männer tötet, wird er gezwungen sein, herauszukommen und sich mit Euch zu befassen.", sourceObjective = "Tötet Ausgräber und Fußsoldaten der Dunkeleisenzwerge im Kessel, bis Ausgrabungsboss Krawallschnäuzer erscheint. Dann tötet den Ausgrabungsboss Krawallschnäuzer und bringt seine Dunkelglut an Euch.", progress = "Wenn Krawallschnäuzer das Gewünschte nicht bei sich trägt, bin ich nicht sicher, was wir als Nächstes tun werden.", completion = "Eine... eine Glut? Was ist das für ein Ding?", sourceObjectiveStatus = "unverified-source-field" }
quests[27965] = { id = 27965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thoriumspitze: Der Sitz der Bruderschaft", description = "Habt... habt Ihr das gesehen? Das ist das Puzzlestück, das uns gefehlt hat! Wir müssen diese Informationen zu jemandem an der Thoriumspitze bringen.\n\nEs ist bekannt, dass die Dunkeleisenzwerge in der Vergangenheit gemeinsame Sache mit dem Feuerfürsten gemacht haben, aber noch nie zuvor haben sie sich so weit in die Sengende Schucht hinaus gewagt.\n\nDie Thoriumspitze liegt westlich und nördlich von hier. Ihr findet sie versteckt in den Klippen, die die Pyroxebenen überragen. Bringt diese Informationen schnurstracks zu Aufseher Schlickfaust.", sourceObjective = "Meldet Euch bei Aufseher Schlickfaust auf der Thoriumspitze in der Sengenden Schlucht.", completion = "Kenne ich Euch, {race}?\n\n\n\nDas klingt nach einem weiteren Diener von Ragnaros. So etwas höre ich überhaupt nicht gern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27966] = { id = 27966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Überreste", description = "Der Vergessene Hügel ist von Zombies und Ghulen überrannt worden, seit dem Tag, an dem wir diese erbärmliche Insel für uns beanspruchten. Wir haben versucht, sie loszuwerden, aber es scheint, als kämen sie immer wieder.\n\nEiner unserer Leutnants hat vorgeschlagen, die Ghulknochen wegzuräumen, nachdem wir sie getötet haben, in der Hoffnung, dass sie nicht über Nacht wiederauferstehen. Glaubt Ihr, dass Ihr uns hierbei helfen könntet?", sourceObjective = "Ihr müsst 9 verfluchte Oberschenkelknochen von den Ghulen, die auf dem Vergessenen Hügel hausen, einsammeln. Der Vergessene Hügel befindet sich auf der westlichen Seite der Insel, direkt vorbei an der Vergessenen Front.", progress = "Konntet Ihr die Oberschenkelknochen sammeln? Mir ist lieber, Ihr versucht es, als dass ich es tun müsste.", completion = "Ich hätte nicht gedacht, dass Ihr es schaffen könnt, {name}. Ihr steckt ja voller Überraschungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27967] = { id = 27967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberleutnant Connor", description = "Als ich das erste Mal von Oberleutnant Connor hörte, war ich ein junger Rekrut im Verlies von Sturmwind. Niemand von uns hätte je gedacht, dass er mal hier auf Tol Barad enden würde. Traurigerweise wandert er noch immer über diese elenden Inseln und richtet verheerenden Schaden an der Moral unserer Truppen an.\n\nIch möchte, dass Ihr seinem Elend ein Ende macht... und damit unserem.", sourceObjective = "Findet und tötet Oberleutnant Connor auf dem Vergessenen Hügel. Ihr findet den Vergessenen Hügel auf der westlichen Seite der Insel.", completion = "He, Ihr habt es lebendig hierher zurück geschafft! Ich kann nicht behaupten, dass Ihr der Erste wart, der dieses Unterfangen versucht hat, aber Ihr seid gewiss der Erste, der in einem Stück zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27968] = { id = 27968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wut des Rudels", description = "Ah, der süße Geruch von Sieg! Meine Männer sollten Godfrey in eben diesem Augenblick in Stücke reißen. Begebt Euch zu ihm und holt Euch Euren Teil der Beute - Ihr habt es Euch verdient!\n\nMan hätte gedacht, dass es schwieriger würde, ihn zu vernichten...", sourceObjective = "Tötet Lord Godfrey.", progress = "Legen wir los.", completion = "Wir haben es geschafft, {name}! Es hat uns viel gekostet, aber der Sieg ist unser.\n\nDiese Burg könnte mir und meinem Rudel als Heimstatt dienen, auch wenn wir normalerweise einen etwas natürlicheren Lebensraum bevorzugen.\n\nVielleicht ist es das Beste, sie zur Erinnerung an Godfreys Verrat und die Blutfangkrieger, die hier gefallen sind, zu belassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27969] = { id = 27969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht Euch nützlich", description = "Wir werden Gubbel sehr vermissen, aber die Mission darf nicht darunter leiden.\n\nVielleicht gibt es da etwas, das Ihr tun könnt, um Euch zu rehabilitieren.\n\nNehmt eine der Uniformen, die Ihr gefunden habt. Wenn Ihr sie tragt, werden meine Arbeiter nicht so... aggressiv reagieren.\n\nIn letzter Zeit war ihre Moral nicht gerade hoch. Einige der Arbeiter weigern sich gar, ihren Pflichten nachzukommen.\n\nOh, diese Dreistigkeit!\n\nFindet diese faulen Schwachköpfe und überzeugt sie davon, an die Arbeit zu gehen... oder sonst!", sourceObjective = "Kommandant Schnottz möchte, dass Ihr 6 faulenzende Arbeiter davon überzeugt, wieder an die Arbeit zu gehen.", completion = "Gut gemacht, {class}.\n\nVielleicht besteht ja noch Hoffnung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27970] = { id = 27970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän P. Harris", description = "Das Kap der Verlorenen Hoffnung steckt uns hier auf Tol Barad seit Wochen wie ein Stachel im Fleisch. Die Hälfte unserer Versorgungsschiffe endet auf den Felsen dort unten.\n\nHinzu kommt, dass es von einer Bande untoter Matrosen überrannt wurde. Wir haben versucht, sie zu dezimieren, aber sie kommen immer wieder zurück. Unsere letzte Hoffnung ist es, den Kapitän zu töten, der ihnen ihre Befehle gibt. Ihr solltet ihn auf einem Schiff nahe des Ufers finden.\n\nOh, und ich hoffe, Ihr habt keine große Angst vor Haien.", sourceObjective = "Ihr habt den Auftrag, Kapitän P. Harris am Kap der Verlorenen Hoffnung zu töten. Das Kap der Verlorenen Hoffnung liegt gleich nordwestlich von hier, die Küste entlang. Haltet einfach Ausschau nach den Schiffswracks.", completion = "Ihr habt es geschafft! Vielleicht schaffen es jetzt endlich ein paar Schiffe in den Hafen! Danke sehr, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27971] = { id = 27971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stört ihre vorletzte Ruhe", description = "Seit einiger Zeit haben wir Probleme mit den Untoten unten am Kap der Verlorenen Hoffnung. Bei jedem neuen Schiffbruch schließen sich ihnen neue Untote an.\n\nKönnt Ihr uns einen Gefallen tun und die Mannschaft dort etwas ausdünnen? Ich weiß, Ihr könnt sie nicht alle töten, aber jeder Beitrag ist für uns von Nutzen.\n\nHaltet ein Auge auf die Horde, in letzter Zeit wird gemeldet, dass ihre Kämpfer am Strand im Hinterhalt liegen.", sourceObjective = "Lagerkommandant Brack hat Euch gebeten, am Kap der Verlorenen Hoffnung 8 schiffbrüchige Seemänner oder Seefrauen zu töten. Das Kap befindet sich nordwestlich von hier, am Strand.", completion = "Gute Arbeit mit den Untoten da oben, {name}. Wir wissen Eure Hilfe wirklich sehr zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27972] = { id = 27972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkung der Moral", description = "Die Stimmung ist in letzter Zeit schlecht, {name}. Wir tun, was wir können, um die Truppen bei Laune zu halten, aber leider geht uns der wichtigste Stimmungsaufheller aus... Rum.\n\nUnsere Infanterie im Osten berichtet, dass in den Rümpfen der Schiffswracks am Kap der Verlorenen Hoffnung jede Menge Südmeerrum liegt. Würdet Ihr dort hinreisen und dem nachgehen?\n\nBringt so viel Rum mit, wie Ihr finden könnt.", sourceObjective = "Ihr habt den Auftrag erhalten, 6 Fässer mit Südmeerrum aus den Schiffswracks am Kap der Verlorenen Hoffnung zu beschaffen. Das Kap liegt nördlich von hier, entlang der Küste.", progress = "Konntet Ihr den Rum bergen? Ich würde es ja versuchen, aber ich habe Angst vor Wasser. Und vor diesem verrückten Hai.", completion = "Der Rum wird uns sehr helfen, {name}. Sie werden sich morgen früh zwar nicht gut fühlen, aber wenigstens schlafen sie glücklich ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27973] = { id = 27973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, Splitter", description = "Wart Ihr schon in Wellsons Werft, {name}? Am besten haltet Ihr Euch davon fern, es sei denn, Ihr habt einen guten Grund, dort hinzugehen. Und unglücklicherweise werde ich Euch einen guten Grund geben.\n\nWisst Ihr, wir haben hier nur wenige Vorräte, seit wir die Insel wieder eingenommen haben. Auf der von Geistern heimgesuchten Werft ist viel Holz, aber alle, die ich bisher geschickt habe, um es zu holen, kamen nicht zurück.\n\nKönnt Ihr uns helfen?", sourceObjective = "Bringt 15 Stücke Schiffsbauholz von Wellsons Werft zu Unteroffizier Grau. Das Holz wird von den Geistern in der Werft bewacht oder liegt frei zugänglich in der Werft verteilt. Die Werft ist an der Küste nordwestlich von hier.", progress = "Haben die Geister Euch Angst eingejagt?", completion = "Ich habe nicht damit gerechnet, dass Ihr diese Aufgabe erfüllen könnt, {name}. Ihr steckt voller Überraschungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27974] = { id = 27974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist unser Land", description = "Dachtet Ihr, dass eine Handvoll Worgengezücht mich aufhalten kann? Ha!\n\nZu Lebzeiten war Burg Schattenfang Teil des Königreichs Lordaeron, also ist es nur gerecht, dass es im Tode den Verlassenen gehört. Godfrey und seine Komplizen sind bestenfalls kleine Hindernisse und natürlich freuen wir uns, sie als Strafe für den Verrat an der Dunklen Fürstin beseitigen zu können.\n\nAshbury hat sich bei der Vorderseite der Burg niedergelassen und ist einem Angriff gegenüber völlig ungeschützt. Bereitet uns einen schönen Anfang, ja?", sourceObjective = "Tötet Baron Ashbury.", progress = "Stellt meine Geduld und mein Wohlwollen nicht auf die Probe.", completion = "Ah, sehr gut! Sie haben sich mächtige Verbündete beschafft, aber offensichtlich ist das nichts, womit ein herausragender {class} der Bansheekönigin nicht fertig würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27975] = { id = 27975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Vorarbeiter Wellson", description = "Vorarbeiter Wellson ist uns schon seit unserer Ankunft ein Dorn im Auge. In seiner Werft lagert er haufenweise Materialien, die für uns von extrem hohem Nutzen sein könnten... wenn wir nur an sie heran kämen.\n\nEr lässt sie von seinen Dienern streng bewachen und macht es uns schwer, auch nur einen Fuß in die Werft zu setzen. Ihr müsst Wellson ein für alle Mal für mich erledigen. Aber seid vorsichtig, {name}. Uns wurde berichtet, dass die dreckige Horde überall in der Gegend ihr Unwesen treibt.", sourceObjective = "Tötet Vorarbeiter Wellson in Wellsons Werft. Die Werft befindet sich nordwestlich von hier an der Westküste.", completion = "Ausgezeichnete Arbeit, {name}. Ich werde Eure Taten sofort unserem Oberkommando melden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27976] = { id = 27976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammt seien diese fetten Finger", description = "Leider kann ich wegen dieses Fettfingerproblems meine Schläge nicht mehr so austeilen wie früher. Durch das Klima hier draußen und den fehlenden Luftdruck dehnen sich meine Finger aus. Die sehen aus wie riesige Thelsamarblutwürste, oder?\n\nIhr werdet meine Befehle und all so'n Zeug ausführen müssen.\n\nPunkt Eins auf der Liste: Die schweren Kriegsgolems in der Schlucht windelweich prügeln. Legt los.", sourceObjective = "Tötet 12 schwere Kriegsgolems.", completion = "Ihr seid ein wirklich guter Junge. Ich hab ein kleines Geschenk für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27977] = { id = 27977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufklärungsausstattung", description = "Früher hatten wir hier mal mehr Zeug. Ich glaube, es gab hier mal irgendwo ein Handfernrohr, zusammen mit einer Schmiedwindform.\n\nIch bin mir ziemlich sicher, dass sie von Dunkeleisenzwergen gestohlen wurden. Ja, ich weiß, dass ich ein Dunkeleisenzwerg bin! Ich spreche von den bösen Dunkeleisenzwergen, die in der Schlucht leben.\n\nAm besten versucht Ihr es mal bei den Dampfschmieden, die südlich von hier arbeiten. Bei ihnen ist es am Wahrscheinlichsten, dass sie solche Werkzeuge benutzen.", sourceObjective = "Findet die Schmiedewindform und das Ausguckhandfernrohr und bringt sie zurück.", progress = "Wenn Ihr wegen Eurer Belohnung hier seid, dann müsst Ihr mir erst die gestohlenen Gegenstände aushändigen.", completion = "Fantastische Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[27978] = { id = 27978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterjäger", description = "Seht Ihr den Hügel, direkt außerhalb unseres Basislagers? Das ist Largos Warte und es ist nicht der schönste Ort, um daneben ein Lager zu errichten. Wir mussten uns mit Geistern und Schreckgespenstern herumschlagen, seit wir unser Basislager hier aufgeschlagen haben.\n\nKönnt Ihr Euch dorthin begeben und sie wissen lassen, dass wir nicht vorhaben, uns sobald von hier wegzubewegen? Ein paar Abschüsse in ihren Reihen sollten sie zur Räson bringen.\n\nVielen Dank für Eure Hilfe hierbei, {name}.", sourceObjective = "Tötet 14 beliebige Geister bei Largos Warte, direkt nordöstlich des Basislagers.", completion = "Hervorragend, {name}! So bald sollten wir von den Geistern nichts mehr hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[27979] = { id = 27979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Dienste", description = "Ich habe noch eine Aufgabe für Euch. Diese kommt direkt vom Aufseher. Offenbar war er ziemlich aufgewühlt, als er von dem \"Erzherzog\" hörte, den Ihr entdeckt habt.\n\nEr hat uns gebeten, drei Zwielichtpriester, die drüben am Feuerwachtgrat im Westen arbeiten, aufzuspüren. Sie heißen Kiyuubi, Letherio und Fiester und jeder von ihnen trägt einen speziellen Stein bei sich. Setzt die drei zusammen und bringt sie herher.\n\nHört zu - wenn der Aufseher Befehle gibt, stellt man keine Fragen. Man tut es einfach.", sourceObjective = "Beschafft Euch die Steinkügelchen von Kiyuubi, Letherio und Fiester. Setzt sie zu einem Zwielichttripetrizin zusammen.", progress = "Habt Ihr das Ding?", completion = "<Hansel wiegt den Stein in seinen Händen.>\n\nDieses Ding ist seltsam, {name}. Ich weiß nicht, was ich davon halten soll. Eins ist sicher - es ist nicht natürlichen Ursprungs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27980] = { id = 27980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spinnen müssen weg", description = "Mit Spinnen von normaler Größe kann ich umgehen.\n\nBei riesigen Glasnetzspinnen fühle ich mich unbehaglich, aber die sind weit genug weg, sodass ich mir nicht allzu viele Sorgen machen muss.\n\nAber Lavaspinnen? <Lolo erschauert.> Lavaspinnen sind GRUSELIG. Das sind gewaltige Spinnen. Die in LAVA leben.\n\nIch habe gerade meinen Lohn für die letzte Arbeitswoche bekommen und werde Euch gut bezahlen, wenn Ihr diese Dinger tötet. Ihr findet sie überall in der Sengenden Schlucht.", sourceObjective = "Erschlagt 9 Lavaspinnen in der Sengenden Schlucht.", completion = "Ihr konntet sicher nicht alle Spinnen in der Schlucht töten, aber Ihr habt definitiv eine Lücke in ihre Reihen geschlagen.\n\nGut, hier ist, was ich Euch versprochen habe. Aber gebt nicht alles auf einmal aus. Außer Ihr tut es auf der Thoriumspitze.", sourceObjectiveStatus = "unverified-source-field" }
quests[27981] = { id = 27981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitze, die nie vergeht", description = "Wir schmieden, wir schmelzen, wir rösten jegliches Spinnenfleisch, das wir finden können. Buschhühner, wenn wir Glück haben. Der Punkt ist, dass wir für all diese Arbeiten unglaublich viel Feuer benötigen.\n\nOh, wenn wir doch bloß in einer Aschewüste leben würden, in der einem an jeder Ecke der Bart versengt wird.\n\nNatürlich stammt das beste Feuer von den Elementaren. Man findet sie überall in der Sengenden Schlucht, hauptsächlich aber in der Nähe von Lava. Hier, nehmt diese Flaschen und benutzt sie bei den Elementaren.\n\nOh, habe ich schon erwähnt, dass die Elementare am Leben sein müssen, wenn Ihr die Proben einsammelt?", sourceObjective = "Besorgt 10 gefüllte Ofenflaschen. Ihr müsst die Ofenflaschen bei lebendigen Elementaren in der Sengenden Schlucht benutzen.", progress = "Schlickfaust sagt, wir sollen bald Feuerbomben für ihn bauen. Umso dringender benötigen wir diese Flaschen.", completion = "Auaaaaaaaaa! Ihr dürft dieses Zeug doch nicht einfach in die offene Hand eines Zwergs legen. Das Zeug ist doch glühend heiß!\n\nJetzt werden meine Hände noch mehr anschwellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27982] = { id = 27982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichthalsbänder", description = "Habt Ihr diese lächerlichen Ketten gesehen, die die Kultisten des Schattenhammers tragen? Die Edelsteine auf den Dingern sind größer als Hansels Faust!\n\nNur ein paar von diesen spiegeleigroßen Juwelen und Burninate da drüben könnte dieses Schmiedegeschäft auf die nächste Ebene bringen. Bringt ihm diese Halsbänder und es soll Euer Schaden nicht sein.", sourceObjective = "Beschafft 20 Zwielichthalsbänder.", progress = "Ein rubinbesetzer Hammer... Klingt doch nett, oder?", completion = "Hmm... Aus der Ferne sahen diese Edelsteine irgendwie... funkelnder aus. Aus der Nähe sind sie doch ganz schön stumpf.\n\nAch, was soll's! Ein wenig Spucke und Politur sollte die Sache schon richten. Und falls nicht, kann ich sie immer noch nutzen, um meine Entzauberkünste zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27983] = { id = 27983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunks Abenteuer: Launische kleine Zwerge", description = "Was Ihr machen? Warum Ihr töten?\n\nIhr brauchen Sachen von Zwergen? Ah, Lunk verstehen. Lunk haben besseren Weg.\n\nHört zu: Ihr bekämpfen Zwerg, aber nicht töten! Nur bekämpfen, bis Zwerg müde sein. Dann Lunk wird helfen, wenn Zwerg einschlafen. Zwerge wahrscheinlich nur griesgrämig, weil sie nicht schlafen.\n\nKommt, vertraut Lunk.", sourceObjective = "Schwächt 7 Dampfschmiede der Dunkeleisenzwerge, sodass Lunk ihnen helfen kann, einzuschlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27984] = { id = 27984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distelmonds Geschichte", description = "Werdet Ihr mir helfen, <Sterblicher/Sterbliche>? Hört meine Geschichte.", sourceObjective = "Lauscht Zamaels Erzählung.", completion = "Ich habe mich in mein Schicksal hier in diesem Käfig ergeben, aber das Gebet muss gefunden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27985] = { id = 27985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebet an Elune", description = "Werdet Ihr mir helfen, sterbliches Wesen? Werdet Ihr das Gebet an Elune finden?\n\nWie ich bereits sagte, wurde das Gebet auf eine goldene Schrifttafel geätzt. Ich denke, dass sie sie in einer ihrer widerwärtigen Kisten aufbewahren, in der Nähe des Eingangs zu ihrer Höhle, am Boden des Grats.\n\nWenn es Euch gelingt, mein Gebet zurückzubekommen, so bringt es nicht zu mir zurück. Stattdessen nehmt Euch bitte die Zeit, es zu lesen.\n\nVergebung ist vielleicht zu viel verlangt, wenn man die Sünden bedenkt, die ich begang. Es wird mich aber nicht davon abhalten, weiterhin zu hoffen.Ihr erlernt:", sourceObjective = "Findet und lest das Gebet an Elune.", sourceObjectiveStatus = "unverified-source-field" }
quests[27986] = { id = 27986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Hallen des Bergfürsten", description = "Die Thoriumbruderschaft verfügt über keinerlei Miliz - nur ein paar Wachen und ich, und das war's. Wenn wir einen erfolgreichen Schlag gegen die Dunkeleisenzwerge in der Schlacht führen wollen, dann brauchen wir Hilfe.\n\nBergfürst Rendan befindet sich oben im Turm, über die Schlucht hinweg, von uns aus im Süden. Er verkehrt nicht mit dem Gesindel des Schattenhammers oder mit Feuerelementaren, aber er hat sich auch nicht der Bruderschaft angeschlossen. Vielleicht ist es an der Zeit, dass wir ihm einen Besuch abstatten. Mit seiner Hilfe könnten wir eine Chance haben.", sourceObjective = "Sprecht mit Bergfürst Rendan auf dem Eisengipfel in der Sengenden Schlucht.", completion = "Und wer seid Ihr wohl?\n\nAh, ein Abgesandter der Thoriumbruderschaft. Ihr benötigt meine Unterstützung? Nun gut, ich könnt' mich bereit erklären, Euch zu helfen...\n\n...wenn die Bezahlung stimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27987] = { id = 27987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenkugel!", description = "Seit wir unser Lager hier errichtet haben, stehlen Largo und seine Handlanger unsere Vorräte. Das ist mehr als frustrierend.\n\nUns wurde berichtet, dass er oben auf seiner Warte Kanonenkugeln in den Türmen lagert, die über das Wasser hinausblicken. Würdet Ihr Euch dorthin aufmachen und versuchen, einige davon für uns zurückzuholen?\n\n{name}, vergesst nicht, auch vor der Horde auf der Hut zu sein.", sourceObjective = "Ihr müsst 4 Stapel Kanonenkugeln aus Largos Warte für Unteroffizier Grau besorgen. Ihr findet Largos Warte nordöstlich des Basislagers.", progress = "Habt Ihr die Kanonenkugeln gefunden?", completion = "Eine sehr gelungene Bergung, {name}. Diese Kanonenkugeln sollten eine Weile reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27988] = { id = 27988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuche... Überall Seuche!", description = "Das Beste an dieser Seuche ist: selbst wenn der sichtbare Teil verblasst, so ist der verbleibende Überrest doch immer noch recht mächtig! Allerdings haben wir immer noch eine riesige Fläche abzudecken, bevor wir fertig sind, auf der sich jede Menge von Godfreys Verteidigungen befinden.\n\nEs scheint, als würden die Diener, die Baron Silberlein und Kommandant Grüntal im Leben umsorgten, dies auch noch im Tode tun, und dass Godfrey sie benutzt, um uns zu behindern. Zeigt ihnen den eisernen Willen der Verlassenen!", sourceObjective = "Tötet Baron Silberlein und Kommandant Grüntal.", progress = "Ein paar körperlose Geister werden es doch wohl nicht mit Euch aufnehmen können, oder?", completion = "Cromush besitzt sowohl einen dicken Schädel als auch ein Spatzenhirn und das werden wir uns zunutze machen. Bis irgendjemand herausfindet, wie stark die Seuche in Wahrheit ist, wird es viel zu spät sein.\n\nDanke, dass Ihr während seiner Tirade an Euch gehalten habt. Ich verspreche Euch, dass Ihr das nicht bereuen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27989] = { id = 27989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo verlangt Honig", description = "Ruumbo hat Hunger!\n\nDie Totenwaldidioten haben der Holzschlundfeste den ganzen Honig gestohlen! Wir haben es... äh... Ruumbo hat es gesehen! Und jetzt muss Ruumbo den Honig bekommen!\n\nNehmt diesen... diesen Stock! Ja, diesen Stock! Nehmt den Stock und benutzt ihn, um den Honig aus ihren Bienenstöcken im Lager der Totenwaldfelle zu klauen.\n\nRuumbo muss so viel Honig wie möglich haben. Das ist wichtig.", sourceObjective = "Sammelt 10 Honigtropfen der Totenwaldfelle aus den Bienenstöcken im Lager der Totenwaldfelle, indem Ihr Ruumbos Honigstock benutzt.", progress = "Ruumbo kann riechen, ob Ihr Honig dabei habt, oder nicht!", completion = "Honig! Köstlicher Honig!\n\nGut gemacht, hässliches Geschöpf! Ihr könnt den Honig genau... dort hinstellen. Nein, weiter links. Ja, da. Lasst ihn da stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27990] = { id = 27990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefechtszone", description = "Es scheint, als gäbe es da noch eine Möglichkeit, Euch zu rehabilitieren, {race}.\n\nDieser kleine Zwischenfall hat mich einige Panzerkanoniere gekostet.\n\nMeint Ihr, Ihr habt es drauf, einen von ihnen zu ersetzen?\n\nMeine Panzer befinden sich gleich westlich des Lagers. Geht da raus und bereitet diesem Unfug ein Ende!", sourceObjective = "Kommandant Schnottz möchte, dass Ihr einen der Belagerungspanzer bemannt und ihn benutzt, um 7 altersschwache Behüter zu besiegen. Meldet Euch danach wieder bei ihm.", completion = "Autsch!\n\nWäre ich nur eine Handbreit größer, wäre ich jetzt tot!", sourceObjectiveStatus = "unverified-source-field" }
quests[27991] = { id = 27991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Warte", description = "Es gibt nur eine Möglichkeit, wie wir Largos Warte zurückzuerobern können.\n\nIch glaube, Ihr wisst, was Ihr tun müsst, {name}. Largo ist in letzter Zeit ziemlich paranoid. Ihr solltet ihn also auf der Turmspitze finden, wo er nach seiner eingebildeten Flotte Ausschau hält.", sourceObjective = "Unteroffizier Grau hat Euch beauftragt, Kommandant Largo in Largos Warte zu töten. Die Warte befindet sich direkt nordöstlich des Basislagers.", completion = "Ha! Endlich haben wir Largo erledigt! Sehr gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27992] = { id = 27992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinischer Magnetismus", description = "Nützliche Maschinenteile hier draußen auf der Insel zu bekommen, war sehr schwierig, {name}. Wir haben versucht, die kaputten Belagerungsmaschinen hier im Camp zu reparieren, doch uns sind brauchbare Ersatzteile ausgegangen.\n\nUnser Zweites Regiment berichtete uns von schrottreifen Belagerungsmaschinen auf einem Schlachtfeld im Westen. Vielleicht könnten wir dort Ersatzteile finden?\n\nIhr werdet Probleme haben, überhaupt irgendetwas auf dem alten Schlachtfeld zu finden. Nehmt deshalb diesen magnetisierten Schrottsammler und macht ihn Euch zunutze.", sourceObjective = "Ihr habt die Aufgabe erhalten, 7 Stücke Belagerungsmaschinenschrott zu bergen. Benutzt den magnetisierten Schrottsammler an der Rastlosen Front, um die Schrottteile zu finden. Die Rastlose Front befindet sich im Westen hinter der zweiten Brücke.", progress = "Hat diese Magnetvorrichtung wirklich funktioniert?", completion = "Diese Ersatzteile werden uns wirklich weiterhelfen, {name}! Wer hätte gedacht, dass man unter all diesem nutzlosen Schrott noch so nützliche Dinge finden kann?", sourceObjectiveStatus = "unverified-source-field" }
quests[27993] = { id = 27993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt's ihnen!", description = "Wir haben echt Glück gehabt, dass wir entkommen sind, {class}. Ich glaub ich würde mich nicht sehr wohl in meiner Haut fühlen, wenn wir's den Wegelagerern nicht gezeigt hätten.\n\nWie wär's, wenn Ihr zurück zum Grab des Khartut geht und den kleinen Nervensägen was auf die Nase gebt?\n\nDas Grab ist im Nordosten, direkt hinter dem Eingang zu Uldum, wenn ich mich recht entsinne.\n\nWarum guckt Ihr so dumm? Ich bin nicht in der Verfassung, das selbst zu machen!", sourceObjective = "Mack möchte, dass Ihr das Grab des Khartut untersucht.", completion = "Schön, Euch zu sehen.\n\nNoch schöner wäre es allerdings gewesen, wenn Ihr hier gewesen wärt und mir geholfen hättet, diese kleinen Wilden in den Griff zu bekommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27994] = { id = 27994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo verlangt Gerechtigkeit", description = "Ihr! Wanderer! Verneigt Euch vor der Macht Ruumbos, dem großen Gott des Stamms der Holzschlundfeste!\n\nVernehmt meinen Willen! Der bösartige Stamm der Totenwaldfelle lebt in dem Lager hinter mir! Sie sind riesige Blödmänner!\n\nIch meine... sie... sie besudeln meinen Namen mit ihren niederträchtigen Missetaten! Sie verfolgen meinen geliebten Stamm der Holzschlundfeste und verletzen sie!\n\nIch verlange, dass Ihr meine Gerechtigkeit walten lasst! Vernichtet die Totenwaldfelle und ich werde Euch meine... meine Gunst gewähren! Ja! Die Gunst von RUUMBO!", sourceObjective = "Tötet 15 Furbolgs der Totenwaldfelle jedweder Art.", completion = "Es hat geklappt!\n\nÄhm, ich meine natürlich, JA! Ruumbos Wille wurde vollstreckt! Das habt Ihr gut gemacht, Geschöpf! Ihr dürft diese glänzenden Münzen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27995] = { id = 27995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanzt für Ruumbo!", description = "Ihr habt gute Arbeit geleistet, {race}! Ruumbo ist erfreut über Eure Tapferkeit und den leckeren Honig, den Ihr Ruumbo gegeben habt.\n\nUnd jetzt müsst Ihr... müsst Ihr tanzen! Ja!\n\nTanzt für Ruumbo! Tanzt!", sourceObjective = "Tanzt einen albernen Tanz für Ruumbo.", completion = "Diese zwei Gören... ich hätte es wissen sollen! Sie waren schlau genug, immer dann leise zu sein, wenn ich nach dem Totem gesehen habe.\n\nIch werde sie ausfindig machen und bei den Ohren zur Holzschlundfeste zurückzerren! Danke, dass Ihr Euch der Sache angenommen habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[27996] = { id = 27996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle sind was für die Lebenden", description = "Wie nicht anders erwartet, werden wir natürlich nicht auf Cromush hören, was die Seuche betrifft. Nichtsdestotrotz wird uns seine brachiale Kraft nützlich sein, wenn es darum geht, auf dem Weg zu Godfrey einen Durchgang für meine Männer durch die Gegnerreihen zu erzwingen. Der mächtigste in ihren Rängen dürfte seine rechte Hand, Lord Walden, sein.\n\nIch treffe Euch in Waldens Kammer, nachdem Ihr mit ihm fertig seid. Dann endlich werden wir Burg Schattenfang für die Verlassenen einnehmen!", sourceObjective = "Tötet Lord Walden.", completion = "Die Stunde hat geschlagen! Godfrey wird fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27997] = { id = 27997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jadefeuerverderbnis", description = "Das Säubern dieses Waldes hat sich als zermürbender Prozess herausgestellt. Für jeden errungenen Erfolg, hat sich eine neue Herausforderung aufgetan.\n\nDie Jadefeuersatyrn sind ein fortwährendes Ärgernis. Sie streben danach, den Wald zu verderben, während wir uns bemühen, ihn zu reinigen. Nun haben wir Schritte eingeleitet, um sie im Teufelswald vollständig auszurotten.\n\nReist ins Jadefeuertal im Westen und säubert den Wald von ihrer Präsenz. Ihr findet den Eingang direkt nördlich der Mauern zum Lager der Totenwaldfelle; haltet einfach Ausschau nach ihren widerwärtigen Bannern.", sourceObjective = "Tötet 12 Jadefeuersatyrn oder Jadefeuerteufelsanbeter im Jadefeuertal.", progress = "Das Jadefeuertal ist unser erstes Ziel in einer ganzen Reihe von koordinierten Angriffen. Um die anderen kümmern wir uns später.", completion = "Der Dank des Smaragdkreises ist Euch sicher, {name}. Wenn wir hier alle zusammenarbeiten, können wir diese Dämonen aus unserer Mitte tilgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27998] = { id = 27998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße, gnadenlose Rache", description = "Wenn alles gut geht, solltet Ihr in der Lage sein, direkt in Godfreys persönliche Gemächer zu spazieren und eine Belohnung zu erhalten, wie <ein eifriger junger/eine eifrige junge:c> {class} wie Ihr sie verdient hat.\n\nGodfrey ist allerdings ein listiger Gegner, es könnte also weise sein, Euch schnell auf den Weg dorthin zu machen, für den Fall, dass Ihr benötigt werdet. Er wird dafür bezahlen, was er der Dunklen Fürstin angetan hat!", sourceObjective = "Tötet Lord Godfrey.", completion = "Einen Moment lang dachte ich, alles wäre dahin. Selbst als ich in Gilneas von den Worgen umzingelt war, hatte ich mehr Hoffnung!\n\nAber Ihr habt meine Befürchtungen widerlegt, {name}. Ich werde dafür sorgen, dass Sylvanas selbst von Eurem heutigen Sieg erfährt. Macht Euch keine Gedanken über die Unordnung hier. Ich werde mich gern selbst darum kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27999] = { id = 27999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Doyles", description = "Anscheinend haben die Doyles ihren letzten Kampf hinter sich. Iain wird über ihr Schicksal Bescheid wissen wollen.", sourceObjective = "Kehrt mit den Neuigkeiten über den Klan Doyle zu Iain Feuerbart auf Feuerbarts Friedhof zurück.", completion = "Das ist wirklich schade. Genauso stur, wie sie sich verhielten, wenn man mit ihnen reden wollte, waren sie auch im Kampf. Es wäre gut gewesen, sie dabeizuhaben.\n\nSobald das hier erledigt ist, werden wir einige der Jungs aussenden, um sie zurückzuholen, damit wir ihnen ein anständiges Begräbnis verschaffen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28000] = { id = 28000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichteln, einmal anders", description = "Die Satyrn verstecken ihren verderbten Mondbrunnen hinter einer undurchdringlichen Barriere aus dämonischem Feuer. Ihre eigenen Truppen müssen über eine Möglichkeit verfügen, ungehindert hindurchzudringen.\n\nDie Satyrn zu verhören wird sinnlos sein, aber die Wichtel, mit denen sie verkehren, dürften leicht zu beeinflussen sein. Ich habe da einen ganz bestimmten im Auge...\n\nÖstlich von hier, am Gebirgsfuß, wurde ein einsamer Wichtel gesehen, der weit abseits der anderen Dämonen umherstreift. Er dürfte leichte Beute sein. Schwächt ihn im Kampf und benutzt dann diesen verzauberten Sack, um ihn einzufangen. Das Reden übernehme ich dann...", sourceObjective = "Schwächt Impsy und dann benutzt den verzauberten Wichtelsack, um ihn einzufangen.", completion = "Wichtel sind betrügerische Kreaturen. Da so viele von ihnen am Schattenlauergrat gesehen wurden, bin ich sicher, dass dort etwas versteckt wird.\n\nUnser kleiner Freund wird uns genau beschreiben, wie wir das finden können, wenn er nicht wieder in den Sack zurück will.", sourceObjectiveStatus = "unverified-source-field" }
quests[28001] = { id = 28001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was einem Feigling zusteht", description = "Mag ja sein, dass wir hier sicher sind, aber da draußen gibt es noch eine Menge Wildhämmer, die Unterstützung brauchen können. Unser Geschwader kann die bieten, aber wir müssen unsere Streitkräfte verstärken, wenn wir den Schattenhammer auslöschen wollen.\n\nIch werde mit Colin Donnermar sprechen. Nur ein Feigling wendet sich von dem Ruf seines Volkes ab, vor allem in schwierigen Zeiten wie diesen.\n\nGeht nach Donnermar, findet Colin und lasst Euch von ihm eine vernünftige Erklärung geben. Ich werde keine Feigheit bei einem Anführer der Wildhammer dulden.", sourceObjective = "Sprecht mit Colin Donnermar in Donnermar.", completion = "Bitte? BITTE WAS!? Er nennt MICH einen FEIGLING?!\n\nTypisch Feuerbart - nur heiße Luft und keine Spur von Verstand. Ich habe die Hauptlast des Einmarsches des Drachenmalklans aus dem Süden ertragen, Donnermar liegt zum großen Teil in Trümmern und kommt mal einer der anderen Klans zu Hilfe? NEIN! Der alte Donnermar ist hier ganz allein und Ihr könnt mir glauben, dass ich alles in meinem Arsenal benutze, nur um die Flutwelle aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28002] = { id = 28002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krisenmanagement", description = "Es gibt eine heikle Situation, die nach der... unparteiischen Diskretion eines Außenstehenden verlangt.\n\nWisst Ihr, ein unglücklicher Vorfall hat einige unserer Gäste beunruhigt. Seid versichert, dass unsere besten Leute sich um die Einzelheiten kümmern.\n\nIn der Zwischenzeit wäre es wunderbar, wenn Ihr unsere etwas überempfindlichen Gäste beruhigen könntet.\n\nWenn Ihr damit gut umgeht, wird der Fellhändler mit Sicherheit davon hören!", sourceObjective = "Bellok Leuchtklinge möchte, dass Ihr die Gäste in Schnottz' Landeplatz beschwichtigt.", completion = "Hmm, sie sind immer noch ein wenig außer sich, wie?\n\nNun, Ihr kennt ja das Sprichwort. Die Zeit heilt alle Wunden.\n\nAußer die des Botschafters natürlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[28003] = { id = 28003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Flammenschlund", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Flammenschlund, direkt unterhalb des großartigen Orgrimmars, zu reisen!\n\nDie Sengende Klinge ist bereit, jeden Augenblick anzugreifen und die Stadtwachen können nicht mehr viel länger aushalten! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Flammenschlund und sprecht mit Steingardist Kurjack, dem Leiter der Verteidigungsinitiative, um der Bedrohung für Orgrimmar ein für alle Mal ein Ende zu setzen!", sourceObjective = "Sprecht mit Steingardist Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[28004] = { id = 28004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Die Todesminen", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Todesminen im weit entfernten Westfall zu reisen!\n\nEure Unterstützung ist vonnöten, um ein Schiff der Defias, die Moloch, für die Horde einzunehmen und es gegen die Allianz einzusetzen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zu den Todesminen und sprecht mit Kagtha, einer Schurkin der Zerschmetterten Hand, um im Krieg gegen die Allianz behilflich zu sein.", sourceObjective = "Sprecht mit Kagtha.", sourceObjectiveStatus = "unverified-source-field" }
quests[28005] = { id = 28005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Die Todesminen", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zu den Todesminen im südlichen Westfall zu reisen!\n\nEs wird Unterstützung dabei benötigt, die Schreckensherrschaft der wiedergeborenen Bruderschaft der Defias dort zu beenden! Entschließt Ihr Euch zu helfen, so begebt Euch zu den Todesminen und sprecht dort mit Leutnant Horatio Laine, dem leitenden Ermittler in der Sache, um der Defias ein für alle Mal das Handwerk zu legen.", sourceObjective = "Sprecht mit Leutnant Horatio Laine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28006] = { id = 28006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Die Höhlen des Wehklagens", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Höhlen des Wehklagens westlich des Wegekreuzes zu reisen!\n\nNaralex muss erweckt werden, um das Brachland zu retten! Ihr solltet Eure Entscheidung weise treffen, zu den Höhlen des Wehklagens aufbrechen und mit Nalpak, einem Jünger Naralex' sprechen, um dabei zu helfen, das zerstörte Land zu heilen.", sourceObjective = "Sprecht mit Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28007] = { id = 28007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Die Höhlen des Wehklagens", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zu den Höhlen des Wehklagens westlich des Wegekreuzes zu reisen!\n\nNaralex muss erweckt werden, um das Brachland zu retten! Ihr solltet Eure Entscheidung weise treffen, zu den Höhlen des Wehklagens aufbrechen und mit Nalpak, einem Jünger Naralex' sprechen, um dabei zu helfen, das zerstörte Land zu heilen.", sourceObjective = "Sprecht mit Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28008] = { id = 28008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Burg Schattenfang", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Burg Schattenfang im südlichen Silberwald zu reisen!\n\nDer Verräter, Lord Godfrey, soll dafür bezahlen, was er Sylvanas angetan hat! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zur Burg Schattenfang und sprecht mit Todespirscherkommandant Belmont, dem Leiter der dortigen Kriegsanstrengungen, um bei der Durchführung der angemessenen Rache behilflich zu sein.", sourceObjective = "Sprecht mit Todespirscherkommandant Belmont.", sourceObjectiveStatus = "unverified-source-field" }
quests[28009] = { id = 28009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Burg Schattenfang", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Burg Schattenfang im südlichen Silberwald zu reisen!\n\nDer Verräter, Lord Godfrey, soll dafür bezahlen, was er unseren neuen Verbündeten angetan hat! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zur Burg Schattenfang und sprecht mit Rudelführer Ivar Blutfang, dem Leiter der dortigen Kriegsanstrengungen, um bei der Durchführung der angemessenen Rache behilflich zu sein.", sourceObjective = "Sprecht mit Rudelführer Ivar Blutfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[28010] = { id = 28010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Tiefschwarze Grotte", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Tiefschwarzen Grotte nördlich vom Außenposten von Zoram'gar zu reisen!\n\nDer Schattenhammerkult bedroht dort mit seinen Taten das Wohl der Welt! Ihr solltet Eure Entscheidung weise treffen, zur Tiefschwarzen Grotte aufbrechen und mit Je'neu Sancrea, einem Mitglied des Irdenen Rings sprechen, um die Bedrohung durch den Kult aufzuhalten.", sourceObjective = "Sprecht mit Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[28011] = { id = 28011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Tiefschwarze Grotte", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Tiefschwarzen Grotte westlich von Astranaar zu reisen!\n\nDer Schattenhammerkult bedroht dort mit seinen Taten das Wohl der Welt! Ihr solltet Eure Entscheidung weise treffen, zur Tiefschwarzen Grotte aufbrechen und mit Schildwache Aluwyn, der Anführerin der Truppen der Nachtelfen vor Ort sprechen, um die Bedrohung durch den Kult aufzuhalten.", sourceObjective = "Sprecht mit Schildwache Aluwyn.", sourceObjectiveStatus = "unverified-source-field" }
quests[28012] = { id = 28012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Verlies von Sturmwind", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Verlies von Sturmwind innerhalb der Stadt selbst zu reisen!\n\nIm Verlies ist es zu einer Massenrevolte gekommen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Verlies und sprecht mit Schützenkommandant Coe, dem Anführer der Wache des Verlieses, um den Aufstand niederzuschlagen.", sourceObjective = "Sprecht mit Schützenkommandant Coe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28013] = { id = 28013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Gnomeregan", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Gnomeregan westlich von Eisenschmiede zu reisen!\n\nDie Gnome brauchen Hilfe dabei, ihre Stadt wieder einzunehmen! Falls Ihr interessiert seid, begebt Euch nach Gnomeregan und sprecht mit Mör'dok, dem Rekrutierer des G-Teams, um ihnen zu helfen.", sourceObjective = "Sprecht mit Mör'dok.", sourceObjectiveStatus = "unverified-source-field" }
quests[28014] = { id = 28014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Kral der Klingenhauer", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Kral der Klingenhauer im südlichsten Teil des Südlichen Brachlands zu reisen!\n\nAuld Steinkeil braucht Hilfe dabei, die Verbreitung der Stacheleber zu unterbinden! Falls Ihr interessiert seid, begebt Euch zum Kral der Klingenhauer und sprecht mit Auld Steinkeil, einem weisen und respektierten Schamanen, um ihm zu helfen.", sourceObjective = "Sprecht mit Auld Steinkeil.", sourceObjectiveStatus = "unverified-source-field" }
quests[28015] = { id = 28015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Kral der Klingenhauer", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Kral der Klingenhauer im südlichsten Teil des Südlichen Brachlands zu reisen!\n\nAuld Steinkeil braucht Hilfe dabei, die Verbreitung der Stacheleber zu unterbinden! Falls Ihr interessiert seid, begebt Euch zum Kral der Klingenhauer und sprecht mit Auld Steinkeil, einem weisen und respektierten Schamanen, um ihm zu helfen.", sourceObjective = "Sprecht mit Auld Steinkeil.", sourceObjectiveStatus = "unverified-source-field" }
quests[28016] = { id = 28016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Friedhof", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Friedhof des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, damit sie ihren Angriff beginnen kann! Wenn Ihr Euch dazu entschließt, begebt Euch zum Friedhof des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara - einer äußerst klugen Kämpferin - um Euren Teil beizutragen.", sourceObjective = "Sprecht mit der dunklen Waldläuferin Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28017] = { id = 28017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrote Hallen", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Scharlachroten Hallen nordöstlich von Unterstadt zu reisen!\n\nAktivitäten des Kreuzzugs nehmen sowohl in den Pestländern als auch anderswo zu. Der Kriegshäuptling glaubt, dass ein Wiederaufleben im Gange ist, was NICHT toleriert werden wird.\n\nBetretet die Scharlachroten Hallen, um ihre Waffenkammer zu zerstören und ihre Bibliothek zu vernichten, bevor sie ihre Streitkräfte mobilisieren können.", sourceObjective = "Betretet die Scharlachroten Hallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28018] = { id = 28018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Waffenkammer", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Waffenkammer des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um die Offensivkräfte dort auszuschalten! Wenn Ihr Euch dazu entschließt, begebt Euch zur Waffenkammer des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euren Teil beizutragen.", sourceObjective = "Sprecht mit der dunklen Waldläuferin Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28019] = { id = 28019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich das Scharlachrote Kloster nordöstlich von Unterstadt anzugreifen!\n\nDer Scharlachrote Kreuzzug hat fortwährend Festen der Verlassenen in den Pestländern bedroht. Er MUSS vernichtet werden.\n\nBegebt Euch zum Scharlachroten Kloster, um die Befehle des Kriegshäuptlings auszuführen den Kreuzzug ein für alle Mal auszulöschen.", sourceObjective = "Betretet das Scharlachrote Kloster.", sourceObjectiveStatus = "unverified-source-field" }
quests[28020] = { id = 28020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Friedhof", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Friedhof des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nJoseph der Erweckte - ein ehemaliger Kreuzfahrer - hat um Hilfe gebeten, die dortigen Anführer auszuschalten und den Kreuzzug neu zu formieren! Wenn Ihr Euch dazu entschließt, begebt Euch zum Friedhof des Scharlachroten Klosters und sprecht mit Joseph dem Erweckten, um Euren Teil beizutragen.", sourceObjective = "Sprecht mit Joseph dem Erweckten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28021] = { id = 28021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrote Hallen", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zu den Scharlachroten Hallen nordöstlich von Unterstadt zu reisen!\n\nAktivitäten des Kreuzzugs nehmen sowohl in den Pestländern als auch anderswo zu. Ihre Majestät befürchtet, dass ein Wiederaufleben im Gange ist. Scharlachroter Fanatismus wird nirgendwo nahe der Ländereien des Königs geduldet!\n\nBetretet die Scharlachroten Hallen, um ihre Waffenkammer zu zerstören und ihre Bibliothek zu vernichten, bevor sie ihre Streitkräfte mobilisieren können.", sourceObjective = "Betretet die Scharlachroten Hallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28022] = { id = 28022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Waffenkammer", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Waffenkammer des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nJoseph der Wahnsinnige hat um Hilfe gebeten, um Herod den Scharlachroten Champion zu töten! Wenn Ihr Euch dazu entschließt, begebt Euch zur Waffenkammer des Scharlachroten Klosters und sprecht mit Joseph dem Wahnsinnigen, um ihm zu helfen.", sourceObjective = "Sprecht mit Joseph dem Wahnsinnigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28023] = { id = 28023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich das Scharlachrote Kloster nordöstlich von Unterstadt anzugreifen!\n\nWiederholte Versuche, mit dem Scharlachroten Kreuzzug zu verhandeln, sind gescheitert. Ihr Fanatismus stürzt nicht nur die zurückeroberten Pestländer ins Chaos.\n\nBegebt Euch zum Scharlachroten Kloster, um das Recht des Königs durchzusetzen. Der Einsatz tödlicher Gewalt ist wünschenswert!", sourceObjective = "Betretet das Scharlachrote Kloster.", sourceObjectiveStatus = "unverified-source-field" }
quests[28024] = { id = 28024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Hügel der Klingenhauer", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Hügel der Klingenhauer in Tausend Nadeln zu reisen!\n\nDie geheimnisvolle Koristrasza braucht Hilfe dabei, die Allianz der Geißel und der Stacheleber zu unterbinden! Falls Ihr interessiert seid, begebt Euch zum Hügel der Klingenhauer und sprecht mit Koristrasza, um ihr zu helfen.", sourceObjective = "Sprecht mit Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28025] = { id = 28025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Hügel der Klingenhauer", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Hügel der Klingenhauer in Tausend Nadeln zu reisen!\n\nDie geheimnisvolle Koristrasza braucht Hilfe dabei, die Allianz der Geißel und der Stacheleber zu unterbinden! Falls Ihr interessiert seid, begebt Euch zum Hügel der Klingenhauer und sprecht mit Koristrasza, um ihr zu helfen.", sourceObjective = "Sprecht mit Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28026] = { id = 28026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Uldaman", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Uldaman unweit Neu-Kargaths zu reisen!\n\nDie Archäologische Akademie und ihr Leiter, der Oberste Prüfer Tae'thelan Blutwächter, benötigt Unterstützung, um die mächtigen Artefakte im Inneren zu sichern! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch nach Uldaman und sprecht mit dem Obersten Prüfer, um sie in ihren Bestrebungen zu unterstützen.", sourceObjective = "Sprecht mit dem Obersten Prüfer Tae'thelan Blutwächter.", sourceObjectiveStatus = "unverified-source-field" }
quests[28027] = { id = 28027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Uldaman", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Uldaman im Ödland zu reisen!\n\nDie Forscherliga und ihr Leiter, der Oberausgrabungsleiter Durdin, benötigen Unterstützung, um gegen die großen Gefahren zu bestehen, die die Jagd nach Wissen mit sich bringt! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch nach Uldaman und sprecht mit dem Oberausgrabungsleiter Durdin, um sie in ihren Bestrebungen zu unterstützen.", sourceObjective = "Sprecht mit dem Oberausgrabungsleiter Durdin.", sourceObjectiveStatus = "unverified-source-field" }
quests[28028] = { id = 28028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung!", description = "Aufseher Schlickfaust hätte sich keinen schlechteren Zeitpunkt aussuchen können, um mich zu bitten, einem Kampf beizutreten. Meine Spitze wird bereits belagert!\n\nNichts, womit meine Wachen nicht umgehen könnten, aber trotzdem... es wird nicht leicht für mich sein, damit weiterzumachen und gleichzeitig Zwerge in diese höllische Schlucht zu entsenden.\n\nIch sage Euch was: Ihr schaltet deren Schützen aus, die unsere Festung belagern, und ich denke noch mal über Euer Angebot nach. Sie schleichen auf den Felsvorsprüngen im Osten herum.", sourceObjective = "Tötet 9 Schützen der Dunkeleisenzwerge.", completion = "Das Mindeste, was Ihr für uns getan habt, ist uns etwas Zeit und Platz zu verschaffen, unsere Versorgungslinien durch diese Belagerung zu öffnen.\n\nSeid 'n feiner {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28029] = { id = 28029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt sie in Brand!", description = "Ich weiß nicht, ob es Euch aufgefallen ist, aber mein Turm ist um einiges größer als die anderen Türme hier in der Schlucht. Manche Zwerge bilden sich etwas darauf ein, wie tief sie graben können... ich nicht. Manchmal glaube ich, ich hätte eigentlich als Wildhammerzwerg zur Welt kommen sollen.\n\nTrotzdem gefällt mir der Anblick dieser anderen Türme nicht. Wie sie sich so in den Himmel recken und meinen Turm an den Zehen kitzeln. Hier, nehmt diese Fackel und benutzt sie an den Kohlenpfannen auf den anderen Türmen. Es wird ihnen noch leidtun, diese Türme überhaupt gebaut zu haben.", sourceObjective = "Benutzt die Fackel der Vergeltung auf den vier Türmen, die den Kessel umgeben.", completion = "Ihr wisst offenbar, wie man Dinge in Brand steckt. Ein {race} mit solch einer Fertigkeit ist bewundernswert.", sourceObjectiveStatus = "unverified-source-field" }
quests[28030] = { id = 28030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bessere Kugel", description = "Diese in der Schlucht grabenden Zwerge machen wenigstens eine Sache richtig: Sie stellen qualitativ hochwertige Patronen her. Es war mir bisher nicht möglich, ihre Ergebnisse zu reproduzieren, weshalb ich dazu gezwungen war, ihnen alle Kugeln, die ich finden konnte, zu stehlen.\n\nIhr wollt meine Hilfe? Besorgt mir ein paar Hundert Dunkeleisenkugeln von ihren Schützen da unten.\n\nIch bin mir sicher, dass sie Euch mit Vergnügen eine Kugel nach der anderen geben werden, aber es könnte einfacher sein, wenn Ihr nach den Kisten Ausschau haltet, in denen sie sie lagern.", sourceObjective = "Beschafft Euch 200 Dunkeleisenkugeln.", progress = "Ein richtiger {class} hätte die Kugeln mit seinen Zähnen gefangen.", completion = "Ich verteil' die mal unter den Wachen. Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[28031] = { id = 28031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderlieferung für Langnase", description = "Ich habe einen neuen Geschäftspartner, meinen besten Freund Langnase. Gerade jetzt arbeitet er daran, die Infrastruktur für unser neues Eiscremeimporium aufzuarbeiten!\n\nEr hat unseren Kühlschlepper, unser gesamtes Inventar, und auch die Mitarbeiter in die Versunkene Ausgrabungsstätte im Südwesten befördert. Leider sehe ich gerade keine Möglichkeit, ihm die nächste Lieferung zukommen zu lassen... eine äußerst wichtige Lieferung: unsere supergeheime SchrEIS-Kryokanone!\n\nEs würd Euch nicht stören, sie ihm zu bringen, oder?", sourceObjective = "Liefert die SchrEIS-Kryokanone an Langnase in der Versunkenen Ausgrabungsstätte in Tausend Nadeln.", progress = "Das ist nicht das, was ich glaube, dass es ist? Oder doch?!", completion = "Das muss die neue SchrEIS-Kryokanone sein! Oh, ist sie nicht wunderschön?!\n\n<Langnase betrachtet Euch mit dem geübten Auge eines Geschäftsmannes.>\n\nIch werde Euch ein Geheimnis verraten, mein guter Freund: die Grundmauern eines großen Handelsimperiums werden hier gelegt!\n\nSagt mir... mögt Ihr Eiscreme?", sourceObjectiveStatus = "unverified-source-field" }
quests[28032] = { id = 28032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse des Feuermuskelmagens", description = "Es gibt so vieles, was wir bei den Incendosauriern nicht wissen. Woher kommen sie? Wie überleben sie hier draußen in den Ebenen? Und warum schmecken sie so überhaupt nicht?\n\nDer Schlüssel zum Verständnis dieser prähistorischen Bestien liegt, so glaube ich, im Feuermuskelmagen. Jeder Incendosaurier verfügt über einen. Ich hätte gerne ein paar davon, um sie zu untersuchen.\n\nIhr findet Incendosaurier, die sich am Fuße des Eisengipfels aufhalten, hauptsächlich im Westen.", sourceObjective = "Sammelt 6 Feuermuskelmägen.", progress = "Endlich bekomme ich ein paar dieser Reptilienmägen in die Finger!", completion = "Oh, die sind aber schnuckelig. Lasst mich jetzt mit meinen Innereien allein. Es gibt viel zu untersuchen!\n\n<Agnes beginnt, mit einem Stock in den Mägen herumzustochern.>\n\nJa, sehr interessant. Äußerst interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[28033] = { id = 28033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrug", description = "Was? Warum seid Ihr noch immer hier? Oh, habe ich versprochen, dass ich Euch und der Thoriumbruderschaft in Eurem Kampf helfen würde?\n\nIch habe gelogen.\n\nIch habe im Moment einfach keine Männer übrig. Ich weiß, ich habe gesagt, ich würde helfen, aber ich werde mich unter keinen Umständen von Euch überzeugen lassen, den Eisengipfel jetzt zu verlassen. Unter keinen Umständen.", sourceObjective = "Findet einen Weg, den Bergfürsten Rendan davon zu überzeugen, sich der Thoriumbruderschaft anzuschließen.", completion = "So, so, so. Einer mal ansehen, wer diesmal Lunks Hilfe brauchen!\n\nDas klingen nach Fall für Lunks einzigartigen Ansatz für Problemlösung ohne Töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28034] = { id = 28034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunks Abenteuer: Rendans Schwäche", description = "Lunk nicht klug, aber Lunk fallen Dinge auf. Heute ist Lunk aufgefallen, dass Bergzwerg es mag, Leute tanzen zu sehen.\n\nLunk mag tanzen! {name} mag tanzen! Wahrscheinlich!\n\nVielleicht finden wir mehr Zwerge die tanzen mögen. Dann wir reden mit Bergzwerg und er wird {name} zuhören.", sourceObjective = "Sprecht mit drei Eisengipfelwachen und bittet sie, bei Eurem Tanz mitzumachen.", completion = "Sprech' ich etwa undeutlich? Ich habe doch ganz klar gesagt, dass ich... nicht...\n\nHe, Ihr habt echt was drauf! Bin beeindruckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28035] = { id = 28035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterstützung des Bergfürsten", description = "In Ordnung, in Ordnung! Wenn ich gewusst hätte, dass Ihr so tanzen könnt, dann hätte ich Euch nicht den ganzen anderen Kram machen lassen.\n\nSagt Aufseher Schlickfaust, dass ich mich Euch anschließen werde. Ich treffe Euch in der Schlackengrube, <Kumpel/Mädel>! Mit den vereinten Kräften der Thoriumsspitze und des Eisengipfels werden die Schluchtzwerge gar nicht wissen, wie ihnen geschieht!", sourceObjective = "Berichtet Aufseher Schlickfaust auf der Thoriumsspitze in der Sengenden Schlucht von Eurem Erfolg.", completion = "So, Rendan steht also auf unserer Seite? Wurde auch Zeit, dass der Tölpel sich einen Ruck gegeben hat.\n\nAlso Abmarsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28036] = { id = 28036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Zul'farrak", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Zul'farrak westlich von Gadgetzan zu reisen!\n\nGadgetzan wird von den Trollen der Sandwüter und ihrer wachsenden Armee bedroht! Falls Ihr interessiert seid, begebt Euch nach Zul'farrak und sprecht mit Tran'rek, um den Goblins zu helfen.", sourceObjective = "Sprecht mit Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28037] = { id = 28037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Zul'farrak", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Zul'farrak westlich von Gadgetzan zu reisen!\n\nGadgetzan wird von den Trollen der Sandwüter und ihrer wachsenden Armee bedroht! Falls Ihr interessiert seid, begebt Euch nach Zul'farrak und sprecht mit Tran'rek, um den Goblins zu helfen.", sourceObjective = "Sprecht mit Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28038] = { id = 28038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut im Hochland", description = "Ihr habt einigen Kampfeswillen in Euch, {class}. Ihr könntet Euch im Schmelztiegel gut schlagen.\n\nWie bitte? Ihr habt noch nie vom Schmelztiegel des Gemetzels gehört? Dieser schmierige Goblin Gurgthock und sein Trollkumpel pflastern uns ständig mit Handzetteln zu, seit er sich hier im Hochland angesiedelt hat. Champions aus ganz Azeroth kämpfen dort bis zum Tod. Ihr solltet ein paar Freunde zusammentrommeln und sehen, was Ihr dort ausrichten könnt.\n\nDer Schmelztiegel ist genau im Südwesten. Sucht nach Wodin dem Trolldiener, der sich irgendwo in der Mitte eines Rings aus Knochen befindet.", sourceObjective = "Sprecht mit Wodin dem Trolldiener am Schmelztiegel des Gemetzels im Schattenhochland.", completion = "Hey, ein {class}, der ein kräftiger Bursche zu sein scheint. Könnt Ihr im Schmelztiegel bestehen? Wir haben sogar Buchmacher in Bereitschaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[28039] = { id = 28039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Maraudon", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Maraudon im westlichen Desolace reisen!\n\nMaraudon von seiner derzeitigen Verderbnis zu heilen, würde der Gesamtheit Desolaces sehr helfen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch nach Maraudon und sprecht mit Zaetars Geist. Er wird Euch leiten.", sourceObjective = "Sprecht mit Zaetars Geist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28040] = { id = 28040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Maraudon", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Maraudon im westlichen Desolace zu reisen!\n\nMaraudon von seiner derzeitigen Verderbnis zu heilen, würde der Gesamtheit Desolaces sehr helfen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch nach Maraudon und sprecht mit Zaetars Geist. Er wird Euch leiten.", sourceObjective = "Sprecht mit Zaetars Geist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28041] = { id = 28041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ködern und würgen", description = "Ihr könnt Euch gut behaupten, {name}, das muss ich Euch lassen.\n\nAber wir vom Drachenmalklan dominieren den Himmel ebenso wie das Land. Solange Ihr mir nicht beweist, dass Ihr mit einem Drachen ebenso gut umgehen könnt, wie ein Mitglied des Drachenmalklans, zählt Eure Horde nicht für mich.\n\nSchauen wir einmal, ob Ihr einen zur Blutschlucht zurückbringen könnt.\n\nAls erstes braucht Ihr einen Köder. Geht und tötet einen der Greifen, die durch die Wälder im Westen oder Nordosten von hier streifen. Achtet darauf, dass es kein gezähmter ist! Drachen hassen den Gestank von Zwergen auf ihrem Futter.\n\nBesorgt den Greifenkadaver und Ihr werdet wissen, was zu tun ist.", sourceObjective = "Besorgt einen frischen Greifenkadaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[28042] = { id = 28042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderlieferung für Langnase", description = "Ich habe vor Kurzem etwas erhalten, das einem Gnom namens Langnase geliefert werden muss. Stumpfnase wäre wohl passender, wenn Ihr mich fragt.\n\nWie dem auch sei, ich möchte, dass Ihr die Lieferung nach Südwesten, zur verlassenen Ausgrabungsstätte bringt. Er hat etwas vor, und es hat mit viel Zaster zu tun... ich kann es förmlich riechen!\n\nWerft ein Auge darauf, was er treibt, {name}, und versucht, an einen Teil seines Gewinns heranzukommen. Einen großen Teil!", sourceObjective = "Liefert die SchrEIS-Kryokanone an Langnase in der Versunkenen Ausgrabungsstätte in Tausend Nadeln.", progress = "Das ist nicht das, was ich glaube, dass es ist? Oder doch?!", completion = "<Langnase schaut Euch von Kopf bis Fuß an, aber wird aufgeregt und überglücklich, als er die Sonderlieferung sieht.>\n\nWillkommen, Freudenlieferer, herzlich willkommen! Ich kann Euch eine Einstiegsposition in einer wahrlich lebensverändernden Arbeit anbieten.\n\nDem Unternehmergeist sind die Unterschiede zwischen Horde und Allianz egal!\n\nSagt mir... mögt Ihr Eiscreme?", sourceObjectiveStatus = "unverified-source-field" }
quests[28043] = { id = 28043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachen quälen leicht gemacht", description = "<Ihr werft Euch den blutüberströmten Greifenkadaver über die Schulter. Seine Flügel schleifen auf dem Boden.>\n\n<Hochlandschwarzdrachen nisten südwestlich des Schmelztiegel des Gemetzels auf einem Kreis aus niedrigen Berggipfeln.>\n\n<Wenn Ihr den Greifenkadaver dort ablegt, wird sicherlich ein Drache beginnen, ihn zu fressen. Da er nicht wachsam sein wird, solltet Ihr in der Lage sein, ihn anzugreifen, bis er schwach genug ist, dass Ihr aufsitzen und ihn fliegen könnt.>", sourceObjective = "Lockt einen geköderten Schwarzdrachen an, greift ihn an, bis er geschwächt ist und dann reitet ihn zurück zur Blutschlucht.", completion = "Das war eine beeindruckende Flugvorführung, {name}, aber ich wünschte, sie hätte zu einem passenderen Zeitpunkt stattgefunden.\n\nNarkrall ist ein großer {class}, aber er ist auch ein ungeduldiger Narr. Er ist gerade dabei, sich umzubringen... und wir sind gerade dabei, eine unserer wichtigsten Waffen im Kampf um das Hochland zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[28044] = { id = 28044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unberührbare berühren", description = "Ich habe einen Tropfen meiner eigenen Essenz in den Schlamm gegeben. Haltet im Westen, am Rand des Schattenlauergrats, nach einem Siegelzeichen Ausschau. Stellt Euch darauf, konzentriert Euch, und gießt dann dieses Zeug über Euch. Es sollte ausreichen, damit Ihr in den Nether wechseln und sehen könnt, was WIRKLICH da ist.\n\nIhr werdet nicht alleine sein... Der Schatz des Satyrs wird von dem größten Leerenwandler beschützt, den sie beschwören konnten. Besiegt ihn, und der Schatz gehört Euch.\n\nUnd kommt heil zurück, oder dieses verrückte Weib wird mich in Stücke reißen!", sourceObjective = "Benutzt den Phasenbluttrank beim Mal des Tichondrius, um in den Nether zu wechseln, und sucht nach der Klaue des Tichondrius.", progress = "Könnt Ihr mich da drin hören, {name}? Habt Ihr die Klaue?", completion = "Die Klaue des Tichondrius...\n\nIhr haltet ein Stück des Dämons in der Hand, der die Legion in diese Wälder geführt hat, {name}. Es ist besser in unseren Händen als bei den Satyrn.\n\nHaltet still. Ich werde Euch auf unsere Ebene zurückholen und dafür sorgen, dass Ihr und die Klaue sicher hier ankommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28045] = { id = 28045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Geschmack der Welt!", description = "Unter uns ist eine Höhle - eine riesige Höhle! Etwas besseres können wir für unsere neue Kühlhalle fast nicht finden. Die Höhle ist so groß, dass alle unsere Vorräte hineinpassen und wir sogar expandieren können.\n\nLeider sind Insektentiere aus dem Nichts erschienen, als wir fast fertig waren, die Rohre zu verlegen, und haben alle meine Angestellten getötet!\n\nDamit konnte ich nicht rechnen!\n\nIch habe allerdings deshalb eine tolle Idee gehabt: Eiscreme mit Silithidengeschmack! Das wird der absolute Renner!\n\nWir brauchen nur noch die Zutaten.", sourceObjective = "Erhaltet 8 Löffel Silithidenglibber.", progress = "Habt Ihr genug Glibber für die erste Ladung Eiscreme?", completion = "Oh ja! Das wird mit Sicherheit der beste Eiscremegeschmack auf der Welt!\n\nForor und Tigule können einpacken!", sourceObjectiveStatus = "unverified-source-field" }
quests[28046] = { id = 28046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es zu Ende", description = "Wir versuchen schon die ganze Woche, an der Front brauchbaren Schrott zu sammeln. Jedes Mal, wenn wir eine Ladung zusammengestellt haben und sie zum Lager zurückbringen wollen, werden wir von der rastlosen Infanterie aus der Umgebung angegriffen. Könntet Ihr Euch dorthin begeben und sie beseitigen?", sourceObjective = "Tötet 5 rastlose Infanteristen an der Rastlosen Front. Ihr findet die Front auf der westlichen Seite der Insel, direkt vor dem Vergessenen Hügel.", completion = "Wurde auch Zeit, dass sich die Burschen jemand vorknöpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28047] = { id = 28047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rohre einfrieren", description = "Es ist an der Zeit, dass wir die SchrEIS-Kryokanone einweihen!\n\nWir konnten die Technik der Frostkanonen der Rennboote entfernen - wenn wir Gnome eines wirklich gut können, dann ist es Sachen klein machen, indem wir alles andere vergrößern!\n\nBringt die Kanone in die Höhle und friert die Rohre ein, die wir in den Wänden installiert haben. Das wird einen guten Anstoß geben!", sourceObjective = "Benutzt die SchrEIS-Kryokanone, um die vier Rohre in der Höhle einzufrieren.", completion = "Hört Ihr das, {name}? Dieses Brummen ist das hübsche Geräusch, dass von der Kühlung hervorgerufen wird.\n\nWir werden unsere Vorräte hier unten schon sehr bald lagern können. Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[28048] = { id = 28048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarmaufseher muss entfernt werden", description = "Hinten in der Höhle ist eine Art schlaues Insekt. Es scheint, es hält den Posten des Aufsehers der Silithiden inne.\n\nMeine Eiscreme schmilzt! Wie soll ich nur mein Eiscremimperium erfolgreich starten und meine Vorräte sichern, wenn dieses Ding in der Höhle ist?!", sourceObjective = "Töten den Schwarmaufseher.", completion = "Großartig! jetzt kann uns nichts mehr davon abhalten, die besten Eiscremehersteller Azeroths zu werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[28049] = { id = 28049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unsichtbare sehen", description = "Ja, ja, Eure hochnäsige Magierfreundin da hat den Nagel auf den Kopf getroffen. Die Wichtel im Schattenlauergrat verstecken den Schlüssel zu der Satyrbarriere im Nether. Es ist direkt da, aber man kann es weder sehen noch berühren, wenn man sich nicht innerhalb einer Phasenverschiebung befindet.\n\nEs scheint, als hättet Ihr kein Glück, da nur Wichtel der Phasenverschiebung mächtig sind! Ihr solltet also einfach die Augen zumachen, Euch umdrehen und mich gehenlassen...\n\nEs war ein Witz! Tut mir nicht weh! Ich brauche Schleim von den verfluchten Schlammen in diesen Ruinen. Bringt mir genug, um Euch von Kopf bis Fuß damit zu bedecken!", sourceObjective = "Sammelt 8 Einheiten verfluchten Schlamm aus den Ruinen von Constellas.", progress = "Habt Ihr den Schleim?", completion = "Ah gut, Ihr seid wieder da! Lasst mich mit ihr nicht allein! Sie ist irre!\n\nHer damit. Ihr werdet im Handumdrehen Unsichtbares sehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28050] = { id = 28050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank, der Haifisch", description = "Ich hasse Haie. Alle meine Soldaten hassen Haie ebenfalls. Und hier kommt Ihr ins Spiel, {name}.\n\nIch möchte, dass Ihr Euch zum Kap der Verlorenen Hoffnung begebt und einen riesigen Hai namens Tank aus dem Weg räumt. Mit Tank ist nicht zu spaßen, deshalb würde ich an Eurer Stelle noch ein paar Freunde mitbringen.", sourceObjective = "Ihr habt den Auftrag erhalten, Tank, einen großen Hai, der die Gewässer um das Kap der Verloren Hoffnung durchpflügt, zu töten. Das Kap kann nördlich von hier gefunden werden, an der nördlichen Küste.", completion = "Ihr macht Witze, oder? Ihr habt ihn tatsächlich besiegt? Heute Abend stehen Haifischtacos auf der Speisekarte!", sourceObjectiveStatus = "unverified-source-field" }
quests[28051] = { id = 28051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle wollen Eiscreme... und finden den Tod!", description = "Versteht mich nicht falsch... ich mag zwar gut gelaunt erscheinen, aber innerlich bin ich in in tausend Stücke gerissen. Alle meine Freunde und Angestellten sind tot.\n\nKönntet Ihr mir einen Gefallen tun? Könntet Ihr in die Höhle schwimmen und den Haken am Seil an den Köpfen der toten Angestellten befestigen? Ich ziehe sie dann hoch.", sourceObjective = "Befestigt den Haken des Abschleppseils an 10 toten Angestellten.", completion = "Vielen Dank, {name}. Sie haben ihr Leben für Eiscreme gelassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28052] = { id = 28052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Rührt den Kessel um", description = "Ich setze Euch in eine Flugmaschine, {name}.\n\nIhr werdet dafür zuständig sein, dass unsere Landung in der Schlackengrube so glatt wie möglich verläuft. Sprecht mit Eurem Flugmeister hier an der Thoriumspitze und fliegt dann runter zur Schlucht.\n\nSobald Ihr Euch dem Landepunkt nähert, werden zweifellos Horden von Dunkeleisenzwergen auf Euch warten. Benutzt die Kanonen unserer Flugmaschine, um so viele von ihnen außer Gefecht zu setzen, wie Ihr könnt, und landet dann am Eingang der Höhle. Rendan sollte bei Eurer Ankunft schon auf Euch warten.", sourceObjective = "Sprecht mit dem Flugmeister der Thoriumsspitze und benutzt dann die Kanonen der Flugmaschine der Bruderschaft, um Kesselverteidiger zu töten, bis der Bereich sicher genug ist, um ihn zu betreten.", completion = "So, da wären wir.\n\nIch hoffe, Ihr seid bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28053] = { id = 28053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk mag Euren Stil", sourceObjective = "Lunk gehört, dass Ihr Stein benutzt habt, um Feuerechse zu verbannen. Ihr gerettet Schlucht und habt nicht einmal getötet!\n\nLunk so stolz. Lunk ist gern Lehrer von {name}.\n\nVielleicht ihr das hier nehmen. Lunk es nicht brauchen. Lunk zu beschäftigt mit Abenteuern!", sourceObjectiveStatus = "unverified-source-field" }
quests[28054] = { id = 28054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduzierung des Wettbewerbs", description = "Ähnlich wie Aufseher Maltorius bin auch ich ein reicher Zwerg. Wie dem auch sei, ich habe meine Reichtümer durch harte Arbeit und weise Entscheidungen verdient, nicht durch Sklaverei.\n\nOkay, gut, durch ein wenig Sklaverei. Kaum der Rede wert.\n\nJedenfalls, das erste, was ich in diesen Höhlen sehe, sind Sklavenhändler und Zuchtmeister. Das kann ich nicht tolerieren! Während Ihr Euch durch die Höhle bewegt, solltet Ihr so viele, wie Ihr könnt, töten. Erstattet Evonice Rußraucher, die sich tiefer in der Schlackengrube befindet, Bericht über Eure Resultate.", sourceObjective = "Tötet 10 Zuchtmeister der Dunkeleisenzwerge oder Sklavenhändler der Dunkeleisenzwerge.", completion = "Das habt Ihr gut gemacht. Ich mag Sklaverei auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28055] = { id = 28055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße, furchtbare Freiheit", description = "Natürlich wollen wir so lange wir hier sind so viele Sklaven wie möglich befreien. Die meisten von ihnen werden sich uns wahrscheinlich anschließen, begierig, ihre ehemaligen Geiselnehmer zu bekämpfen.\n\nAllerdings werdet Ihr manchmal auch auf Sklaven treffen, die sich ihrer Befreiung widersetzen. Ein seltsames Phänomen, das oft das \"Durnholdesyndrom\" genannt wird.\n\nWie dem auch sei, Ihr solltet versuchen, sie zu befreien. Wenn sie sich widersetzen, müsst Ihr sie als Feinde behandeln. Erstattet Evonice Rußraucher, die sich tiefer in der Schlackengrube befindet, Bericht über Eure Resultate.", sourceObjective = "Befreit 12 Sklavenarbeiter. Wenn sie sich widersetzen: Tötet sie.", completion = "Es ist merkwürdig, dass so viele Sklaven nicht mit der Freiheit zurechtkommen. Eine Schande, dass wir das tun müssen, aber so ist das nun mal im Krieg.\n\nWidmen wir uns wieder dringenderen Aufgaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28056] = { id = 28056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Obsidion", description = "Aufseher Maltorius hat hier das Sagen, aber er ist nicht der einzige Zwerg mit Macht innerhalb der Schlackengrube. Lathoric der Schwarze und sein fürchterlicher Golem, Obsidion, lauern gerade diesen Korridor runter.\n\nWenn Ihr Euch an Lathorics Altar zu schaffen macht, sollten sie beide beschworen werden. Findet ihn, beschwört Lathoric und tötet ihn. Meldet Euch bei Evonice Rußraucher, wenn Ihr fertig seid.", sourceObjective = "Benutzt den Altar von Suntara und tötet dann Lathoric den Schwarzen und Obsidion.", completion = "Eine glorreiche Schlacht, {name}! Ich merke schon, wie sich das Blatt wendet.\n\nNun dann. Wenn Ihr bereit seid, lasst uns diesen Dunkeleisenzwergen ordentlich einheizen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28057] = { id = 28057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie durch Schlafentzug", description = "Es ist eine wenig bekannte Tatsache, dass Zwerge, und insbesondere diejenigen, die dem Dunkeleisenklan angehören, Schlaf brauchen! Viel Schlaf!\n\nJetzt frage ich Euch: Wie können sie ohne Kissen schlafen? Ganz genau, {name}... gar nicht! Und genau darum müsst Ihr ihre Kissen stehlen.\n\nSobald Ihr den Kissendiebstahl vollendet habt, solltet Ihr mit Zuchtmeister Skrange sprechen. Er befindet sich etwas tiefer in der Höhle und arbeitet mit Hansel an einem geheimen Projekt.", sourceObjective = "Beschafft Euch 16 Dunkeleisenkissen.", progress = "Was? Kissen?\n\nHä?", completion = "Wie ich sehe, spielt Evonice wieder ihre alten Spielchen. Ich, ähm, behalte diese Kissen erstmal für eine Weile.\n\nHauptsache, Ihr seid hier. Wir werden Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28058] = { id = 28058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie groß das ist!", description = "So, so, so... Na, wenn das keine Überraschung ist. Der Kissenmeister hatte ein riesiges Zierkissen und jetzt gehört es Euch. Evonice Rußraucher wird das gute Stück mit Sicherheit gern in ihre schmuddeligen Grabbelfinger bekommen. Sprecht mit ihr und seht, ob sie Euch für Eure Mühen etwas Nettes anbietet.", sourceObjective = "Bringt das Kissen von Kissenmeister zu Evonice Rußraucher in der Sengenden Schlucht.", progress = "Na, das ist mal ein riesiges Kissen! Wo habt Ihr das her?", completion = "Das ist besser, als ich es mir je vorstellen konnte! Das magische Kissen des Zimmermädchens gehört mir! Und ob Ihr eine schöne Belohnung für diese Errungenschaft bekommt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28059] = { id = 28059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einnahme der Festung", description = "Habt Ihr die Festung auf der Nordseite der Insel gesehen, {name}? Von dort aus überwacht Festungslord Farson seine Operationen.\n\nFarson verfügt über eine kleine Gruppe loyaler Anhänger, die uns seit unserer Ankunft Ärger machen. Wir haben ein paar unserer Leute heimlich in die Burg geschickt und sie konnten uns seinen genauen Aufenthaltsort dort melden.\n\nWürdet Ihr ihn für uns erledigen?", sourceObjective = "Man hat Euch gebeten, Festungslord Farson in der Farsonfestung zu töten. Die Farsonfestung werdet Ihr auf der Nordseite der Insel finden.", completion = "Ihr habt ihn getötet? Das haben wir wochenlang vergeblich versucht! Wir danken Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28060] = { id = 28060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtige Zwielichtbande", description = "Hansel und ich sind hier auf geheimer Mission: um Aufseher Maltorius zu töten. Während unser Hauptziel unverändert bleibt - Erzherzog Calcinder zu vernichten - wird es nicht schaden, den berüchtigten Aufseher der Schlackengrube auszuschalten, wenn wir schon mal da sind.\n\nDas einzige Problem ist, dass Hansel nur darauf vorbereitet war, es mit einem Zwerg aufzunehmen, doch es scheint, als hätte Maltorius einen Besucher... einen Gesandten des Schattenhammers!\n\nSprecht mit Hansel und helft ihm aus. Dann begebt Euch weiter den Korridor hinunter und entlang des Balkons draußen, um Aufseher Schlickfaust anzutreffen.", sourceObjective = "Sprecht mit Hansel Bleihand und helft ihm, Aufseher Maltorius und Zwielichtfürst Arkkus zu bekämpfen.", completion = "Der Schattenhammer, wie? Das hätte ich mir denken können. Ich bin froh, dass Ihr rechtzeitig zu ihrer Hilfe gekommen seid.\n\nEs sieht so aus, als hätten wir entgegen aller Aussichten unseren Vorstoß bis vor Calcinders Haustür getrieben. Jetzt ist es an der Zeit, die Sache zu Ende zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28061] = { id = 28061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calcinders Handlanger", description = "Man kann auch zu tief graben, {name}. Man findet die reichhaltigsten Mineralienadern zwar tief unter der Oberfläche, aber auch die bösartigsten Kreaturen.\n\nWie zum Beispiel Feuerelementare.\n\nCalcinders Günstlinge durchstreifen die Höhle vor uns. Jeder von ihnen trägt ein Stück von Calcinders Übel in sich. Vernichtet so viele von ihnen, wie Ihr könnt und zeigt keine Reue.", sourceObjective = "Tötet 6 sengende Flammengespenster.", sourceObjectiveStatus = "unverified-source-field" }
quests[28062] = { id = 28062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woher er kam", description = "Erzherzog Calcinder windet sich im hinteren Teil genau dieser Höhle. Wir sind kurz davor, ihn zu töten... allerdings werden wir das nicht tun.\n\nCalcinder hier zu töten hat keinerlei Bedeutung. Seine Akolythen können ihn leicht wiederbeleben. Stattdessen werden wir ihn verbannen.\n\nIch habe Euch zuvor gebeten, einen wertvollen Stein vom Schattenhammer zu erlangen. Diesen werden wir nun gegen Calcinder einsetzen. Verwickelt ihn in einen Kampf, schwächt ihn und setzt dann dieses Gerät gegen ihn ein. Er wird aus diesem Reich verbannt werden.\n\nViel Glück, {name}.", sourceObjective = "Schwächt Erzherzog Calcinder und setzt dann den Geweihten Tripetrizin ein, um ihn zu verbannen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28063] = { id = 28063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst keine Waffen zurück", description = "Nachschub für den Kampf ist auf diesem Felsen beinahe unmöglich zu bekommen. Jedes Mal, wenn wir die Horde abwehren, kommt es uns vor, als ob wir mit Stöcken und Steinen kämpfen.\n\nWir haben Berichte erhalten, dass Festungslord Farson auf der Nordseite der Insel große Vorräte an Gewehren hat, die wir gebrauchen könnten. Könnt Ihr Euch dorthin begeben und das überprüfen?\n\nSeid vorsichtig, {name}, die Anhänger Farsons werden alles tun, um ihn zu beschützen.", sourceObjective = "Besorgt 12 rostige Gewehre aus Burg Farson auf der Nordseite der Halbinsel von Tol Barad.", progress = "Habt Ihr mit den Gewehren Glück gehabt?", completion = "Danke, dass Ihr die für uns eingesammelt habt, {name}. Ist schwierig, ohne Gewehre eine Schlacht zu schlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28064] = { id = 28064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in der Bruderschaft", description = "Ihr solltet zur Thoriumsspitze zurückkehren. Aufseher Schlickfaust und die Thoriumbruderschaft werden sich fragen, wie Ihr im Kampf gegen Calcinder abgeschnitten habt.", sourceObjective = "Erstattet Aufseher Schlickfaust auf der Thoriumsspitze in der Sengenden Schlucht Bericht.", completion = "Unsere Aufgabe hier ist vollbracht und es ist allein Euch zu verdanken, {name}. Bitte wählt Euch aus unserem Besitz aus, wonach Euch der Sinn steht. Darüberhinaus möchte ich Euch zu einem vollwertigen Mitglied unseres Ordens machen. Willkommen in der Thoriumbruderschaft, {name}. Euch Bruder nennen zu können erfüllt mich mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[28065] = { id = 28065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In ihrer Haut", description = "Wir haben in den letzten Wochen mindestens drei verschiedene Aufklärungstrupps losgeschickt, um die Farsonfestung auszukundschaften. Leider ist keiner von ihnen mit Informationen zurückgekehrt.\n\nIm Moment können wir nur hoffen, dass sie gefangen genommen, aber am Leben sind. Ich möchte, dass Ihr die Festung infiltriert und dabei helft, unsere Soldaten zurückzuholen. Einfach wird das nicht, {name}, aber wenn uns jemand helfen kann, dann Ihr.", sourceObjective = "Bringt einen Gefangenen der Farsonfestung in Sicherheit. Die Festung befindet sich am nordwestlichen Spize der Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[28066] = { id = 28066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Der Versunkene Tempel", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Versunkenen Tempel unweit von Steinard zu reisen!\n\nDie Trolle des Stammes der Atal'ai versuchen dort, Hakkar den Seelenschinder zu beschwören! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Versunkenen Tempel und sprecht mit dem grünen Drachen Lord Itharius, der bereit ist, diesen gefährlichen Trollen ein Ende zu machen.", sourceObjective = "Sprecht mit Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28067] = { id = 28067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Der Versunkene Tempel", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Versunkenen Tempel unweit der Sumpftidenwacht zu reisen!\n\nDie Trolle des Stammes der Atal'ai versuchen dort, Hakkar den Seelenschinder zu beschwören! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Versunkenen Tempel und sprecht mit dem grünen Drachen Lord Itharius, der bereit ist, diesen gefährlichen Trollen ein Ende zu machen.", sourceObjective = "Sprecht mit Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28068] = { id = 28068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Schwarzfelstiefen", description = "König Anduin Wrynn fordert alle diensttauglichen Abenteurer auf, umgehend in die Schwarzfelstiefen nordwestlich von Morgans Wacht zu reisen!\n\nDie Dunkeleisenzwerge stellen für die Rotkammbewohner eine ernst zu nehmende Bedrohung dar! Falls Ihr interessiert seid, begebt Euch in die Schwarzfelstiefen und sprecht mit Morgan, die nach langer Abwesenheit wieder unter uns ist und ihre Rache an den Dunkeleisenzwergen verüben möchte.", sourceObjective = "Sprecht mit Morgan.", completion = "Ihr seht so aus, als könntet Ihr es kaum erwarten, ein paar hundert Dunkeleisenzwerge im Namen der Gerechtigkeit zu töten.\n\nPerfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28069] = { id = 28069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Schwarzfelstiefen", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich in die Schwarzfelstiefen westlich vom Flammenkamm zu reisen!\n\nDie Dunkeleisenzwerge haben bereits das von der Allianz gehaltene Rotkammgebirge angegriffen und wenn sie nicht kontrolliert werden, könnten sie schon bald eine Gefahr für unsere wenigen Hordestellungen im südlichen Azeroth darstellen.\n\nFalls Ihr interessiert seid, begebt Euch in die Schwarzfelstiefen und sprecht mit Oberhenker Nuzrak, der die Expeditionskorps von Kargath reformiert, um den Dunkeleisenzwergen ein für alle Mal ein Ende zu bereiten.", sourceObjective = "Sprecht mit Oberhenker Nuzrak.", completion = "Wir konnten dieses kleine Gebiet einnehmen, aber um mehr zu erreichen benötigen wir Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28070] = { id = 28070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Schwarzfelsspitze", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Schwarzfelsspitze westlich vom Flammenkamm zu reisen!\n\nNefarians Armeen und die Anhänger Rend Schwarzfausts bedrohen die Existenz der Horde! Falls Ihr interessiert seid, begebt Euch zur Schwarzfelsspitze und sprecht mit Acride, unserem einzigen Kontakt vor Ort, der die Invasion aufhalten könnte.", sourceObjective = "Sprecht mit Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28071] = { id = 28071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Schwarzfelsspitze", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Schwarzfelsspitze nordwestlich von Morgans Wacht zu reisen!\n\nNefarians Armeen und die Anhänger Rend Schwarzfausts bedrohen sein Königreich! Falls Ihr interessiert seid, begebt Euch zur Schwarzfelsspitze und sprecht mit Acride, unserem einzigen Kontakt vor Ort, der die Invasion aufhalten könnte.", sourceObjective = "Sprecht mit Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28072] = { id = 28072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Düsterbruch - Wucherborkenviertel", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Wucherborkenviertel in Düsterbruch östlich der Mondfederfeste zu reisen!\n\nAlzzin der Wildformer hat Verderbnis in die Gegend gebracht und könnte ganz Düsterbruch einnehmen! Falls Ihr interessiert seid, begebt Euch zum Wucherborkenviertel und sprecht mit Furgus Wucherborke, dem einzigen nicht verderbten Wesen, das in der Gegend noch am Leben ist.", sourceObjective = "Sprecht mit Furgus Wucherborke.", sourceObjectiveStatus = "unverified-source-field" }
quests[28073] = { id = 28073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Düsterbruch - Wucherborkenviertel", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Wucherborkenviertel in Düsterbruch westlich von Camp Mojache zu reisen!\n\nAlzzin der Wildformer hat Verderbnis in die Gegend gebracht und könnte ganz Düsterbruch einnehmen! Falls Ihr interessiert seid, begebt Euch zum Wucherborkenviertel und sprecht mit Furgus Wucherborke, dem einzigen nicht verderbten Wesen, das in der Gegend noch am Leben ist.", sourceObjective = "Sprecht mit Furgus Wucherborke.", sourceObjectiveStatus = "unverified-source-field" }
quests[28074] = { id = 28074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Düsterbruch - Hauptstadtgärten", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich in die Hauptstadtgärten in Düsterbruch westlich von Camp Mojache zu reisen!\n\nDer gefallene Hochgeborene Prinz Tortheldrin benutzt den riesigen Dämon Immol'thar, um die Gärten unter Kontrolle zu halten! Falls Ihr interessiert seid, begebt Euch in die Hauptstadtgärten und sprecht mit Estulan, einem reinen Hochgeborenen, der erst vor Kurzem aus der Vergessenheit erschienen ist und nun versucht, die gefallene Stadt für sein Volk zurückzuerobern.", sourceObjective = "Sprecht mit Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28075] = { id = 28075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Düsterbruch - Hauptstadtgärten", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich in die Hauptstadtgärten in Düsterbruch östlich der Mondfederfeste zu reisen!\n\nDer gefallene Hochgeborene Prinz Tortheldrin benutzt den riesigen Dämon Immol'thar, um die Gärten unter Kontrolle zu halten! Falls Ihr interessiert seid, begebt Euch in die Hauptstadtgärten und sprecht mit Estulan, einem reinen Hochgeborenen, der erst vor Kurzem aus der Vergessenheit erschienen ist und nun versucht, die gefallene Stadt für sein Volk zurückzuerobern.", sourceObjective = "Sprecht mit Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28076] = { id = 28076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Der Norden Düsterbruchs", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich in den nördlichen Teil Düsterbruchs östlich der Mondfederfeste zu reisen!\n\nKönig Gordok und seine wachsende Armee der Oger der Gordok stellen in der Gegend die größte und mächtigste Bedrohung für uns dar! Falls Ihr interessiert seid, begebt Euch in den Norden Düsterbruchs und sprecht mit dem Druiden der Kralle, der bereits zur Erkundung vorgeschickt wurde.", sourceObjective = "Sprecht mit dem Druiden der Kralle.", sourceObjectiveStatus = "unverified-source-field" }
quests[28077] = { id = 28077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Der Norden Düsterbruchs", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich in den nördlichen Teil Düsterbruchs westlich von Camp Mojache zu reisen!\n\nKönig Gordok und seine wachsende Armee der Oger der Gordok stellen in der Gegend die größte und mächtigste Bedrohung für uns dar! Falls Ihr interessiert seid, begebt Euch in den Norden Düsterbruchs und sprecht mit dem Oger der Steinbrecher, der bereits zur Erkundung vorgeschickt wurde.", sourceObjective = "Sprecht mit dem Oger der Steinbrecher.", sourceObjectiveStatus = "unverified-source-field" }
quests[28078] = { id = 28078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Haupttor von Stratholme", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Haupttor von Stratholme nördlich vom Pestwald zu reisen!\n\nDer Schreckenslord Balnazzar hat Kreuzfahrer des scharlachroten Kreuzzugs getötet und sie als Auferstandende wiederbelebt! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.", sourceObjective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28079] = { id = 28079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Haupttor von Stratholme", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Haupttor von Stratholme nördlich vom Pestwald zu reisen!\n\nDer Schreckenslord Balnazzar hat Kreuzfahrer des scharlachroten Kreuzzugs getötet und sie als Auferstandene wiederbelebt! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.", sourceObjective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28080] = { id = 28080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Dienstbotentor von Stratholme", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Dienstbotentor von Stratholme nordwestlich des Nordpassturms zu reisen!\n\nBaron Aurius Totenschwur, ehemaliger Paladin der Silbernen Hand und kürzlich wiederbelebter Sohn von niemand Geringerem als Baron Totenschwur selbst, führt nun die restlichen Streitmächte der Geißel an! Falls Ihr interessiert seid, begebt Euch zum Dienstbotentor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.", sourceObjective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28081] = { id = 28081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Dienstbotentor von Stratholme", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Dienstbotentor von Stratholme, nordwestlich des Nordpassturms zu reisen!\n\nBaron Aurius Totenschwur, ehemaliger Paladin der Silbernen Hand und kürzlich wiederbelebter Sohn von niemand Geringerem als Baron Totenschwur selbst, führt nun die restlichen Streitmächte der Geißel an! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.", sourceObjective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28082] = { id = 28082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scholomance", description = "König Anduin Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Scholomance östlich von Andorhal zu reisen!\n\nJüngste nekromantische Aktivitäten in diesem Gebiet weisen auf Dunkelmeister Gandling und erneute Bemühungen der Ausbildung mächtiger Zauberer für die Geißel hin. Falls Ihr interessiert seid, begebt Euch nach Scholomance und setzt dem bösen Treiben ein Ende.", sourceObjective = "Betretet Scholomance.", sourceObjectiveStatus = "unverified-source-field" }
quests[28083] = { id = 28083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scholomance", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Scholomance östlich von Andorhal zu reisen!\n\nJüngste nekromantische Aktivitäten in diesem Gebiet weisen auf Dunkelmeister Gandling und erneute Bemühungen der Ausbildung mächtiger Zauberer für die Geißel hin. Falls Ihr interessiert seid, begebt Euch nach Scholomance und setzt dem bösen Treiben ein Ende.", sourceObjective = "Betretet Scholomance.", sourceObjectiveStatus = "unverified-source-field" }
quests[28084] = { id = 28084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Krom'gar", sourceObjective = "Ihr habt jetzt Zugang zum Vorratslager der Krom'gar, {name}! Für ein geringes Entgelt verkaufe ich Euch Kampfausrüstung, die Euch beim Vernichten Eurer Feinde dienlich sein wird! Es hängt von Eurem Rang in der Armee ab, welche Waren ich Euch verkaufen kann. Besucht mein Geschäft, wann immer Ihr einen neuen Rang erhaltet.\n\nLOK'TAR OGAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[28085] = { id = 28085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Steilhang", description = "Vielen Dank für Eure Hilfe, {name}. Ihr solltet Euch mit Pao'ka Bergrausch in Steilhang unterhalten, südwestlich von hier.\n\nVielleicht weiß er, wo sich die Ältestengreisin befindet?", sourceObjective = "Sprecht mit Pao'ka Bergrausch in Steilhang in Tausend Nadeln.", completion = "Ich weiß nichts von Magatha, der Ältestengreisin. Ich weiß aber, dass der Schattenhammer den Steilhang zerstört.\n\nKönnt Ihr mir dabei helfen, sie aufzuhalten, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[28086] = { id = 28086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit die Wyverlinge!", description = "Die Fallensteller arbeiten daran, alle jungen Windreiter zusammenzutrommeln. {name}, könnt Ihr Euch der Sache annehmen und die Wyverlinge befreien?", sourceObjective = "Befreit 12 Steilhangwyverlinge.", completion = "Sie sind so wertvoll. Eines Tages werden sie auch stark sein, aber bis dahin müssen sie beschützt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28087] = { id = 28087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod allen Fallenstellern!", description = "Für die dreckigen Fallensteller der Schattenhämmer haben wir nur eines übrig: den Tod!\n\nBringt mir ihre Netze, {name}.", sourceObjective = "Sammelt 8 Netze der Fallensteller.", progress = "Welcher Wahnsinn kann jemanden dazu bringen, so grauenvolle Taten zu vollbringen?", completion = "Ab dem heutigen Tage werden keine Fallen mehr hier zu finden sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[28088] = { id = 28088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freilassung von Klingenherz", description = "Der Schattenhammer hält das Alphamännchen von Steilhang fest. Ihr müsst Euch nach Osten begeben und Klingenherz befreien, bevor das Rudel seinen Anführer verliert.", sourceObjective = "Befreit Klingenherz von allen Ketten, die ihn festhalten.", progress = "Ihr müsst Klingenherz befreien, bevor sie ihn in ihr böses Lager verfrachten!", completion = "Der große Klingenherz ist eine majestätische Kreatur. Er hat mir von seiner Dankbarkeit und Wertschätzung für Euch berichtet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28089] = { id = 28089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Vorgebirge des Hügellands!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands zu melden. Die Kriegsmaschinerie der Verlassenen bewegt sich immer weiter vorwärts und sichert Lordaeron für die Horde!\n\nUm das Südwachttor zu erreichen, müsst Ihr der Straße in Richtung Süden durch den Silberwald folgen und die östliche Abzweigung nehmen, die ins Vorgebirge des Hügellands führt.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Meldet Euch bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands.", completion = "Ich habe mich schon gefragt, wann die Verstärkung eintreffen würde. Macht Euch bereit, {name}. Zeit, etwas Gerechtigkeit walten zu lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28090] = { id = 28090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Waren", description = "Die Tore weiter unten im Canyon sind geschlossen. Wir haben ausgekundschaftet, dass es eine Art Stein gibt, den sie in Kisten in ihren Karawanen mitführen, und zum Öffnen der Tore benutzen.\n\nGeht dort hinunter und durchsucht die Leichen der Wachen nach einem Truhenschlüssel. Wenn Ihr ihn findet, benutzt ihn bei einer der großen Truhen auf den Karawanenwagen und bringt den Torstein zu mir zurück.", sourceObjective = "Bergt einen Torstein der Zwielichtkarawane. Die Speerwächter sollten Schlüssel bei sich tragen, die Euch Zugang zu den Truhen mit den Torsteinen verschaffen.", progress = "Wisst Ihr, wir könnten die Tore wahrscheinlich einfach aufsprengen, aber wie wir unseren Sprengmeister kennen, sollten wir das Risiko lieber nicht eingehen.", completion = "Gut gemacht!\n\nSieht nicht nach etwas Besonderem aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28091] = { id = 28091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichte Aufgabe", description = "Der Hinterhalt ging problemlos vonstatten. Die meisten Wachen sind tot, aber einige sitzen immer noch bei den Wagen fest.\n\nIhr könnt sie genau im Westen in dem Canyon unter uns sehen. Geht dorthin und erledigt sie, damit wir diesen Angriff ins Rollen bringen können.", sourceObjective = "Tötet 8 Zwielichtspeerwärter.", completion = "Ausgezeichnet. Jetzt können wir unsere Bodentruppen in Richtung Grim Batol in Bewegung setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28092] = { id = 28092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn der Schlüssel passt", description = "Die Wyrms haben den Kampf bereits in den Himmel über Grim Batol getragen. Jetzt ist es an uns, unsere Leute auf dem Boden dorthin zu bewegen und die Tore zu sichern.\n\nIhr sollt wissen, was auf dem Spiel steht, {class}. Grim Batol ist die Quelle der Verstärkung für den Schattenhammer im ganzen Hochland. Wenn wir das hier nicht unterbinden, werden wir die Kämpfe, die vor uns liegen, nicht gewinnen können.\n\nIch schicke die Goblinschwadron mit Euch. Erreicht das Tor im Südosten und öffnet es. Flick sollte weitere Anweisungen für Euch haben, wie es ab da weiter geht.", sourceObjective = "Führt die Goblinschwadron zu dem geschlossenen Tor des Drachenmals.\n\nWenn Ihr die Goblinschwadron verliert, kehrt zu Kriegsfürst Krogg zurück, damit Ihr neue Truppen zugeteilt bekommt.", completion = "Es klappt doch immer wieder aufs Neue.", sourceObjectiveStatus = "unverified-source-field" }
quests[28093] = { id = 28093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordringen", description = "Bis jetzt war das gute Arbeit. Wir sollten den Eingang zu Grim Batol direkt hinter dem nächsten Tor finden.\n\nIch habe Befehle, den Eingang zu sichern und der Verstärkung den Weg zu verstellen, während der Rest unserer Leute durch den Pfad, den wir durch den Canyon freigemacht haben, vorwärts drängt. Ich glaube, wir werden es bald geschafft haben, vielleicht kann ich Ticker dann ein wenig mehr Spaß gönnen.\n\nMachen wir uns auf den Weg hinunter in den Canyon im Südwesten - wir sollten das nächste Tor recht schnell finden.", sourceObjective = "Führt die Goblinschwadron am nördlichen Tor des Drachenmals vorbei zum Eingang von Grim Batol.\n\nWenn Ihr die Goblinschwadron verliert, kehrt zu Kriegsfürst Krogg zurück, damit Ihr neue Truppen zugeteilt bekommt.", progress = "Willkommen, {race}.", completion = "Das Tor ist frei. Sobald Eure Leute den Canyon durchquert haben, werden wir mit Euren Anführern über den nächsten Schritt sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28094] = { id = 28094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg ebnen", description = "Meine Befehle lauten, Euch nach Süden durch die Tore des Drachenmals zum Eingang von Grim Batol zu begleiten. Wir sollen einen Weg freimachen, damit der Rest der Männer uns folgen und den Eingang sichern kann.\n\nÜbersetzung: Tötet alles, das sich bewegt und schämt Euch nicht, wenn Ihr Spaß dabei habt.\n\nDie Jungs werden langsam unruhig. Auf geht's.", sourceObjective = "Tötet 30 Kultisten des Schattenhammers entlang der Wyrmbiege, während Ihr Euch zum Eingang von Grim Batol durchkämpft.", completion = "Es sieht beinahe leicht aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28095] = { id = 28095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb nach draußen" }
quests[28096] = { id = 28096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beamtenmikado", description = "Wer sich zuerst bewegt, hat verloren, <mein Lieber/meine Liebe>. Nur so kann man es als hochrangiger Offizier der Verlassenen zu etwas bringen. Ja, das hier ist in der Tat das gute Leben und Ihr werdet es leben!\n\nIch möchte, dass Ihr diese Befehle nehmt und sie an die kleinen Anfänger ausgebt, die hier vorbeikommen und nach Arbeit suchen. Wem Ihr was gebt, ist Euch überlassen.\n\nWenn Ihr bereit seid, steigt auf mein braves Skelettross auf - damit man Euch nicht übersieht - und fangt an, das Leben zu leben! Was bedeutet, einfach hier herumzustehen und zu warten.", sourceObjective = "Gebt 3 Quests aus.", progress = "Na, wie ist der \"Schreibtischjob\" so?", completion = "Na, wie war's? So, wie Ihr es Euch immer vorgestellt hattet? Aufregend, nicht wahr?\n\nNein?\n\n<Darthalia seufzt.>\n\nIch sehe, dass Ihr ein wahrer Held seid. Ihr braucht Action. Ich denke, ein \"Schreibtischjob\" ist nichts für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28097] = { id = 28097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tore von Grim Batol", description = "Krogg hat den Angriff begonnen, um durch den Canyon zu drängen. Er ist kurz hinter dem Tor im Südosten.\n\nIch werde die Schwadron zusammenrufen, damit wir uns dem Angriff anschließen. Wir treffen Euch dort unten.", sourceObjective = "Sprecht mit Kriegsfürst Krogg in der Wyrmbiege.", completion = "Der Canyon ist gut geschützt, aber die Ablenkung, die die Drachen liefern, dürfte reichen, damit wir durchbrechen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28098] = { id = 28098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmelsmeister der Schatten", description = "Richtofen der Schattenhimmelsmeister befindet sich oben und über Zwielichthorst südöstlich von hier. Es ist egal, was wir hier unten tun - wenn wir ihn nicht ausschalten, wird alle Hoffnung für Steilhang verloren sein.\n\nKlingenherz ist zwar zu schwer verletzt, um Euch im Kampf zu helfen, aber er kann Euch zum Horst fliegen. Der Rest liegt dann bei Euch, {name}.\n\nIch wünsche Euch viel Glück.", sourceObjective = "Fliegt mit Klingenherz nach Zwielichthorst und bekämpft Schattenhimmelsmeister Richtofen.", completion = "Die Wyverlinge haben das gemacht? Sie müssen Euch sehr schätzen, dafür dass Ihr sie befreit habt.\n\nIch danke Euch, {name}. Ihr habt den Steilhang gerettet!", sourceObjectiveStatus = "unverified-source-field" }
quests[28099] = { id = 28099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasha'krak", description = "Nach den Informationen, die Ihr geliefert habt, denke ich, dass einer der Handlanger des \"Erzherzogs\" seinen Blick bereits auf die Thoriumspitze gerichtet hat.\n\nSein Name ist Rasha'krak und er patrouilliert entlang der Lavaseen südlich von uns. Er sieht so aus wie die latenten Feuerelementare, die in der Nähe wüten. Es gibt aber einen kleinen Unterschied: die Armschienen der Bindung, die er an seinen Handgelenken trägt.\n\nFindet ihn und bringt mir diese Armschienen, {name}. Ich brauche einen Beweis dafür, dass wir uns in Gefahr befinden, bevor wir uns auf Kriege mit den Elementaren einlassen.", sourceObjective = "Beschafft Rasha'kraks Armschienen der Bindung.", progress = "Ich werde nicht gegen Elementare kämpfen, bis wir bewiesen haben, dass sie eine Bedrohung für uns sind.", completion = "Leider ist es so, wie ich vermutet hatte. Diese Armschienen tragen die unauslöschlichen Zeichen des Feuerlords und seiner Handlanger.\n\nAlso gut. Da sich weder Streitkräfte der Horde noch der Allianz in der Nähe dieser gottverlassenen Schlucht befinden, bleibt es an der Thoriumbruderschaft hängen, diesen Erzherzog aufzuhalten, bevor er noch mehr Böses verbreitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[28100] = { id = 28100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sprechendes Totem", description = "Das Furbolgdorf im Süden ist die Heimat der Totenwaldfelle, die Todfeinde der Holzschlundfeste sind. Sie sind verderbt und widerwärtig, wie so vieles andere. Die Fäulnis des Waldes hat sie in den Wahnsinn getrieben.\n\nNun ist allerdings etwas Außergewöhnliches in der Nähe des Lagers geschehen. Reisende, die hier vorbeikamen, haben gesagt, dass das Totem an der Straße zu ihnen gesprochen hat.\n\nIch habe noch nie etwas gehört, wenn ich mich ihm genähert habe. Vielleicht spricht es mit Euch, {name}? Vielleicht könnt Ihr für mich herausfinden, was dort vor sich geht.", sourceObjective = "Sprecht mit dem Totem von Ruumbo in der Nähe des Lagers der Totenwaldfelle.", completion = "Ihr da... ja, Ihr! Ich habe Euch, {race}, als meinen Champion erwählt! Ihr werdet die Arbeit von Ruumbo verrichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28101] = { id = 28101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias' Befehl", description = "Die Ereignisse in letzter Zeit machen es noch offensichtlicher, dass es zur Absicherung unseres Volkes nicht ausreicht, hier einfach nur auszuharren und sporadische Angriffe auf Grim Batol auszuführen - geschweige denn, dass wir Grim Batol zurückerobern könnten. Wir müssen aggressiver sein und sie mitten ins Herz treffen.\n\nIch habe zugestimmt, Eurem Kommandanten Drachen zur Unterstützung zu senden. Sie hatten ohnehin schon über einem Plan gebrütet, wie man auf Grim Batol losschlagen kann, also solltet Ihr Eure Aufmerksamkeit zunächst einmal darauf konzentrieren.\n\nIhr solltet Mathias Shaw am Drachenmalpass im Canyon südlich unter uns finden.", sourceObjective = "Sprecht mit Meister Mathias Shaw am Drachenmalpass.", completion = "Die roten Drachen sind bereit, zu helfen! Das war sicher nicht leicht. Die Allianz dankt Euch.\n\nAls die Drachen sich mit uns in Verbindung setzten, hatten wir bereits einen Plan ausgearbeitet, eine Zwielichtkarawane aus dem Hinterhalt heraus anzugreifen. Jetzt helfen sie uns, deren Rückzug zu unterbinden.\n\nDer Kampf tobt noch immer. Ihr könnt auf jeden Fall helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28102] = { id = 28102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekämpft die Macht", description = "Es ist Zeit für den entscheidenden Schlag gegen die Jadefeuer!\n\nWenn Ihr bereit seid, durch ihre verderbte Barriere zu brechen und ihrem Anführer den Kampf anzusagen, würde ich Euch auch darum bitten, uns gegen die niederen Satyrn zu unterstützen. Unsere Druiden kämpfen erbittert, aber Eure Stärke könnte helfen, die Schlacht zu unseren Gunsten zu wenden.\n\nZeigt den Jadefeuersatyrn, dass Ihre Macht nicht länger die Vorherrschaft über diese Lande hat!", sourceObjective = "Tötet 8 Jadefeuerschurken oder Jadefeuerschattenpirscher in den Ruinen von Constellas.", completion = "Einige der verbliebenen Satyrn sind in die Tiefen der Wälder geflohen, aber sie haben schwere Verluste erlitten. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28103] = { id = 28103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichte Aufgabe", description = "Der Hinterhalt ging problemlos vonstatten. Die meisten Wachen sind tot, aber einige sitzen immer noch bei den Wagen fest.\n\nGeht dorthin und erledigt sie, damit wir diesen Angriff ins Rollen bringen können.", sourceObjective = "Tötet 8 Zwielichtspeerwärter.", completion = "Ausgezeichnet. Jetzt können wir unsere Bodentruppen in Richtung Grim Batol in Bewegung setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28104] = { id = 28104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Waren", description = "Die Tore weiter unten im Canyon sind geschlossen. Wir haben ausgekundschaftet, dass es eine Art Stein gibt, den sie in Kisten in ihren Karawanen mitführen, und zum Öffnen der Tore benutzen.\n\nGeht dort hinunter und durchsucht die Leichen der Wachen nach einem Truhenschlüssel. Wenn Ihr ihn findet, benutzt ihn bei einer der großen Truhen auf den Karawanenwagen und bringt den Torstein zu mir zurück.", sourceObjective = "Bergt einen Torstein der Zwielichtkarawane. Die Speerwächter sollten Schlüssel bei sich tragen, die Euch Zugang zu den Truhen mit den Torsteinen verschaffen.", progress = "Sie sind ein wenig zu selbstbewusst geworden. Das scheint zunehmend der Grund für den Untergang der mächtigsten Armeen zu sein.", completion = "Gut gemacht!\n\nSieht nicht nach etwas Besonderem aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28105] = { id = 28105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kavem der Gefühllose", description = "Kavem war schon grausam genug, bevor die Neferset sich Todesschwinge verschrieben haben. Sein Vergnügen, anderen Schmerzen zuzufügen, grenzt inzwischen an Wahnsinn.\n\nEr hat jetzt die Schlüssel für unsere Fesseln.\n\nEr haust in dem Gebäude neben uns zu meiner Rechten.\n\nFindet ihn und nehmt seinen Schlüssel an Euch. Zögert nicht und erweist ihm keine Gnade. Er würde Euch die Kehle aufschlitzen und sich nichts dabei denken.", sourceObjective = "Beschafft den Schlüssel aus Neferset von Kavem dem Gefühllosen.", progress = "Ihr seid wieder da. Habt Ihr den Schlüssel?", completion = "Ausgezeichnet, {name}. Bald werden wir hier herauskommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28106] = { id = 28106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tore von Grim Batol (NICHT LÖSCHEN. NICHT ALS VERALTET FLAGGEN)" }
quests[28107] = { id = 28107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg ebnen", description = "Meine Befehle lauten, Euch nach Süden durch die Tore des Drachenmals zum Eingang von Grim Batol zu begleiten. Wir sollen einen Weg freimachen, damit der Rest der Männer uns folgen und den Eingang sichern kann.\n\nÜbersetzung: Tötet alles, was sich bewegt und schämt Euch nicht, wenn Ihr Spaß dabei habt.\n\nDie Jungs werden langsam unruhig. Auf geht's.", sourceObjective = "Tötet 30 Kultisten des Schattenhammers entlang der Wyrmbiege, während Ihr Euch zum Eingang von Grim Batol durchkämpft.", completion = "Es sieht beinahe leicht aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28108] = { id = 28108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn der Schlüssel passt", description = "Die Wyrms haben den Kampf bereits in den Himmel über Grim Batol getragen. Jetzt ist es an uns, unsere Leute auf dem Boden dorthin zu bewegen und die Tore zu sichern.\n\nIch will, dass Ihr wisst, was auf dem Spiel steht, {class}. Grim Batol ist die Quelle der Verstärkung für den Schattenhammer im ganzen Hochland. Wenn wir sie hier nicht aufhalten, werden wir die Kämpfe, die vor uns liegen, nicht gewinnen können.\n\nIch schicke eine Schwadron aus Hochstade mit Euch. Erreicht das Tor im Südosten und öffnet es. Euer Hauptmann sollte weitere Anweisungen für Euch haben, wie es ab da weiter geht.", sourceObjective = "Führt die Schwadron aus Hochstade zu dem geschlossenen Tor des Drachenmals.\n\nWenn Ihr Eure Schwadron verliert, kehrt zu Meister Mathias Shaw zurück, damit Ihr neue Truppen zugeteilt bekommt.", completion = "Wie eine gut geölte Kriegsmaschine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28109] = { id = 28109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordringen", description = "Bis jetzt war das gute Arbeit.\n\nWir sollten den Eingang zu Grim Batol direkt hinter dem nächsten Tor finden. Ich habe Befehle, den Eingang zu sichern und der Verstärkung den Weg zu verstellen, während der Rest unserer Leute durch den Pfad, den wir durch den Canyon freigemacht haben, vorwärts drängt.\n\nMachen wir uns auf den Weg hinunter in den Canyon im Südwesten - wir sollten das nächste Tor recht schnell finden.", sourceObjective = "Führt Eure Schwadron an dem nördlichen Tor des Drachenmals vorbei zum Eingang von Grim Batol.\n\nWenn Ihr die Schwadron verliert, kehrt zu Meister Mathias Shaw zurück, damit Ihr neue Truppen zugeteilt bekommt.", completion = "Das Tor ist frei! Sobald Eure Leute durch den Canyon hindurch sind, werden wir mit Euren Anführern über den nächsten Schritt sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28110] = { id = 28110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb nach draußen" }
quests[28111] = { id = 28111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am Azurschacht", description = "Die Produktivität unserer Spinnenfarm am Azurschacht hat einen Stillstand erreicht. Hauptmann Keyton hat uns darum gebeten, sofort Hilfe zu schicken. Keyton behauptet, dass die Minenspinnen sich weigern, Befehlen zu gehorchen, und durchdrehen. Außerdem plündert eine Gruppe Küstenmurlocs unsere Vorräte. Könnt Ihr dort hinuntergehen und den Sachen nachgehen? Helft Keyton und der Spinnendompteurin, {name}.\n\nIhr findet den Azurschacht im Südosten in der Nähe der Küste.", sourceObjective = "Meldet Euch bei Hauptmann Keyton am Azurschacht im Vorgebirge des Hügellands.", completion = "Wir stecken ein wenig in der Klemme, {class}. Die Spinnen von Sarus werden ein wenig dreist, weil wir sie seit Tagen nicht füttern konnten. Wenn wir fortgehen, werden die Murlocs unseren Außenposten übernehmen! Schlimmer noch, Aufseher Stillwasser drüben an den Schlickfeldern verlangt, dass wir ihm noch mehr Menschen schicken! Er ist unersättlich! Wir brauchen Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[28112] = { id = 28112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus der Verlorenen Stadt", description = "Alles ist bereit! Löst meine Ketten und befreit Eure Freunde.\n\nWir müssen uns beeilen, bevor der Neferset-Abschaum bemerkt, dass wir etwas vorhaben!\n\nWenn wir es schaffen, begebt Euch zu meinem Bruder, König Phaoris, für eine Belohnung.", sourceObjective = "Befreit Prinz Nadun und sprecht mit König Phaoris in Ramkahen in Uldum.", completion = "Es stimmt also? Ein Außenstehender hat Prinz Nadun vor den Neferset gerettet? \n\nWir stehen wirklich in Eurer Schuld, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[28113] = { id = 28113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unzerstörbare zerstören", description = "Mit der Klaue sind wir bereit, die Verteidigung der Jadefeuersatyrn zu durchbrechen.\n\nBegebt Euch in die Ruinen im Nordwesten. Hinter der Frontlinie der Satyrn werdet Ihr einen engen Pfad finden, der zu ihrem verderbten Mondbrunnen führt. Eine riesige Wand aus dämonischen Flammen blockiert den Pfad, aber die Klaue des Tichondrius sollte sie bannen können.\n\nHinter der Barriere findet Ihr den Anführer dieser Streitkräfte, Xavathras, der den verderbten Mondbrunnen bewacht. Tötet ihn, sobald Ihr das Hindernis überwunden habt!", sourceObjective = "Tötet Xavathras.", completion = "Seht Ihr, was man mit ein bisschen Zusammenarbeit erreichen kann?\n\nIch werde dafür sorgen, dass die Klaue Leuten übergeben wird, die genug Verantwortungsbewusstsein haben, um so etwas aufzubewahren... das heißt, sofern sie nicht zerstört werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[28114] = { id = 28114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großartige Ernte", description = "Genau südöstlich vom Südwachttor findet Ihr unsere Operation zur Zähmung von Spinnen. Im Laufe der Jahre haben wir eine enge Verbindung zu Spinnen des Hügellandes aufgebaut und haben es geschafft, die hübschen kleinen Tierchen zu zähmen und zu züchten. Jetzt sind die Spinnen für uns normale Haustiere und Nutztiere für den Kampf! Es sind so vielseitige Kreaturen!\n\nIhr müsst für mich auf die Felder im Südosten gehen und vorsichtig Eier einsammeln, die in Bären ausgebrütet werden. Liefert die Ernte bei Sarus an der Mine ab.", sourceObjective = "Sammelt 60 Krabblereier ein.", progress = "Habt Ihr meine Ernte mitgebracht?", completion = "Wunderbar! Nun müssen diese Eier nur noch in eine hübsche, dunkle Nische innerhalb der Mine gelegt werden und dann kann das Wunder des Lebens geschehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28115] = { id = 28115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Zenit überschritten", description = "Bären sind seelenlose Tiere, die auf diese Welt gesetzt wurden, um uns zu quälen. Nur dem Einfallsreichtum der Verlassenen haben wir es zu verdanken, dass wir einen Weg gefunden haben, um die Bären nutzbar zu machen, damit sie einem Zweck dienen! Wir benutzen die Bären auf unserer Spinnenfarm als lebendige Nährquellen für die Eier. Unsere Spinnen legen ihre Eier in das Fleisch der Bären und die Eier ernähren sich von dem Fleisch und dem Blut der Tiere.\n\nNachdem sie ihren Zweck erfüllt haben, müssen die Monster eingeschläfert werden. Reist nach Südosten und tötet die infizierten Bären, die ihren Lebenszenit überschritten haben.", sourceObjective = "Tötet 8 infizierte Bären.", completion = "Die Bärengötter sind grausame Herren. Sie werden diese Welt weiterhin bis ans Ende aller Tage mit Bären bevölkern. Es ist unser Recht als zivilisierte Menschen, uns diese Plagegeister zunutze zu machen - zum Nutzen aller!", sourceObjectiveStatus = "unverified-source-field" }
quests[28116] = { id = 28116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klageveilchen", description = "Wir müssen uns sorgfältig vorbereiten, bevor wir Jaedenar angreifen. Die Magie der Hexenmeister und Dämonen in Jaedenar ist stark und wir werden unsere eigenen Schutzzauber benötigen, bevor wir hineingehen.\n\nWir benötigen nur noch eine letzte Zutat: Klageveilchen, die in den Hügeln nordwestlich des feindlichen Lagers wachsen.\n\nSammelt die Klageveilchen und trefft Euch dann mit meinem Feldassistenten. Er wird Euch sagen, was als Nächstes zu tun ist.", sourceObjective = "Sammelt 8 Klageveilchen.", progress = "Habt Ihr die Klageveilchen schon finden können, {name}? Wir brauchen sie so schnell es geht.", completion = "Wunderbar. Greta hat eine weise Entscheidung getroffen, als sie Euch gebeten hat, diese Aufgabe zu übernehmen. Ich werde die Kräuter umgehend verarbeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[28117] = { id = 28117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefen säubern", description = "Wie schön, Euch zu sehen, {name}. Jetzt da wir Tol Barad eingenommen haben, fängt die Schlacht erst an.\n\nGleich östlich von hier haben wir einen Zellenblock entdeckt, den Ihr ausräumen müsst. Er steckt zum Bersten voll mit Geistern, die seit Ewigkeiten dort eingesperrt sind.\n\nBeseitigt so viele wie möglich und meldet Euch dann bei mir.", sourceObjective = "Ihr habt den Auftrag, 9 Geister beliebigen Typs in den Verfluchten Tiefen gleich östlich der Baradinfestung zu töten.", completion = "Ihr seid lebendig davongekommen? Ihr seid stärker als ich es bin, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28118] = { id = 28118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Erzmagier", description = "Seit wir auf Tol Barad gelandet sind, versuchen wir, den Zellenblock in den Verfluchten Tiefen auszuräumen. Jedes Mal, wenn wir uns nähern, taucht dieser Erzmagier auf und drängt uns zurück.\n\nJetzt, da wir die Insel eingenommen haben, ist es an der Zeit, es noch einmal zu versuchen. Begebt Euch dorthin und bringt mir seinen Stab zum Beweis, dass Ihr den Auftrag erledigt habt.", sourceObjective = "Ihr müsst Erzmagier Galus töten und mit seinem Stab aus den Verfluchten Tiefen östlich der Baradinfestung zurückkehren.", progress = "Konntet Ihr den Erzmagier beseitigen?", completion = "Galus ist tot? Fantastische Arbeit, {name}. Jetzt können wir die Putzkolonne dort hinunterschicken und den Zellenblock für neue Gefangene vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28119] = { id = 28119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinheit aus Verderbnis", description = "Die Blumen, die Ihr mir gebracht habt, waren die Hauptzutat.\n\nSchutzbarrieren umgeben die Schattenfeste und werden von dämonischen Kohlenpfannen aufrechterhalten. Wenn wir den Schattenrat aus dem Teufelswald vertreiben wollen, müssen diese Kohlenpfannen erlöschen.\n\nDiese Phiole enthält Klageveilchen und die Magie der Wildnis. Füllt sie am verderbten Mondbrunnen im Zentrum von Jaedenar und kehrt zu mir zurück.", sourceObjective = "Füllt die leere Feldflasche mit Wasser aus dem verderbten Mondbrunnen im Zentrum von Jaedenar.", progress = "Habt ihr das Wasser aus dem verderbten Mondbrunnen?", completion = "Das reicht vollkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28120] = { id = 28120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Vergangenheit lernen", description = "Jetzt, da wir auf dieser elenden Insel endlich Fuß gefasst haben, können wir Untersuchungen beginnen, wie sie in diesen Zustand geraten ist. Einige unserer Truppen haben Tagebücher am Eingang zum Zellblock östlich von hier in den Verfluchten Tiefen entdeckt.\n\nDiese Tagebücher sind für unsere ältesten Schreiber im Basislager von besonderem Interesse. Ihr müsst vier von den Tagebüchern finden und so schnell Ihr könnt zu mir zurückbringen.\n\n{name}, seid vorsichtig dort unten, da wimmelt es nur so von Untoten.", sourceObjective = "Man hat Euch gebeten, vier verstaubte Gefängistagebücher aus den Verfluchten Tiefen östlich der Baradinfestung zu bergen.", progress = "Konntet Ihr die Tagebücher bergen? Berichten zufolge wurden sie sowohl innerhalb, als aus auch außerhalb der Zellen dort unten gesehen.", completion = "Diese Tagebücher sind in ausgezeichnetem Zustand, {name}. Wir werden sofort anfangen, sie zu entschlüsseln. Nur die Zeit wird zeigen, welche Geheimnisse sie bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28121] = { id = 28121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streitkräfte von Jaedenar", description = "Der Schattenrat hält die Verderbnis dieser Lande aufrecht. Bei Jaedenar im Nordwesten verehren sie die Dämonen der Brennenden Legion und arbeiten daran, den Weg für die Rückkehr ihrer Herren in diese Welt vorzubereiten.\n\nDas Gebiet wird von Hunden, Wächtern, Adepten und Kultisten von Jaedenar patrouilliert - Schlägern, die die Augen für die noch boshafteren Streitkräfte unter ihnen offenhalten. Sie werden die ersten sein, die sterben, damit diese Wälder nicht länger leiden müssen.", sourceObjective = "Tötet 12 Soldaten von Jaedenar.", completion = "Gut, {name}! Jetzt, da ihre Zahlen zurückgehen, können wir bald unseren Angriff auf ihre Truppen tief in der Schattenfeste starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28122] = { id = 28122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein riesiges Problem", description = "Endlich haben wir diesen gottverdammten Fels eingenommen und dann treibt so ein riesiger Ettin hier sein Unwesen und schaltet unsere Wachpatrouillen aus!\n\n{name}, trommelt ein paar Verbündete zusammen und erledigt den Ettin. Wir können nicht zulassen, dass die Bestie hier alles verwüstet.\n\nSeid auf der Hut, von der Front wird gemeldet, dass er mit einem riesigen Baum bewaffnet ist. Und er hat keine Skrupel, ihn einzusetzen.", sourceObjective = "Ihr wurdet beauftragt, Problim zu töten, einen Riesenettin, der die Wege von Tol Barad unsicher macht.", completion = "Ihr habt ihn tatsächlich getötet?! Ich kann es kaum glauben!", sourceObjectiveStatus = "unverified-source-field" }
quests[28123] = { id = 28123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonenkette", description = "Narkrall hat mir das Geheimnis seines Einflusses über die Drachen in dieser Gegend verraten. Ich dachte, die Dämonenkette wäre ein Mythos, aber er hatte sie die ganze Zeit.\n\nUnd jetzt ist der Narr dabei, sie zu verlieren.\n\nSein Leben bedeutet mir nichts, aber die Drachenmalorcs können es sich nicht leisten, das Artefakt zu verlieren. Folgt ihm nach Norden zu Donnermar. In der Stadt wird Chaos herrschen, also könnt Ihr vielleicht unbemerkt landen. Kehrt mit der Dämonenkette zu mir zurück, selbst, wenn Ihr sie Narkralls Leiche entreißen müsst.\n\nFindet das Artefakt, {name}.", sourceObjective = "Bringt die Dämonenkette an Euch.", progress = "Habt Ihr sie? Ja? Das Schicksal Drachenmals hängt von der Dämonenkette ab.", completion = "<Zaela nimmt die blutbespritzte Kette und wickelt sie um ihre Hand und ihr Handgelenk.>\n\nWenn die Geschichten wahr sind, {name}, war es diese Kette, an der Todesschwinge einst die Dämonenseele angebunden hatte, die nach seinem Befehl erschaffen worden war, um die anderen Drachenschwärme unter seine Kontrolle zu bringen. Die Dämonenseele wurde bereits vor langer Zeit zerstört, aber vielleicht enthält dieser Klumpen Elementiumerz noch Reste dieser Kraft...\n\nIhr habt heute Großes geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28124] = { id = 28124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter zum Bollwerk", description = "{name}, als sich die Wyverlinge um den Himmelsmeister gekümmert haben, kam Lakota Windweise vorbei. Sie sagte mir, sie möchte Euch am Schattenbollwerk treffen, östlich von hier.\n\nIch glaube, Magatha Grimmtotem wird dort festgehalten.", sourceObjective = "Sprecht mit Lakota Windweise am Schattenbollwerk in Tausend Nadeln.", completion = "Ich bin froh, dass Ihr kommen konntet.\n\nKümmert Euch nicht um mein Aussehen. Es schien weise, meine Kleidung entsprechend anzupassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28125] = { id = 28125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was zum Anziehen", description = "Ich habe eine Idee, wie wir Euch in die Nähe der Anführer bekommen können, ohne dass man Euch gleich tötet. Zuerst braucht Ihr aber etwas zum Anziehen.\n\nIch schlage vor, dass Ihr von dort vorne eine ihrer Rüstungen schnappt.", sourceObjective = "Sammelt 10 Teile Schattenhammerrüstungen.", progress = "Wie viele Rüstungsteile konntet Ihr finden?\n\nFür Eure nächste Aufgabe solltet Ihr wirklich gut verkleidet sein.", completion = "<Lakota sieht über den Zustand der Rüstung besorgt aus, besonders über die vielen Blutflecken.>\n\nIhr habt auch wirklich sorgfältig geschaut, {name}? Naja, das wird reichen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28126] = { id = 28126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammen des Schutzes ersticken", description = "Die Kohlenpfannen sind überall in der Schattenfeste verteilt.\n\nBetretet den Tunneleingang zur Schattenfeste und folgt den unterirdischen Korridoren. Löscht jede einzelne Flamme der Kohlenpfannen und der Schutz, den der Rat eingerichtet hat, wird für mindestens eine Weile zusammenbrechen.", sourceObjective = "Benutzt das gereinigte Wasser aus dem Mondbrunnen, um die vier Kohlenpfannen des Schutzes in der Schattenfeste zu löschen.", completion = "Jetzt, da die Kohlenpfannen gelöscht sind, können die Druiden des Smaragdkreises die Schattenfeste betreten und die restlichen Kultisten beseitigen. Mit der Zeit kann dieser Ort vielleicht wieder als der Grabhügel genutzt werden, der er einst war.\n\nIhr habt meinen Dank, {name}. Bitte, nehmt diese Belohnung an.", sourceObjectiveStatus = "unverified-source-field" }
quests[28127] = { id = 28127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht sie aus", description = "Magatha ist nicht die einzige Gefangene des Schattenhammers.\n\nWährend Ihr in ihrem Lager im Süden seid, solltet Ihr so vielen wie möglich beim Ausbruch helfen.", sourceObjective = "Rettet 5 Bollwerkgefangene von den Zwielichtkerkermeistern.", completion = "Ihr gebt so viel, ohne etwas zurückzuverlangen.\n\nDie Bevölkerung von Tausend Nadeln ist dankbar, und ich bin es auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28128] = { id = 28128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der innere Kreis", description = "Jetzt, da ihre äußeren Wächter fort sind, sind die höheren Mitglieder des Schattenrates dran.\n\nTief in den verderbten Grabhügeln findet Ihr mächtige Hexenmeister, Jäger, Vollstrecker, Dunkelwirker und Legionäre von Jaedenar.\n\nSie müssen besiegt werden, wenn diese Lande gerettet werden sollen!", sourceObjective = "Tötet 12 Verteidiger in der Schattenfeste.", completion = "Die Säuberung der Schattenfeste wird lange dauern und viel Anstrengung erfordern, aber ohne Euren Sieg gegen den Schattenrat, wäre sie überhaupt nicht möglich. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28129] = { id = 28129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dämonenprinz", description = "Die Jadefeuersatyrn, die so viel vom Teufelswald überrannt haben, arbeiten direkt mit dem Schattenrat zusammen.\n\nDiese Satyrn sind direkt dem uralten und mächtigen Prinz Xavalis unterstellt. Einige sagen, er ist der Sohn von Xavius, dem ersten Satyr, und von Sargeras höchstpersönlich gesegnet. \n\nEgal, welchen Ursprungs er ist, er muss sterben, wenn wir die Satyrn der Jadefeuerregion zerschlagen und unsere Grabhügel zurückerobern wollen. Begebt Euch tief in die Schattenfeste und tötet ihn. Gewährt ihm keine Gnade, denn auch er wird Euch keine gewähren.", sourceObjective = "Tötet Prinz Xavalis.", sourceObjectiveStatus = "unverified-source-field" }
quests[28130] = { id = 28130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht die freundlichste Stadt", description = "Seid Ihr schon oben in Rostberg gewesen, {name}? Ich schlage vor, dass Ihr eine scharfe Klinge bei Euch tragt, wenn Ihr in die Richtung geht.\n\nDie Bewohner dieser Stadt sehen ganz in Ordnung aus, aber da geht irgendwas Verdächtiges vor. Wir haben Berichte erhalten, dass sie unsere Soldaten vorne und hinten wegfangen. Wir haben allmählich die Nase voll davon, deshalb müsst Ihr für uns dorthin gehen und ein bisschen aufräumen.\n\nErledigt so viele von ihnen, wie Ihr könnt, und meldet Euch dann wieder bei mir, wenn Ihr fertig seid.", sourceObjective = "Kommandant Marcus Johnson hat Euch gebeten, 14 Dorfbewohner in Rostberg zu töten. Rostberg befindet sich nördlich des Basislagers auf der rechten Seite.", completion = "Ich habe Euch ja gesagt, dass das Dorf voller Irrer ist. Aber Ihr habt gut dort aufgeräumt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28131] = { id = 28131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelte Versuchung", description = "Moora und Salia sind die persönlichen Dienerinnen von Schattenlord Fel'dan. Lasst Euch nicht von ihnen in die Irre führen!\n\nDiese widerwärtigen Sukkuben benutzen Listen und finstere Magie, um Sterbliche tief in die Schattenfeste zu locken. Diejenigen, die in ihre Fänge geraten, erhalten eine Gehirnwäsche oder werden von Fel'dan seinen dämonischen Herren geopfert.\n\nDie beiden kämpfen wie aus einem Guss und sind unzertrennlich, was sie zu einer erheblichen Bedrohung macht. Geht tiefer in die Schattenfeste und tötet sie.", sourceObjective = "Tötet Moora und Salia.", sourceObjectiveStatus = "unverified-source-field" }
quests[28132] = { id = 28132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effiziente Ausgrabungen", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nNachdem Ihr den Inhalt überflogen habt, wird Euch klar, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist.\n\nEine Karte auf der Rückseite des Umschlags zeigt, dass der Verfasser einen Bunker in der südwestlichen Region von Uldum besitzt.\n\nVielleicht wäre es angebracht, sich einmal vorzustellen.", sourceObjective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand:", completion = "Sieh mal an, es ist eines von Schnottz' Pamphleten.\n\nIch werde das mal an mich nehmen, wenn Ihr nichts dagegen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28133] = { id = 28133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbändige Wut", description = "Narkralls Drache Torth hat den vergeblichen Angriff auf Donnermar überlebt und jetzt ist die Kreatur von ihrem früheren Herrn befreit.\n\nTorth will sich an dem Drachenmalklan rächen und hat die Blutschlucht bereits einmal bombardiert. Er wird solange wiederkommen, bis wir ihn endgültig aufgespießt haben. Es wird Zeit, dass wir die Dämonenkette einsetzen.\n\nTorths altes Nest ist eine kleine Höhle in den Hügeln westlich von hier. Dort haben wir ein kleines Lager names \"Der Rachen\" aufgeschlagen.\n\nTrefft mich am Rachen und wir werden Torth erledigen.", sourceObjective = "Reist zum Rachen und sprecht mit Zaela. Tötet Torth.", completion = "Einmal frei von der Kette, starb Torth lieber, als sich noch einmal unterwerfen zu lassen. Ich bewundere die Kreatur. Ich werde aus seiner Haut einen Rüstungssatz herstellen lassen.\n\nSo viel weiß ich jetzt: Der Drachenmalklan kann allein nichts ausrichten, wenn die Allianz sich hinter die Wildhämmer stellt. Narkrall hat das bewiesen. Und Ihr habt die Macht der Horde immer wieder unter Beweis gestellt.\n\nIch werde unsere Drachengeschwader neu aufbauen und außerhalb der Bastion des Zwielichts Position beziehen. Ihr solltet weiterhin hier im Rachen und anderswo im Hochland aushelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28134] = { id = 28134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevorstehende Vergeltung", description = "Jetzt, da Ihr angemessen belohnt worden seid, kann ich hoffentlich offen mit Euch sprechen.\n\nIhr habt meinem Königreich einen großen Gefallen erwiesen, aber Ihr habt auch einen zerbrechlichen Friedensprozess aus dem Gleichgewicht gebracht.\n\nIch habe versucht, die Freilassung meines Bruders auf rein diplomatischem Wege zu erreichen, um Blutvergießen zu vermeiden.\n\nJetzt wird der Feind sicherlich zurückschlagen wollen.\n\nSprecht mit Nomarch Teneth an den Tahretgründen im Osten, mit Sonnenpriester Asaris am Siegel des Sonnenkönigs im Norden und mit Asaq in Mar'at im Westen. Findet heraus, wann der Feind zuschlagen wird.", sourceObjective = "Sprecht mit Nomarch Teneth an den Tahretgründen, mit Sonnenpriester Asaris am Siegel des Sonnenkönigs und mit Asaq in Mar'at.", completion = "Orsis! Natürlich!\n\nWie konnte ich das übersehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28135] = { id = 28135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'Akirs Rache", description = "Hört zu, {name}. Orsis wurde nicht von einem natürlichen Sandsturm getroffen. Das waren die Helfer von Al'Akir.\n\nDer Elementarlord der Luft ist fest mit Todesschwinge verbündet und es war nur eine Frage der Zeit, bevor er seine Untergebenen auf meine Leute hetzte.\n\nOrsis wurde als Warnung für uns angegriffen. Wir müssen uns beeilen und unseren Brüdern jede erdenkliche Hilfe anbieten.\n\nTrefft Euch mit Nadun am Handelsposten Arsad außerhalb von Mar'at. Ich werde Vorbereitungen treffen, damit wir uns um die Versprengten und Verwundeten kümmern können.", sourceObjective = "Sprecht mit Prinz Nadun am Handelsposten Arsad außerhalb von Mar'at in Uldum.", completion = "Seht Ihr, was Todesschwinges Helfer angerichtet haben? Das große Orsis ist jetzt beinahe vollkommen von Sand bedeckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28136] = { id = 28136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter Euch!", description = "Die drei Anführer des Schattenbollwerks sind mächtig und Ihr solltet sie nicht unterschätzen, {name}. Glücklicherweise seht Ihr mit Eurer Verkleidung aus wie ein Schattenhammerkultist.\n\nTragt Eure Verkleidung und sprecht mit Chiffrenmeister Deethuk, Kommandant Luntenschnell und Elementarist Starion getrennt voneinander. Wartet, bis sie Euch den Rücken zuwenden und führt Euren Angriff dann schnell aus!", sourceObjective = "Ermordet Chiffrenmeister Deethuk, Kommandant Luntenschnell und Elementarist Starion.", completion = "Jetzt, da die drei ausgeschaltet sind, sollten die vereinten Streitkräfte des Freiwindpostens mit dem Rest der Kultisten hier alleine fertigwerden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28137] = { id = 28137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrt einen hungrigen Mann das Fischen... oder das Stehlen", description = "Rostberg. Dieser Ort ist für uns Fluch und Segen, {name}. Ich habe keine Ahnung, wo die Banditen so gut Fischen gelernt haben, aber ich habe jetzt keine Zeit, mir darüber Sorgen zu machen.\n\nIhr müsst Euch dort hinunter begeben und so viele Ihrer Fischvorräte stehlen, wie möglich. Wir leben von Küchenabfällen, seit wir die Insel zurückerobert haben und dies ist die beste Gelegenheit für uns, an vernünftige Essensvorräte zu kommen.\n\nAchtet auf die Verstohlenen dort oben, Berichten zufolge befinden sie sich hauptsächlich innerhalb der Stadtmauern.", sourceObjective = "Ihr müsst 22 Rostbergseebarsche aus Rostberg stehlen. Die Fische befinden sich an Fäden aufgehängt auf Ständern bei den Docks im hinteren Teil des Dorfes. Rostberg befindet sich nördlich des Basislagers auf der rechten Seite.", progress = "Ist Euch der Überfall gelungen und habt Ihr uns Fisch besorgt?", completion = "Diese Fische sind genau das, was wir brauchen, {name}. Sie werden die Truppen ernähren und in guter Verfassung halten und das ist unser wichtigstes Anliegen. Ihr habt Euch wirklich für uns eingesetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28138] = { id = 28138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menschenbefall", description = "Diese Mine war einst das Herzstück des Bergbaus der Allianz im Hügelland. Jetzt dient sie als Brutstätte für unsere getreuen Spinnen, obwohl die Menschen sie immer noch in gewisser Weise besetzt halten.\n\n<Keyton grinst.>\n\nAber lasst uns zum Geschäft kommen! Aufseher Stillwasser hat um weitere Arbeiter für die Schlickfelder gebeten. Ich möchte, dass Ihr die Mine mit diesen Fußfesseln betretet und Menschen des Hügellands für die Arbeit auf den Feldern gefangennehmt.\n\nHolt sie aus ihrer Netzlähmung und schlagt sie, bis sie sich ergeben, bevor Ihr ihnen die Fußfesseln anlegt.", sourceObjective = "Nehmt 8 Menschen des Hügellands gefangen.", completion = "Die sind genau richtig. Ich frage mich, was der Aufseher mit ihnen vorhat. Das Letzte, was ich gehört habe, war, dass die Schlickfelder von furchtbaren Dingen überrannt worden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28139] = { id = 28139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Code des Chiffrenmeisters", description = "{name}, Magatha wird mit speziell verschlüsselten Fesseln festgehalten. Wir können sie nur befreien, wenn wir den Code besorgen können.\n\nChiffrenmeister Deethuk am Schattenbollwerk südöstlich von hier hat eine Chiffriermaschine. Die Codes sind darin gespeichert.\n\nBesorgt sie!", sourceObjective = "Erhaltet den Code des Chiffrenmeisters.", progress = "Habt Ihr den Code, um die Fesseln der Ältestengreisin lösen zu können?", completion = "Gut. Jetzt gibt es nur noch eine Sache, um die wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28140] = { id = 28140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ältestengreisin", description = "Ihr habt den Code. Jetzt müsst Ihr nur noch in den östlichen Teil des Bollwerks und die Ältestengreisin befreien.\n\nViel Erfolg, {name}. Ich danke Euch für alles, was Ihr bisher für uns getan habt.", sourceObjective = "Deaktiviert das Steuergerät für Magathas Fesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[28141] = { id = 28141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte des Sonnenkönigs", description = "Das Siegel des Sonnenkönigs dient als Verteidigungsmechanismus für Ramkahen.\n\nAls die Barriere um Uldum fiel, sahen wir, wie die Vorhut der Wüstenwanderer aus Tanaris unsere Grenzen überschritt.\n\nSie griffen diese heilige Stätte auf ihrem Weg in den Westen an und raubten die Relikte, die ihr einst ihre Macht verliehen.\n\nHolt die Relikte für uns zurück. Ohne sie sind wir machtlos und können uns nicht gegen ihre Angriffe aus der Wüste verteidigen.", sourceObjective = "Beschafft 4 Relikte des Sonnenkönigs.", progress = "Hattet Ihr Erfolg?", completion = "Danke. Die Gerüchte, die ich über Euch gehört habe, erweisen sich doch als wahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[28142] = { id = 28142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ödnis", description = "Magatha hat gesagt, sie werde Euch außerhalb von Schattenödnis östlich von hier treffen.", sourceObjective = "Sprecht mit Magatha Grimmtotem in Schattenödnis in Tausend Nadeln.", completion = "Ihr habt lange gebraucht. Meint Ihr, wir sind zum Spaß hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[28143] = { id = 28143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ödnis", description = "Ihr solltet die Ältestengreisin nicht warten lassen.\n\nSie sagte, dass sie Euch außerhalb der Anhöhung von Schattenödnis östlich von hier treffen wird.", sourceObjective = "Sprecht mit Magatha Grimmtotem in Schattenödnis in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[28144] = { id = 28144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische kleine Monster!", description = "Das lange Stück Küste direkt südlich unseres Standortes, das sich von Westen nach Osten erstreckt, ist bekannt als der Weststrand. Entlang des Weststrands findet Ihr zwei Dinge: Murlocs und gestohlene \"Vorräte\".\n\n<Keyton streckt seine Hände in die Luft und macht das Zeichen für Anführungsstriche mit seinen Fingern.>\n\nDiese verdammten diebischen Murlocs haben hinter unserem Rücken zugeschlagen und unsere \"Vorräte\" gestohlen.\n\nSarus und ich können diesen Posten nicht verlassen. Ihr müsst für uns zum Weststrand gehen und diese \"Vorräte\" wiederbeschaffen!", sourceObjective = "Bergt 6 \"Vorräte\" des Lagers der Verlassenen.", progress = "Bringt unsere \"Vorräte\" zurück, {name}!", completion = "Wenigstens werden wir auf zukünftige Vorfälle vorbereitet sein. \"Vorräte\" wie diese zu bewegen ist ein riskantes Vorhaben. Man weiß nie, wer meint, seine große Klappe aufreißen zu müssen.\n\n<Keyton zieht das, was man für eine Augenbraue halten könnte, hoch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28145] = { id = 28145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenmittel für Giftblut", description = "Iset hat versucht, diesen heiligen Boden gegen die Banditen der Wüstenwanderer zu verteidigen, als sie ihn geplündert haben.\n\nAnscheinend haben sie ein starkes Gift verwendet, das von Giftblutskorpiden stammt.\n\nNehmt diese Phiole und sammelt Gift aus ihren Kadavern, damit ich ein Gegenmittel herstellen kann. Ich fürchte, Iset bleibt nicht mehr viel Zeit.", sourceObjective = "Füllt die Gegengiftphiole mit dem Gift von 8 Giftblutskorpidkadavern.", completion = "Danke, {name}. Vielleicht können wir Iset doch noch retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28146] = { id = 28146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delikatessen der Küste!", description = "Meine Spinnen sind hungrig und aufgebracht! Sie haben seit Tagen nichts zu fressen bekommen und beginnen, unsere menschlichen Gefangenen anzuknabbern. Das geht so nicht. Wir brauchen diese Menschen, damit sie in den Schlickfeldern arbeiten.\n\nIch möchte, dass Ihr eine meiner hungrigen Minenspinnen mit hinausnehmt und ihr Murlocs vom Weststrand südlich von hier zum Fraß vorwerft. Sie wird fressen, was immer Ihr tötet! Je mehr, desto besser!", sourceObjective = "Füttert die hungrige Minenspinne mit 12 Murlocs vom Weststrand.", completion = "Das sollte sie für ein paar Tage glücklich und zufrieden machen. Ihr habt da gute Arbeit gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28147] = { id = 28147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lila ist Eure Farbe", description = "Soweit ich das sagen kann, haben sich die Stopfwampenoger direkt vor der Höhle hier noch nicht dem Schattenhammer angeschlossen. Wenn wir schlau sind, können wir die beiden Gruppierungen gegeneinander ausspielen.\n\nLasst uns mit einem kleinen Trick beginnen, den ich in Silithus gelernt habe. Zunächst müssen wir für Euch einen Satz Kultistenroben zusammenbekommen.\n\nBegebt Euch nach Süden und tötet einige Zwielichtwindwirbler im Schattenriss. Abgesehen davon, dass wir sie bei dem, was sie tun, stören, bietet sich Euch die Chance, Gewandungsfetzen zu sammeln.", sourceObjective = "Hebt 8 Zwielichtkleidungsfetzen auf.", progress = "Das ist gut, {name}. Mit Helden wie Euch, die da draußen für Unruhe sorgen, werden wir den Kult von unserer Hauptinvasion ablenken.\n\nHabt Ihr eine Verkleidung?", completion = "Was habt Ihr bekommen? Ich denke, daraus können wir etwas zusammenflicken.\n\nSchließlich wollt Ihr dem Kult nicht beitreten. Wir müssen nur ein paar Oger täuschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28148] = { id = 28148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbten erlegen", description = "Die abscheuliche Verderbnis der Dämonen durchzieht den gesamten Wald. Die Erde, die Bäume, die Tiere... alle tragen die teuflische Magie in sich.\n\nWir vom Smaragdkreis haben geschworen, diesen Wald zu läutern. Das aber bedarf eines ständigen Kampfes. Vieles kann noch geheilt werden - die Bären und Wölfe jedoch, die in der Nähe umherstreifen, sind bereits zu verderbt.\n\nWir müssen ihr Leiden beenden und sicherstellen, dass Ihre Kadaver die Verderbnis nicht noch weiter verbreiten. Jagt sie und bringt mit ihre Bälge.", sourceObjective = "Sammelt 10 verderbte Pelze von Wutklauenbären oder Teufelspfotenwölfen.", progress = "Ich muss die Pelze haben, um sie von der verbliebenen dämonischen Essenz zu säubern.", completion = "Ich werde dafür sorgen, dass sie schnell und sicher verbrannt werden, {name}. Ich danke Euch vielmals.", sourceObjectiveStatus = "unverified-source-field" }
quests[28149] = { id = 28149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern im Wind", description = "Hört Ihr das, {class}? Stimmen aus der Höhle. Sie woll'n reden, aber sie ham keinen Atem.\n\nLasst uns 'ne Möglichkeit finden, zuzuhören. Die vom Schattenhammer, die reden mit dem Wind. Geht zum Schattenriss südlich von hier und holt den Windsprecherglücksbringer vom Lager. Er ist oben auf 'ner Steinsäule.\n\nWir brauchen auch Atem von Elementaren! Tötet die Sturmvortex und nehmt Euch, was Ihr braucht.", sourceObjective = "Beschafft einen Windsprecherglücksbringer und 5 Vortexhauche.", progress = "Pschscht, {name}! Hört mal. Hört mal...", completion = "Das isses, Mann.\n\nHört Ihr sie jetzt? Die Geister, sie sprechen, aber sie sagen nix gutes.\n\nHolen wir sie ans Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28150] = { id = 28150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein arkaner Verbündeter", description = "Der Smaragdkreis hat geschworen, die Hilfe aller anzunehmen, welche die Dämonen des Teufelswalds zu bekämpfen wünschen. Obwohl die arkanen Künste bei meinem Volk lange verpönt waren, können wir uns einen derartigen Vorteil hier nicht versagen.\n\nArkanistin Delaris, eine überlebende Magierin der Hochgeborenen, hilft uns im Kampf gegen die Jadefeuersatyrn. Folgt der Straße nach Norden und Ihr findet sie in unserem Lager, das die Ruinen von Constellas überblickt.\n\nWenn es Euer Wunsch ist, bei der Läuterung des Teufelswalds mitzuwirken, erfüllt ihre Wünsche, wie ihr meine erfüllt habt.", sourceObjective = "Sprecht mit Arkanistin Delaris bei den Ruinen von Constellas.", completion = "Wir haben nicht viel Zeit für Unterhaltungen, {class}. Die Druiden kämpfen tapfer gegen die Satyrn, aber teuflische Magien versperren ihnen den Weg.\n\nZum Glück habe ich einen Plan...", sourceObjectiveStatus = "unverified-source-field" }
quests[28151] = { id = 28151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todschick", description = "Eure Verkleidung ist fertig, {name}. Wenn Ihr in Zukunft nach Norden zu Stopfwampes Anhöhe geht, werden Eure Schattenhammerabzeichen die Oger täuschen.\n\nDer Rest des Plans ist einfach: Ihr tötet ein paar Stopfwampenoger und sie machen den Kult dafür verantwortlich. Seid Ihr bereit, um in dem Ogercamp Verwirrung zu stiften? Das dachte ich mir.", sourceObjective = "Tötet 10 Stopfwampenoger. Eure Schattenhammerverkleidung wird automatisch angelegt, wenn Ihr auf Stopfwampes Anhöhe seid.", completion = "Ha! Ich bin sicher, dass der Schattenhammer diese Oger zu ihren Rängen zählen wollte. Jetzt müssen sie sich wahrscheinlich gegen sie wehren.\n\nDas ist gut, {name}. Ein gut platzierter {class} hat die Arbeit einer kleinen Armee verrichtet. Ich werde Kriegsfürst Krogg über Eure Arbeit hier unterrichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28152] = { id = 28152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaedenar wartet", description = "Die Kultisten, die Ihr als Wachen der Klaue gesehen habt, waren Mitglieder des Schattenrats - widerliche Hexenmeister, die hinter fast jedem Versuch stecken, Dämonen nach Azeroth zu holen.\n\nNördlich von hier ist Jaedenar, das seinen Namen zu Ehren von Kil'jaeden erhielt. Tief darunter erstreckt sich die Schattenfeste, ein früherer Grabhügel und die Festung des Schattenrats hier auf Azeroth.\n\nBringt diese Kräuter nach Norden zu Wildherzens Lager auf der Ostseite der Straße. Greta Mooshuf wird sie für ihren Plan brauchen, die Schattenfeste endgültig zu säubern.", sourceObjective = "Liefert die Arkanistenkräuter bei Greta Mooshuf in Wildherzens Lager ab.", progress = "Seid gegrüßt, {class}. Was führt Euch her?", completion = "Ah, darauf habe ich gewartet. Mit diesen Kräutern sind die Vorbereitungen für Jaedenar beinahe abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28153] = { id = 28153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlord Fel'dan", description = "Schattenlord Fel'dan wartet noch tiefer drinnen, {name}.\n\nSein Zorn wird unvergleichlich sein, da Ihr seine Lieblinge getötet habt. Doch auch ohne Moora und Salia an seiner Seite ist er eine nicht zu unterschätzende Macht.\n\nHütet Euch vor seinen dunklen Kräften, er ist inzwischen beinahe mehr Dämon als Orc.", sourceObjective = "Tötet Schattenlord Fel'dan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28154] = { id = 28154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matschkiemes Flosse oder so...", description = "Das sieht wie Matschkiemes Flosse oder so was aus. Vielleicht gibt es jemanden, den es kümmert, dass Ihr diesen Murloc im Lager am Azurschacht getötet habt. Vielleicht auch nicht, aber einen Versuch ist es wert.\n\nBringt Matschkiemes Rückenflosse oder was immer es auch sein mag zu Hauptmann Keyton am Azurschacht im südwestlichen Hügelland.", sourceObjective = "Liefert Matschkiemes Flosse bei Hauptmann Keyton am Azurschacht im Vorgebirge des Hügellands ab.", progress = "Seh' ich wie ein Murlocforscher aus?", completion = "Matschkieme sagt Ihr. Nie von ihm gehört. Was ist das hier überhaupt? Eine Art Flosse oder so was?", sourceObjectiveStatus = "unverified-source-field" }
quests[28155] = { id = 28155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Schattenfluch", description = "Jetzt lauert nur noch eine Macht in den Tiefen der Schattenfeste: Lord Schattenfluch.\n\nDer Schattenrat hier ist ihm zu Willen und sogar Fel'dan war nur ein Werkzeug für ihn, um dieses Land für eine weitere Invasion der Brennenden Legion vorzubereiten.\n\nSeid auf der Hut, {name}. Ein Schreckenslord ist ein furchterregender Gegner. Seid standhaft und triumphiert!", sourceObjective = "Tötet Lord Schattenfluch.", completion = "Wirklich unfassbar, {name}. Sich einfach in die Höhle des Löwen zu begeben und jeden Feind zu töten, der sich einem in den Weg stellt... Ich bin überwältigt.\n\nDer Smaragdkreis dankt Euch für Eure Arbeit hier im Teufelswald. Was Andalar betrifft, werde ich Späher zu seiner Rettung entsenden. Wir werden ihm einen Heldenempfang bereiten.", sourceObjectiveStatus = "unverified-source-field" }
